const scenaFantasmi = new THREE.Scene();
scenaFantasmi.add(ghostMesh);

/** disegna i fantasmi sopra l'immagine finita, fuori dal post-processing */
function fantasmiSopraTutto() {
  if (!ghostMesh.count) return;
  renderer.setRenderTarget(null);
  const auto = renderer.autoClear;
  renderer.autoClear = false;              // o cancellerebbe l'immagine appena composta
  renderer.render(scenaFantasmi, camera);
  renderer.autoClear = auto;
}
/** questa cellula va nascosta dalla radiografia in corso? */
function nascostaDaRadiografia(c) {
  return !!tipoEvidenziato && c.creature === world.selected && c.type !== tipoEvidenziato;
}

/* --- sincronizzazione istanze ---------------------------------------- */
const _mat = new THREE.Matrix4();
const _fantasmi = [];
function syncInstances(world) {
  for (const m of meshList) m.userData.cells.length = 0;
  _fantasmi.length = 0;
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;      // solo il recipiente attivo
    for (const cr of v.creatures) {
      const inSkin = cr._blobbed;
      if (inSkin && !skinX) continue;                    // «Skin only»: nessuna cellula dentro
      for (const c of cr.cells) {
        if (c.dead || c._coperta) continue;              // già dentro una pelle o un poliedro
        if (inSkin && isSkinCell(c)) continue;           // il rivestimento È la membrana
        // radiografia: al posto della cellula nascosta resta il suo ovale
        if (nascostaDaRadiografia(c)) { _fantasmi.push(c); continue; }
        (cellMeshes[c.type] || cellMeshes.nutrient).userData.cells.push(c);
        if (pupilMeshes[c.type]) pupilMeshes[c.type].userData.cells.push(c);
      }
    }
    for (const f of v.food) cellMeshes.nutrient.userData.cells.push(f);
  }
  // nel reticolo le sfere si rimpiccioliscono per lasciar vedere le travi
  const shrink = renderMode === 'lattice' ? .62 : 1;
  // col tempo fermo l'orologio non avanza: la taglia e la luce restano quelle
  if (!tempoFermo) uCellTime.value = performance.now() * .001;
  const nowSec = uCellTime.value;
  for (let mi = 0; mi < meshList.length; mi++) {
    let mesh = meshList[mi];
    const cells = mesh.userData.cells;
    if (cells.length > mesh.instanceMatrix.count) {
      const id = mesh.userData.type;
      const kept = cells;
      mesh = growMesh(id, cells.length);
      mesh.userData.cells = kept;
      meshList[mi] = mesh;
    }
    for (let i = 0; i < cells.length; i++) {
      const c = cells[i];
      let s = c.type === 'nutrient' ? c.r
            : (c.creature && c.creature._blobbed) ? c.r * .84     // organi sospesi nel tessuto
            : c.r * shrink;
      let px = c.pos.x, py = c.pos.y, pz = c.pos.z;
      const cr = c.creature;
      if (cr && cr.alive) {
        if (c.def.thrust) {
          const b = battitoCiliare(c, _v3);
          px = _v3.x; py = _v3.y; pz = _v3.z;
          s *= 1 + .18 * b;
        } else if (c.def.power && c.stim > .02) {
          s *= 1 + .14 * c.stim;                          // la fibra si gonfia contraendosi
        }
        const pz2 = cellPulse(c, nowSec);
        s *= pz2.s;
      }
      if (c.def) s *= SIZE_MUL[c.def.cat] || 1;
      // Ogni cellula è un ovale orientato sul proprio asse: di norma quello
      // lungo cui il tessuto è cresciuto — verso la cellula madre — e per le
      // costole quello dell'arco della gabbia. Le armi si allungano molto di
      // più, così hanno una punta invece di essere biglie.
      if (c.def && cr) {
        const { kl: lungo, kt: largo } = elongDi(c.def);
        asseCellula(c, cr, _v1, px, py, pz);
        _q1.setFromUnitVectors(_up, _v1);
        _v2.set(s * largo, s * lungo, s * largo);
        _v3.set(px, py, pz);
        _mat.compose(_v3, _q1, _v2);
      } else {
        _mat.makeScale(s, s, s);
        _mat.setPosition(px, py, pz);
      }
      mesh.setMatrixAt(i, _mat);
      const t = cellTint(c, world);                     // qui è un moltiplicatore
      const lum = (cr && cr.alive && c.def) ? cellPulse(c, nowSec).b : 1;
      mesh.instanceColor.setXYZ(i, t.r * lum, t.g * lum, t.b * lum);
    }
    mesh.count = cells.length;
    mesh.instanceMatrix.needsUpdate = true;
    mesh.instanceColor.needsUpdate = true;
  }
  disegnaFantasmi(nowSec, shrink);
  syncPupils(world);
}

/**
 *  Gli ovali al posto delle cellule che la radiografia nasconde.
 *
 *  Stessa forma della cellula vera — asse di crescita, allungamento del tipo,
 *  pulsazione — perche' e' la sagoma a dire cosa c'era. Solo il materiale
 *  cambia: grigio, un decimo di opacita', sempre sopra.
 */
function disegnaFantasmi(nowSec, shrink) {
  let i = 0;
  const cap = ghostMesh.instanceMatrix.count;
  for (const c of _fantasmi) {
    if (i >= cap) break;
    const cr = c.creature;
    let s = c.r * shrink;
    if (cr && cr.alive) s *= cellPulse(c, nowSec).s;
    if (c.def) s *= SIZE_MUL[c.def.cat] || 1;
    const { kl: lungo, kt: largo } = elongDi(c.def);
    asseCellula(c, cr, _v1);
    _q1.setFromUnitVectors(_up, _v1);
    _v2.set(s * largo, s * lungo, s * largo);
    _v3.set(c.pos.x, c.pos.y, c.pos.z);
    _mat.compose(_v3, _q1, _v2);
    ghostMesh.setMatrixAt(i, _mat);
    i++;
  }
  ghostMesh.count = i;
  if (i) ghostMesh.instanceMatrix.needsUpdate = true;
}

/* --- reticolo: travi fra cellule legate -------------------------------
 *  Ogni mezza trave appartiene alla cellula da cui parte, e ne porta il
 *  MATERIALE, texture compresa: la trave dev'essere una cellula stirata, non
 *  un pezzo di tubo estraneo. Serve quindi un'istanziata per tipo, come per le
 *  sfere — un materiale solo non potrebbe portare 29 texture diverse.
 *
 *  Le UV arrivano dalla CylinderGeometry e vanno usate a scala 1: orizzontale
 *  attorno al fusto, verticale lungo l'asse, esattamente come sulla sfera dove
 *  la u gira attorno e la v va da polo a polo. Le fibre restano longitudinali.
 * ---------------------------------------------------------------------- */
caricaDisegni();          // gli abbinamenti tuoi decidono quali disegni servono
generaTexture();          // ora esistono tutti i materiali: si può cominciare
scopriDisegni().then(aggiornaMenuDisegno);   // il menù si riempie appena si sa cosa c'è
const _up = new THREE.Vector3(0, 1, 0);
// più spicchi di prima: con una texture addosso sette facce si vedevano tutte
const strutGeo = new THREE.CylinderGeometry(1, 1, 1, 12, 1, true);
const strutMeshes = {};
const _strutBuf = {};

function ensureStrut(id, n) {
  let m = strutMeshes[id];
  if (m && m.instanceMatrix.count >= n) return m;
  if (m) { scene.remove(m); m.dispose(); }
  const cap = Math.max(48, Math.ceil(n * 1.6));
  m = new THREE.InstancedMesh(strutGeo, cellMats[id] || cellMats.nutrient, cap);
  m.castShadow = true; m.receiveShadow = true; m.frustumCulled = false;
  m.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  m.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(cap * 3).fill(1), 3);
  m.instanceColor.setUsage(THREE.DynamicDrawUsage);
  scene.add(m);
  strutMeshes[id] = m;
  return m;
}

function syncStruts(world) {
  if (renderMode !== 'lattice') {
    for (const id in strutMeshes) strutMeshes[id].count = 0;
    return;
  }
  for (const id in _strutBuf) _strutBuf[id].length = 0;
  // raccoglie le mezze travi raggruppate per tipo della cellula di partenza
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) for (const con of cr.constraints) {
      if (!con.direct || con.a.dead || con.b.dead) continue;
      for (let h = 0; h < 2; h++) {
        const cell = h ? con.b : con.a;
        if (nascostaDaRadiografia(cell)) continue;      // radiografia: mezza trave in meno
        const id = cellMats[cell.type] ? cell.type : 'nutrient';
        (_strutBuf[id] || (_strutBuf[id] = [])).push(con, h);
      }
    }
  }
  const nowSec = uCellTime.value;
  for (const id in _strutBuf) {
    const buf = _strutBuf[id];
    const mesh = ensureStrut(id, buf.length / 2);
    let i = 0;
    for (let k = 0; k < buf.length; k += 2) {
      const con = buf[k], h = buf[k + 1];
      const a = con.a, b = con.b;
      _v1.copy(b.pos).sub(a.pos);
      const len = _v1.length();
      if (len < 1e-5 || i >= mesh.instanceMatrix.count) continue;
      _q1.setFromUnitVectors(_up, _v2.copy(_v1).multiplyScalar(1 / len));
      const rad = Math.min(a.r, b.r) * .46;
      const cell = h ? b : a;
      _v3.copy(a.pos).addScaledVector(_v1, h ? .75 : .25);
      _v4.set(rad, len * .5, rad);
      _m4.compose(_v3, _q1, _v4);
      mesh.setMatrixAt(i, _m4);
      // instanceColor è un moltiplicatore sul colore del materiale, come per
      // le sfere: qui va la tinta (ferite, selezione) e il battito nervoso
      const t = cellTint(cell, world);
      const lum = (cell.creature && cell.creature.alive && cell.def) ? cellPulse(cell, nowSec).b : 1;
      mesh.instanceColor.setXYZ(i, t.r * lum, t.g * lum, t.b * lum);
      i++;
    }
    mesh.count = i;
    mesh.instanceMatrix.needsUpdate = true;
    mesh.instanceColor.needsUpdate = true;
  }
  for (const id in strutMeshes) if (!_strutBuf[id] || !_strutBuf[id].length) strutMeshes[id].count = 0;
}

/* --- tessuto: metaball con marching cubes ----------------------------------
 *  Ogni cellula deposita nel campo scalare una sorgente 1/d²; dove i campi si
 *  sommano le cellule fondono in una superficie continua. La palette accumula
 *  il colore pesato di ogni cellula e la normalizziamo noi (la libreria non lo
 *  fa: dove le sfere si sovrappongono i colori saturerebbero a bianco).
 * ------------------------------------------------------------------------ */
// Livelli di dettaglio: si sceglie la DIMENSIONE DEL VOXEL in unità di mondo,
// non il numero di celle della griglia. Così un esserino piccolo non spreca
// risoluzione e uno grande non la perde. Il costo del marching cubes cresce col
// cubo della risoluzione, quindi ogni livello ha un tetto, e il tetto si abbassa
// quando i corpi da ricostruire sono tanti.
// voxel espresso in unità di mondo; una cellula ha raggio ~0.1, quindi il
// numero fra parentesi è quanti voxel coprono il raggio di una cellula
const QUALITY = [
  { name: 'low',   voxel: .075, cap: 40 },   // ~1.3 voxel per raggio cellulare
  { name: 'medium', voxel: .050, cap: 56 },   // ~2.0
  { name: 'high',  voxel: .036, cap: 72 },   // ~2.8
  { name: 'ultra', voxel: .026, cap: 96 },   // ~3.8
];
let quality = 2;                     // 'alto' di default
let skinX = true;                    // pelle semitrasparente, organi interni a vista (vedi RENDER_CHIAVE)

/** cellule che formano il rivestimento esterno: sono loro a fare da membrana */
function isSkinCell(c) { return c.def.zone === 'shell'; }

const blobMatSolid = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, vertexColors: true, roughness: .33, metalness: 0,
  clearcoat: .92, clearcoatRoughness: .2, sheen: .5, sheenColor: new THREE.Color(0xffd8e4),
  envMapIntensity: 1.05,
});
// membrana: sottile, bagnata, lascia intravedere gli organi che stanno dentro
const blobMatSkin = new THREE.MeshPhysicalMaterial({
  color: 0xffffff, vertexColors: true, transparent: true, opacity: .3,
  roughness: .16, metalness: 0, clearcoat: 1, clearcoatRoughness: .1,
  sheen: .85, sheenColor: new THREE.Color(0xcfeaff),
  side: THREE.DoubleSide, depthWrite: false, envMapIntensity: 1.6,
});
// Fresnel: una membrana sottile è quasi invisibile di fronte e densa di taglio.
// Senza questo si vedono gli organi ma non si percepisce la pelle attorno.
applyLiquid(blobMatSkin, .012, .85, true);
applyLiquid(blobMatSolid, .010, .35, false);
/*  Il disegno della pelle si aggiunge SOPRA l'aspetto liquido, incatenandosi
 *  al suo `onBeforeCompile`: vedi `vestiPelle`. */
vestiPelle(blobMatSkin);
blobMatSkin.normalScale.set(1, 1);      // il rilievo del disegno, governato dal pannello

const MAX_BLOBS = 8;
const BLOB_SUB = 24;                 // governa l'ampiezza dell'influenza di ogni cellula
const blobPool = [];
let blobFrame = 0;

function getBlob(i, res) {
  let mc = blobPool[i];
  if (mc && mc.userData.res === res) return mc;
  if (mc) { scene.remove(mc); mc.geometry.dispose(); }
  // il numero di triangoli scala con la superficie, quindi con res²
  const maxTris = clamp(Math.round(res * res * 8), 12000, 90000);
  mc = new MarchingCubes(res, blobMatSolid, false, true, maxTris);
  mc.receiveShadow = true;
  mc.frustumCulled = false;
  mc.userData.res = res;
  mc.userData.w = new Float32Array(mc.size3);      // pesi per normalizzare i colori
  mc.userData.bb = new Int32Array(6);              // voxel toccati, per non scorrere tutto
  scene.add(mc);
  blobPool[i] = mc;
  return mc;
}

/** ingombro attuale del corpo, in coordinate di mondo */
function creatureBox(cr) {
  let minx = Infinity, miny = Infinity, minz = Infinity;
  let maxx = -Infinity, maxy = -Infinity, maxz = -Infinity, maxr = 0, n = 0;
  for (const c of cr.cells) {
    if (c.dead) continue;
    n++;
    if (c.pos.x < minx) minx = c.pos.x; if (c.pos.x > maxx) maxx = c.pos.x;
    if (c.pos.y < miny) miny = c.pos.y; if (c.pos.y > maxy) maxy = c.pos.y;
    if (c.pos.z < minz) minz = c.pos.z; if (c.pos.z > maxz) maxz = c.pos.z;
    if (c.r > maxr) maxr = c.r;
  }
  if (!n) return null;
  return {
    cx: (minx + maxx) * .5, cy: (miny + maxy) * .5, cz: (minz + maxz) * .5,
    half: Math.max(maxx - minx, maxy - miny, maxz - minz) * .5 + maxr * 1.9 + .02,
  };
}

/** risoluzione della griglia per questo corpo, con isteresi per non riallocare */
function pickRes(i, half, count, focused) {
  const q = QUALITY[quality];
  let cap = q.cap;
  if (!focused) cap = Math.min(cap, 32);              // in panoramica bastano pochi voxel
  else if (count > 4) cap = Math.min(cap, 44);
  else if (count > 2) cap = Math.min(cap, 64);
  const ideal = clamp(Math.round(2 * half / q.voxel / 8) * 8, 16, cap);
  const slot = blobPool[i];
  // isteresi solo contro il respiro del corpo: se l'utente cambia livello si applica subito
  if (slot && slot.userData.q === quality && slot.userData.res <= cap
      && Math.abs(slot.userData.res - ideal) < 10) return slot.userData.res;
  return ideal;
}

/** deposita una cellula nel campo, con il suo colore pesato */
function stampCell(mc, bx, by, bz, rn, cr, cg, cb, ax, ay, az, kl, kt) {
  const size = mc.size, size2 = mc.size2, field = mc.field, pal = mc.palette;
  const W = mc.userData.w, bb = mc.userData.bb;
  const strength = rn * rn * (mc.isolation + BLOB_SUB);
  const rBase = Math.sqrt(strength / BLOB_SUB);          // raggio d'influenza isotropo
  const radiusN = rBase * Math.max(kl, kt);              // la scatola deve coprire l'ovale
  const radius = size * radiusN;
  const ikl2 = 1 / (kl * kl), ikt2 = 1 / (kt * kt);
  const xs = bx * size, ys = by * size, zs = bz * size;
  const minz = Math.max(0, Math.ceil(zs - radius)), maxz = Math.min(size - 1, Math.floor(zs + radius));
  const miny = Math.max(0, Math.ceil(ys - radius)), maxy = Math.min(size - 1, Math.floor(ys + radius));
  const minx = Math.max(0, Math.ceil(xs - radius)), maxx = Math.min(size - 1, Math.floor(xs + radius));
  if (minx < bb[0]) bb[0] = minx; if (maxx > bb[1]) bb[1] = maxx;
  if (miny < bb[2]) bb[2] = miny; if (maxy > bb[3]) bb[3] = maxy;
  if (minz < bb[4]) bb[4] = minz; if (maxz > bb[5]) bb[5] = maxz;
  const invR = 1 / rBase;
  for (let z = minz; z <= maxz; z++) {
    const fz = z / size - bz, zo = size2 * z;
    for (let y = miny; y <= maxy; y++) {
      const fy = y / size - by, yo = zo + size * y;
      for (let x = minx; x <= maxx; x++) {
        const fx = x / size - bx;
        // distanza ellissoidale: allungata lungo l'asse della cellula
        const pr = fx * ax + fy * ay + fz * az;
        const qx = fx - pr * ax, qy = fy - pr * ay, qz = fz - pr * az;
        const d2 = pr * pr * ikl2 + (qx * qx + qy * qy + qz * qz) * ikt2;
        const val = strength / (1e-6 + d2) - BLOB_SUB;
        if (val <= 0) continue;                          // fuori influenza: qui t < 1 sempre
        const i = yo + x;
        field[i] += val;
        const t = Math.sqrt(d2) * invR;
        const w0 = 1 - t * t * t * (t * (t * 6 - 15) + 10);
        // peso cubico: sulla superficie vince nettamente la cellula più vicina,
        // così ogni cellula tiene la sua faccia colorata invece di sbiadire
        const w = w0 * w0 * w0;
        const j = i * 3;
        pal[j] += cr * w; pal[j + 1] += cg * w; pal[j + 2] += cb * w;
        W[i] += w;
      }
    }
  }
}

function buildBlob(mc, cr, world, box) {
  mc.position.set(box.cx, box.cy, box.cz);
  mc.scale.setScalar(box.half);
  mc.reset();
  const W = mc.userData.w, pal = mc.palette, bb = mc.userData.bb, size = mc.size;
  W.fill(0);
  bb[0] = bb[2] = bb[4] = size; bb[1] = bb[3] = bb[5] = -1;

  const inv = .5 / box.half;                             // mondo -> normalizzato 0..1
  for (const c of cr.cells) {
    if (c.dead) continue;
    const t = cellTint(c, world), base = cellBaseColor[c.type];
    // stesso asse delle altre modalità: dal centro della madre alla cellula
    asseCellula(c, cr, _v1);
    const { kl, kt } = elongDi(c.def);
    const p = cellPulse(c, uCellTime.value);
    stampCell(mc,
      (c.pos.x - box.cx) * inv + .5, (c.pos.y - box.cy) * inv + .5, (c.pos.z - box.cz) * inv + .5,
      c.r * inv * .96 * p.s * (SIZE_MUL[c.def.cat] || 1),
      base.r * t.r * p.b, base.g * t.g * p.b, base.b * t.b * p.b,
      _v1.x, _v1.y, _v1.z, kl, kt);
  }
  // media pesata del colore (la libreria somma e basta: si saturerebbe a bianco)
  for (let z = bb[4]; z <= bb[5]; z++) {
    const zo = mc.size2 * z;
    for (let y = bb[2]; y <= bb[3]; y++) {
      const yo = zo + size * y;
      for (let x = bb[0]; x <= bb[1]; x++) {
        const i = yo + x, w = W[i];
        if (w > 1e-6) { const j = i * 3, k = 1 / w; pal[j] *= k; pal[j + 1] *= k; pal[j + 2] *= k; }
      }
    }
  }
  mc.update();
}

function syncBlobs(world, force) {
  for (const v of world.vessels) for (const cr of v.creatures) cr._blobbed = false;
  world._blobRes = 0;
  if (renderMode !== 'blob' || !MarchingCubes) {
    for (const b of blobPool) if (b) b.visible = false;
    return;
  }
  const list = [];
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) if (cr.cells.some(c => !c.dead)) list.push(cr);
  }
  // il tessuto si ricalcola a 30 Hz, a 20 Hz se la griglia è molto fitta
  const period = (world._blobResPrev || 0) > 72 ? 3 : 2;
  const update = force || (blobFrame++ % period) === 0;
  /*  UNA PELLE SOLA per tutt'e due le voci del menu.
   *  Le due modalita' non sono due materiali diversi: sono la STESSA pelle,
   *  e a cambiare e' soltanto se le cellule di dentro si disegnano o no. */
  const mat = blobMatSkin;
  let i = 0;
  for (const cr of list) {
    if (i >= MAX_BLOBS) break;
    const box = creatureBox(cr);
    if (!box) continue;
    const mc = getBlob(i, pickRes(i, box.half, list.length, !!world.focus));
    mc.userData.q = quality;
    mc.visible = true;
    mc.material = mat;
    /*  L'ombra segue l'OPACITA', non la modalita': una membrana traslucida non
     *  fa ombra piena, una pelle chiusa si'. Prima seguiva la voce del menu, ma
     *  ora le due voci hanno lo stesso materiale e sarebbe stato un residuo. */
    mc.castShadow = blobMatSkin.opacity > .92;
    cr._blobbed = true;                                  // gli altri restano a sfere
    if (mc.userData.res > world._blobRes) world._blobRes = mc.userData.res;
    // se la griglia è appena nata o è passata a un altro esserino va ricostruita
    // subito, altrimenti per un fotogramma mostrerebbe il corpo sbagliato
    const stale = mc.userData.owner !== cr;
    mc.userData.owner = cr;
    if (update || stale) buildBlob(mc, cr, world, box);
    i++;
  }
  for (; i < blobPool.length; i++) if (blobPool[i]) blobPool[i].visible = false;
  world._blobResPrev = world._blobRes;
}

/* --- modalità "mesh": unione esatta di ellissoidi, senza griglia ---------
 *  Le cellule dello stesso tipo attaccate fra loro formano un organo, e
 *  l'organo diventa la loro UNIONE geometrica: la superficie esatta del
 *  solido che occupano, saldature comprese.
 *
 *  Niente marching cubes. Il costo di una griglia cresce col cubo della
 *  risoluzione e restituisce comunque una superficie approssimata; qui invece
 *  la superficie si risolve in forma chiusa, e costa quanto i vertici che si
 *  disegnano.
 *
 *  Il metodo. Ogni cellula presta la sua sfera geodetica di riferimento. Per
 *  ogni direzione, si tira un raggio dal centro della cellula e si cerca dove
 *  ESCE dall'unione: si parte dall'uscita dalla propria superficie e finché
 *  quel punto cade dentro un'altra cellula lo si sposta all'uscita di
 *  quella. Bastano poche passate perché un gruppo ha poche cellule. Il punto
 *  che si ottiene sta esattamente sull'unione, e si sa anche a QUALE cellula
 *  appartiene.
 *
 *  Ogni cellula disegna poi soltanto i triangoli che le appartengono. Dove un
 *  triangolo è a cavallo di una saldatura, si dimezza la direzione dei suoi
 *  vertici finché l'appartenenza cambia: il vertice così trovato cade sulla
 *  curva d'intersezione, e le due cellule confinanti ci arrivano da entrambi
 *  i lati. Le calotte si incastrano quindi lungo il bordo esatto.
 *
 *  Le normali sono analitiche — il gradiente dell'ellissoide nel punto — non
 *  ricavate da un campo campionato: la superficie è liscia per costruzione, e
 *  le saldature restano gli spigoli vivi che devono essere.
 * ---------------------------------------------------------------------- */
const MAX_ORGANI = 1024;
const organi = [];
let organoFrame = 0;

/**
 *  Carica sulla scheda SOLO la parte scritta dell'attributo.
 *
 *  `needsUpdate` da solo rispedisce l'intero buffer, che è dimensionato sul
 *  caso peggiore mai capitato in quello slot: con centotrenta organi, quasi
 *  tutti al dettaglio minimo, si ricaricavano ogni volta megabyte di capienza
 *  inutilizzata. Misurato, era la voce di costo dominante — non i vertici
 *  disegnati, che erano pochi.
 */
function caricaParziale(attr, n) {
  attr.needsUpdate = true;
  const q = n * attr.itemSize;
  if (attr.clearUpdateRanges) { attr.clearUpdateRanges(); attr.addUpdateRange(0, q); }
  else if (attr.updateRange) { attr.updateRange.offset = 0; attr.updateRange.count = q; }
}

/* =============================================================================
 *  MODALITÀ "MESH" — un ovale per ogni legame padre→figlio
 *
 *  Non piu' una superficie implicita per gruppo omogeneo. Ogni COPPIA di
 *  cellule legate diventa un ovale che le contiene entrambe: una capsula con
 *  le due calotte del raggio esatto delle due cellule e il fusto che sfuma da
 *  un raggio all'altro. Contiene senza gonfiare, perche' le calotte SONO le
 *  cellule, e segue l'asse di crescita perche' quell'asse e' la congiungente.
 *
 *  Il materiale sfuma da padre a figlio come nella spline, e per lo stesso
 *  motivo si riusa la sua macchina: `matSpline` porta gia' lo shader che
 *  mescola tre texture con i pesi per vertice, e `agganciaPulsazione` porta i
 *  campionatori dei vicini. Qui basta un peso solo, che corre da 0 a 1 lungo
 *  l'ovale: al polo del padre si vede la texture del padre, a quello del
 *  figlio quella del figlio, e in mezzo la mescola — colore, disegno e rilievo
 *  insieme.
 *
 *  Battito, pigmento, ferite e selezione arrivano tutti dal colore per
 *  vertice, che e' lo stesso `cellBaseColor × cellTint × battito` delle altre
 *  modalita'; l'ondeggio di membrana lo fa lo shader, a cui basta sapere in
 *  che scala e' scritta la geometria (`wobK`).
 * ========================================================================== */
/*  UN MATERIALE PER COPPIA DI TIPI, non uno condiviso con uniformi mutati.
 *
 *  Il primo tentativo riusava il materiale della spline e gli passava le due
 *  texture attraverso uniformi CONDIVISI, riscritti in `onBeforeRender` per
 *  ogni ovale. Non funziona, e il sintomo lo dice: three NON ricarica gli
 *  uniformi fra due disegni consecutivi che usano lo stesso materiale
 *  (`_currentMaterialId` invariato ⇒ niente refresh). Tutti gli ovali con lo
 *  stesso tipo di padre condividevano quindi le texture del PRIMO disegnato,
 *  e bastava ruotare la vista — che cambia l'ordine di disegno — perché
 *  cambiasse quale ovale detta la texture a tutti gli altri.
 *
 *  Qui ogni coppia (padre, figlio) ha il suo materiale, con i suoi uniformi.
 *  Il programma resta uno solo, perché la chiave di cache non cambia, ma il
 *  cambio di materiale fra un disegno e l'altro obbliga three a rispedire gli
 *  uniformi — che è esattamente ciò che serviva.
 *
 *  Le proprietà fisiche (ruvidità, metallo, vernice…) sono quelle del PADRE:
 *  un solo materiale non puo' interpolarle per frammento. A sfumare sono il
 *  colore, il disegno e il rilievo, che è quel che si vede.
 */
const ovaleMats = new Map();
const ovaleMatsPerTipo = {};

function matOvale(tipoA, tipoB) {
  const chiave = tipoA + '|' + tipoB;
  let m = ovaleMats.get(chiave);
  if (m) {
    // texture e proprietà possono essere cambiate dal pannello o da una ricarica
    const d = cellMats[tipoB] || cellMats.nutrient;
    m.userData.uTexB.value = cellTextures[tipoB] || TEX_VUOTA;
    m.userData.uNrmB.value = cellNormals[tipoB] || NRM_VUOTA;
    m.userData.uRugB.value = d.roughness; m.userData.uMetB.value = d.metalness;
    m.userData.uVerB.value = d.clearcoat; m.userData.uVerRB.value = d.clearcoatRoughness;
    return m;
  }
  const base = cellMats[tipoA] || cellMats.nutrient;
  m = base.clone();
  m.vertexColors = true;
  m.color.setHex(0xffffff);                    // il colore lo porta il vertice
  const uTexB = { value: cellTextures[tipoB] || TEX_VUOTA };
  const uNrmB = { value: cellNormals[tipoB] || NRM_VUOTA };
  /*  Anche le proprietà FISICHE del figlio, non solo il suo disegno.
   *
   *  È la parte che mancava: al giunto due ovali mostravano ormai lo stesso
   *  colore e la stessa texture, ma uno restava opaco e l'altro lucido perché
   *  la ruvidità era quella del rispettivo padre. Due superfici che si
   *  compenetrano con riflessi diversi si vedono eccome, ed è l'artefatto a
   *  denti di sega dello screenshot. Passandole come uniformi del materiale di
   *  coppia — che sono suoi, non condivisi — si possono mescolare per
   *  frammento con lo stesso peso del resto. */
  const dB = cellMats[tipoB] || cellMats.nutrient;
  const uRugB = { value: dB.roughness }, uMetB = { value: dB.metalness };
  const uVerB = { value: dB.clearcoat }, uVerRB = { value: dB.clearcoatRoughness };
  m.userData.uTexB = uTexB; m.userData.uNrmB = uNrmB;
  m.userData.uRugB = uRugB; m.userData.uMetB = uMetB;
  m.userData.uVerB = uVerB; m.userData.uVerRB = uVerRB;
  m.userData.tipoB = tipoB;
  // il clone non porta gli agganci allo shader del padre: vanno rimessi, o
  // l'ovale perde ondeggio, Fresnel ed emissione pulsante
  const baseFn = base.onBeforeCompile;
  m.onBeforeCompile = sh => {
    baseFn(sh);
    sh.uniforms.uTexB = uTexB;
    sh.uniforms.uNrmB = uNrmB;
    sh.uniforms.uRugB = uRugB; sh.uniforms.uMetB = uMetB;
    sh.uniforms.uVerB = uVerB; sh.uniforms.uVerRB = uVerRB;
    sh.vertexShader = 'attribute vec2 aMix;\nvarying float vMixB;\n' + sh.vertexShader;
    sh.vertexShader = sh.vertexShader.replace('#include <begin_vertex>',
      'vMixB = aMix.y;\n#include <begin_vertex>');
    sh.fragmentShader = 'uniform sampler2D uTexB;\nuniform sampler2D uNrmB;\nvarying float vMixB;\n'
                      + 'uniform float uRugB;\nuniform float uMetB;\n'
                      + 'uniform float uVerB;\nuniform float uVerRB;\n'
                      + sh.fragmentShader;
    sh.fragmentShader = sh.fragmentShader.replace('#include <map_fragment>', `
      #ifdef USE_MAP
        vec4 tex = texture2D( map, vMapUv );
        diffuseColor *= mix( tex, texture2D( uTexB, vMapUv ), vMixB );
      #endif
    `);
    sh.fragmentShader = sh.fragmentShader.replace('#include <roughnessmap_fragment>',
      '#include <roughnessmap_fragment>\nroughnessFactor = mix( roughnessFactor, uRugB, vMixB );');
    sh.fragmentShader = sh.fragmentShader.replace('#include <metalnessmap_fragment>',
      '#include <metalnessmap_fragment>\nmetalnessFactor = mix( metalnessFactor, uMetB, vMixB );');
    /*  La vernice sta dentro `material`, che nasce in `lights_physical_fragment`,
     *  e il suo blocco esiste solo se il materiale del PADRE ce l'ha: senza la
     *  guardia il programma non compilerebbe per i tipi senza vernice. */
    sh.fragmentShader = sh.fragmentShader.replace('#include <lights_physical_fragment>', `
      #include <lights_physical_fragment>
      #ifdef USE_CLEARCOAT
        material.clearcoat = mix( material.clearcoat, uVerB, vMixB );
        material.clearcoatRoughness = mix( material.clearcoatRoughness, uVerRB, vMixB );
      #endif
    `);

    // stessa mistura sul rilievo: se sfumasse solo il colore, la grana
    // cambierebbe di colpo e il confine resterebbe leggibile nella luce
    sh.fragmentShader = sh.fragmentShader.replace('#include <normal_fragment_maps>', `
      #ifdef USE_NORMALMAP_TANGENTSPACE
        vec3 mapN = texture2D( normalMap, vNormalMapUv ).xyz;
        mapN = mix( mapN, texture2D( uNrmB, vNormalMapUv ).xyz, vMixB );
        mapN = mapN * 2.0 - 1.0;
        mapN.xy *= normalScale;
        normal = normalize( tbn * mapN );
      #endif
    `);
  };
  m.customProgramCacheKey = () => 'ovale';
  ovaleMats.set(chiave, m);
  (ovaleMatsPerTipo[tipoA] = ovaleMatsPerTipo[tipoA] || []).push(m);
  return m;
}

const OV_LOD = [{ rad: 8, seg: 10 }, { rad: 14, seg: 16 }, { rad: 20, seg: 24 }];
const OV_CAP = OV_LOD[OV_LOD.length - 1];
/*  Quanto rientra il CENTRO della faccia rispetto alla sfera vera, per ogni
 *  livello di dettaglio. La faccia e' inclinata nei due sensi — attorno
 *  all'asse (passo 2π/rad) e lungo la calotta (passo 2π/seg) — e i due
 *  accorciamenti si moltiplicano: al centro della faccia si rientra piu' che
 *  sul lato peggiore dei due. Una calotta annidata deve stare sotto QUESTA
 *  soglia, non sotto il raggio nominale, altrimenti i suoi vertici spuntano
 *  proprio dalle rientranze dell'altra.
 *
 *  Il margine si adegua da solo: e' grande dove la tassellatura e' grossolana,
 *  cioe' dove l'ovale e' piccolo sullo schermo e quindi il gradino vale un
 *  paio di pixel, e diventa piccolo sui primi piani. */
const OV_DIP = OV_LOD.map(({ rad, seg }) =>
  Math.cos(Math.PI / rad) * Math.cos(Math.PI / seg) * .999);

function getOvale(i, lod) {
  let m = organi[i];
  const nvMax = (OV_CAP.rad + 1) * (OV_CAP.seg + 1);
  if (!m) {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(nvMax * 3), 3));
    g.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(nvMax * 3), 3));
    g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(nvMax * 2), 2));
    g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(nvMax * 3), 3));
    g.setAttribute('aMix', new THREE.BufferAttribute(new Float32Array(nvMax * 2), 2));
    g.setIndex(new THREE.BufferAttribute(new Uint16Array(OV_CAP.rad * OV_CAP.seg * 6), 1));
    m = new THREE.Mesh(g, blobMatSolid);
    m.frustumCulled = false;
    m.receiveShadow = true;
    m.userData.lod = -1;
    agganciaPulsazione(m);
    scene.add(m);
    organi[i] = m;
  }
  /*  Gli indici dipendono solo dal livello di dettaglio, non dall'ovale: si
   *  riscrivono quando quello slot cambia livello, non a ogni fotogramma. */
  if (m.userData.lod !== lod) {
    m.userData.lod = lod;
    const { rad, seg } = OV_LOD[lod];
    const idx = m.geometry.index.array;
    let k = 0;
    for (let j = 0; j < seg; j++) for (let a = 0; a < rad; a++) {
      const p0 = j * (rad + 1) + a, p1 = p0 + 1, p2 = p0 + rad + 1, p3 = p2 + 1;
      idx[k++] = p0; idx[k++] = p2; idx[k++] = p1;
      idx[k++] = p1; idx[k++] = p2; idx[k++] = p3;
    }
    m.geometry.index.needsUpdate = true;
    m.geometry.setDrawRange(0, k);
  }
  return m;
}

const _ovQ = new THREE.Quaternion(), _ovU = new THREE.Vector3();
// pose DISEGNATE dei due capi: coincidono col centro fisico tranne che per le
// ciliate, che remano
const _ovA = new THREE.Vector3(), _ovB = new THREE.Vector3();
const _ovP = new THREE.Vector3(), _ovN = new THREE.Vector3(), _ovC = new THREE.Color();

/** raggio trasversale della cellula, battito e allungamento compresi */
function raggioOvale(c) {
  const p = cellPulse(c, uCellTime.value);
  const { kt } = elongDi(c.def);
  return Math.max(1e-4, c.r * p.s * (SIZE_MUL[c.def.cat] || 1) * kt);
}

/**
 *  Scrive nella mesh l'ovale che contiene `a` (padre) e `b` (figlio).
 *  Restituisce il raggio medio, che serve allo shader per l'ondeggio.
 */
function scriviOvale(mesh, a, b, world, lod, kA) {
  const { rad, seg } = OV_LOD[lod];
  const g = mesh.geometry;
  const pos = g.attributes.position.array, nor = g.attributes.normal.array;
  const uvs = g.attributes.uv.array, col = g.attributes.color.array;
  const mix = g.attributes.aMix.array;

  /*  CALOTTE CONCENTRICHE, IN FASE E ANNIDATE.
   *
   *  Tutte le calotte che stanno su una stessa cellula sono sfere concentriche
   *  dello stesso raggio: `raggioOvale` viene chiamato sulla stessa cellula
   *  nello stesso fotogramma, quindi la pulsazione e' gia' in fase. Il guaio
   *  non e' la fase, e' che sono sfere POLIGONALI con assi diversi: le facce
   *  dell'una rientrano dove quelle dell'altra sporgono, si tagliano lungo
   *  tutta la circonferenza, e alla minima pulsazione si scambiano il posto —
   *  prima si vede una, poi l'altra.
   *
   *  Colore e normali non tradiscono lo scambio: sulla calotta la mescola e'
   *  satura, quindi le due mostrano la stessa cellula, e la normale e' radiale
   *  in entrambe. A tradirlo sono le UV, che girano attorno all'asse del
   *  PROPRIO ovale: dove le facce si incrociano, il disegno della texture si
   *  taglia con un'altra inclinazione, ed e' la dentellatura che si vedeva.
   *
   *  Due superfici coincidenti non si possono ordinare. Le annidiamo: su ogni
   *  cellula la calotta del legame col padre resta piena, e ogni legame verso
   *  un figlio si stringe di un gradino. Il gradino e' OV_DIP, cioe' la
   *  rientranza della faccia: cosi' i vertici della calotta interna finiscono
   *  sotto le facce di quella esterna e non escono piu', qualunque cosa faccia
   *  la pulsazione. Uno scarto piu' piccolo (avevo provato l'1%) non basta:
   *  resta dentro la rientranza e le facce continuano a incrociarsi.
   *
   *  Il prezzo e' il gradino visibile fra un guscio e l'altro, che infatti
   *  misurai peggiore sul contrasto del bordo. E' un baratto voluto: il bordo
   *  e' fermo, lo scambio di facce lampeggiava. */
  /*  Anche qui le ciliate remano: `posBattito` dà la posa del colpo e il
   *  gonfiamento che l'accompagna, come già fanno le modalità «Cellule» e
   *  «Spline». L'ovale si costruisce sulla posizione REMATA, non su quella
   *  fisica, o la superficie resterebbe ferma sopra una ciglia che si muove. */
  const gA = posBattito(a, _ovA), gB = posBattito(b, _ovB);
  const rA = raggioOvale(a) * gA * (kA || 1), rB = raggioOvale(b) * gB;
  _ovU.copy(_ovB).sub(_ovA);
  const L = _ovU.length();
  if (L < 1e-6) return 0;
  _ovU.multiplyScalar(1 / L);
  _ovQ.setFromUnitVectors(_up, _ovU);              // +Y -> asse padre→figlio

  // colori ai due poli: base × tinta (pigmento, ferite, selezione) × battito
  const baseA = cellBaseColor[a.type] || cellBaseColor.nutrient;
  const baseB = cellBaseColor[b.type] || cellBaseColor.nutrient;
  const tA = cellTint(a, world), pA = cellPulse(a, uCellTime.value).b;
  const cAr = baseA.r * tA.r * pA, cAg = baseA.g * tA.g * pA, cAb = baseA.b * tA.b * pA;
  const tB = cellTint(b, world), pB = cellPulse(b, uCellTime.value).b;
  const cBr = baseB.r * tB.r * pB, cBg = baseB.g * tB.g * pB, cBb = baseB.b * tB.b * pB;

  const pend = (rB - rA) / Math.max(1e-6, L);      // pendenza del fusto
  let k = 0, kc = 0, ku = 0, km = 0;
  for (let j = 0; j <= seg; j++) {
    const t = j / seg;
    /*  La mescola SATURA sulle calotte, invece di correre da 0 a 1 su tutto
     *  l'ovale.
     *
     *  Due ovali che condividono una cellula si toccano proprio lì, e la
     *  vecchia rampa lineare dava alla calotta di uno una mescola .75–1 e a
     *  quella dell'altro una .0–.25: colori e disegni leggermente diversi
     *  sulla stessa superficie, cioè la riga netta che si vedeva. Saturando
     *  fuori dal fusto, entrambe le calotte mostrano ESATTAMENTE la cellula
     *  condivisa — stesso colore, stessa texture — e il giunto sparisce. */
    /*  Satura ESATTAMENTE sul confine delle calotte (un quarto per lato, che
     *  e' come sono costruite): cosi' ogni calotta mostra la sua cellula pura,
     *  senza un residuo dell'altra, e le due che si contendono il giunto
     *  risultano identiche. Allargare oltre non serve e sposta solo il salto
     *  piu' in dentro. */
    const u = clamp((t - .25) / .5, 0, 1);
    const tb = u * u * (3 - 2 * u);
    let rr, yy, ny;
    if (t < .25) {                                  // calotta del padre
      const w = t / .25 * Math.PI * .5;
      rr = rA * Math.sin(w); yy = -rA * Math.cos(w); ny = -Math.cos(w);
    } else if (t > .75) {                           // calotta del figlio
      const w = (t - .75) / .25 * Math.PI * .5;
      rr = rB * Math.cos(w); yy = L + rB * Math.sin(w); ny = Math.sin(w);
    } else {                                        // fusto
      const q = (t - .25) / .5;
      rr = rA + (rB - rA) * q; yy = q * L; ny = -pend;
    }
    const sr = t < .25 ? Math.sin(w0(t, .25)) : t > .75 ? Math.cos(w0(t - .75, .25)) : 1;
    for (let a2 = 0; a2 <= rad; a2++) {
      const ang = a2 / rad * TAU, cs = Math.cos(ang), sn = Math.sin(ang);
      _ovP.set(cs * rr, yy, sn * rr).applyQuaternion(_ovQ).add(_ovA);
      _ovN.set(cs * sr, ny, sn * sr).applyQuaternion(_ovQ).normalize();
      pos[k] = _ovP.x; pos[k + 1] = _ovP.y; pos[k + 2] = _ovP.z;
      nor[k] = _ovN.x; nor[k + 1] = _ovN.y; nor[k + 2] = _ovN.z;
      k += 3;
      col[kc] = cAr + (cBr - cAr) * tb;
      col[kc + 1] = cAg + (cBg - cAg) * tb;
      col[kc + 2] = cAb + (cBb - cAb) * tb;
      kc += 3;
      uvs[ku] = a2 / rad; uvs[ku + 1] = t; ku += 2;   // V lungo l'asse dell'ovale
      mix[km] = 0; mix[km + 1] = tb; km += 2;         // 0 = padre, 1 = figlio
    }
  }
  const nv = (rad + 1) * (seg + 1);
  caricaParziale(g.attributes.position, nv);
  caricaParziale(g.attributes.normal, nv);
  caricaParziale(g.attributes.uv, nv);
  caricaParziale(g.attributes.color, nv);
  caricaParziale(g.attributes.aMix, nv);
  return (rA + rB) * .5;
}
/** angolo della calotta: piccola comodità per non ripetere la formula */
function w0(t, span) { return t / span * Math.PI * .5; }

function syncMesh(world) {
  if (renderMode !== 'mesh') {
    for (const m of organi) if (m) m.visible = false;
    return;
  }
  const altezzaProiezione = viewH * .5 / Math.tan(camera.fov * .5 * Math.PI / 180);
  let i = 0;
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) {
      /*  Un solo livello di dettaglio per tutto l'esserino.
       *
       *  Sceglierlo ovale per ovale spezzava l'annidamento delle calotte: due
       *  che stanno sulla stessa cellula finivano tassellate in modo diverso,
       *  e il gradino calcolato sulla rientranza di una non bastava a
       *  contenere le facce dell'altra. Con la tassellatura condivisa il
       *  confronto e' fra sfere uguali e l'ordine regge. */
      let rMed = 0, nc = 0;
      for (const c of cr.cells) if (!c.dead) { rMed += c.r; nc++; }
      if (!nc) continue;
      rMed /= nc;
      const distCr = Math.max(1e-3, camera.position.distanceTo(cr.origin));
      const pxCr = (rMed / distCr) * altezzaProiezione;
      /*  Soglie piu' basse di quando il livello si sceglieva ovale per ovale:
       *  ora ne serve uno solo per tutto l'esserino, e conviene sbagliare
       *  verso il fine — la tassellatura piu' fitta rende anche piu' stretto
       *  il gradino fra le calotte annidate. */
      const lod = pxCr > 55 ? 2 : pxCr > 18 ? 1 : 0;
      const dip = OV_DIP[lod];

      for (const c of cr.cells) {
        if (c.dead || i >= MAX_ORGANI) continue;
        const p = c.parent;
        if (!p || p.dead) continue;                 // la radice non ha un legame sopra
        // radiografia: se una delle due e' nascosta l'ovale non si disegna, e
        // nessuna delle due resta coperta — tornano come sagome trasparenti
        if (nascostaDaRadiografia(c) || nascostaDaRadiografia(p)) continue;

        /*  Ordine delle calotte sulla cellula `p`: quella del suo legame col
         *  padre tiene il raggio pieno, ogni figlio si stringe di un gradino
         *  in piu'. La calotta su `c` e' invece sempre quella del legame col
         *  padre, quindi resta piena: ogni ovale stringe un capo solo. */
        let rango = (p.parent && !p.parent.dead) ? 1 : 0;
        for (const f of p.children) { if (f === c) break; if (!f.dead) rango++; }
        /*  Un pavimento al restringimento: una cellula con molti figli, al
         *  livello piu' grossolano, si ridurrebbe a meta' e il fusto uscirebbe
         *  da dentro la cellula invece che dalla sua superficie. Oltre il
         *  pavimento le calotte tornano a coincidere — sono comunque le piu'
         *  interne, le meno esposte. */
        const kA = Math.max(.72, Math.pow(dip, rango));
        const mesh = getOvale(i, lod);
        mesh.material = matOvale(p.type, c.type);    // `map` = padre, `uTexB` = figlio
        const rM = scriviOvale(mesh, p, c, world, lod, kA);
        if (!rM) { mesh.visible = false; continue; }
        mesh.userData.wobK = rM;                     // geometria in unità di mondo
        mesh.userData.lum = (cellPulse(p, uCellTime.value).b + cellPulse(c, uCellTime.value).b) * .5;
        mesh.visible = true;
        p._coperta = true; c._coperta = true;
        i++;
      }
    }
  }
  for (; i < organi.length; i++) if (organi[i]) organi[i].visible = false;
}

/* --- modalità "spline": il corpo come rete di salsicce continue ----------
 *  Si passa una spline per i centri delle cellule e ci si estrude attorno una
 *  sezione circolare, con le estremità chiuse a calotta sferica.
 *
 *  I percorsi attraversano TUTTO l'esserino, non un tipo alla volta: padre e
 *  figlio di tipo diverso stanno sulla stessa spline. Il tubo si spezza in
 *  TRATTI solo per cambiare materiale, e due tratti adiacenti condividono
 *  esattamente lo stesso anello di vertici — stesso centro, stesso raggio,
 *  stesso riferimento — quindi la superficie prosegue senza giunte e senza
 *  cupole che chiudano il passaggio. Le calotte restano solo ai capi veri.
 *
 *  Perché gli anelli condivisi coincidano davvero, il riferimento attorno al
 *  tubo va trasportato lungo TUTTO il percorso e poi affettato: se ogni
 *  tratto ripartisse per conto suo, la sezione risulterebbe ruotata in modo
 *  diverso ai due lati del confine e i vertici non si toccherebbero.
 *
 *  Il colore segue la spline come il raggio: si interpola fra le cellule, e
 *  al confine i due tratti calcolano lo stesso valore. La tinta sfuma quindi
 *  con continuità anche dove il disegno della texture cambia.
 *
 *  Un percorso non è per forza una catena: il grafo può ramificare. Si estrae
 *  il DIAMETRO (doppia visita in ampiezza), si tolgono quei nodi e si ripete;
 *  ogni ramo si riaggancia al nodo già usato che lo tocca. A una giunzione il
 *  capo si chiude piatto, sepolto dentro la salsiccia madre: una cupola lì
 *  spunterebbe dal suo fianco.
 * ---------------------------------------------------------------------- */
/**
 *  Nessun tetto al numero di tubi: con undici esserini nel recipiente servono
 *  oltre seicento tratti, e fermandosi a novantasei i percorsi si troncavano a
 *  metà — l'ultimo tratto non disegnato lasciava scoperto l'anello di confine
 *  del precedente, ed è quella la faccia circolare piatta che si vedeva.
 *  Il tetto resta solo come rete di sicurezza contro una crescita patologica.
 */
const MAX_TUBI = 4096, TUBO_RAD = 14, TUBO_ANELLI = 72, TUBO_CALOTTA = 6, MAX_ANELLI = 256;
/*  Seno e coseno del giro della sezione: dipendono solo dall'indice radiale,
 *  quindi sono gli stessi per ogni anello, ogni tratto e ogni fotogramma.
 *  Calcolarli nel ciclo interno voleva dire quindici seni e quindici coseni per
 *  anello, moltiplicati per oltre mille tratti a fotogramma. */
const _TUBO_CO = new Float32Array(TUBO_RAD + 1), _TUBO_SI = new Float32Array(TUBO_RAD + 1);
for (let i = 0; i <= TUBO_RAD; i++) { const a = i / TUBO_RAD * TAU; _TUBO_CO[i] = Math.cos(a); _TUBO_SI[i] = Math.sin(a); }
/**
 *  Quanto si assottiglia il tubo avvicinandosi a una giunzione. Serve: lì il
 *  ramo aveva ESATTAMENTE il raggio della salsiccia madre, quindi le due
 *  superfici erano coincidenti e a ogni fotogramma vinceva l'una o l'altra nel
 *  test di profondità — è questo che si vedeva come rigenerazione continua.
 *  Rastremando, il ramo entra pulito dentro la madre e la sua chiusura, che
 *  resta sempre una cupola come tutte le altre, sparisce là dentro.
 */
const GIUNZ_R = .62;
const tubi = [];
let tuboFrame = 0, _splineT = 0;

/**
 *  Texture dei due tratti confinanti, legate prima di ogni disegno. Sono
 *  uniformi condivisi mutati in `onBeforeRender`, come la scala dell'ondeggio:
 *  i materiali sono per tipo e vanno bene per più tratti, ma i VICINI di ogni
 *  tratto sono diversi, e questo è l'unico modo per passarglieli senza
 *  moltiplicare i materiali per ogni coppia di confine possibile.
 */
const TEX_VUOTA = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
TEX_VUOTA.needsUpdate = true;
const NRM_VUOTA = new THREE.DataTexture(new Uint8Array([128, 128, 255, 255]), 1, 1);
NRM_VUOTA.needsUpdate = true;

/**
 *  Materiali dedicati: come quelli delle cellule ma col colore per vertice, che
 *  è ciò che permette alla tinta di sfumare da un tipo all'altro. Non si può
 *  accendere `vertexColors` su quelli originali: le sfere istanziate non hanno
 *  l'attributo `color` sulla geometria e diventerebbero nere.
 *
 *  Sopra ci va il raccordo fra tratti: ogni vertice porta in `aMix` quanto
 *  pesano le texture dei due vicini, e colore e rilievo si mescolano nel
 *  frammento. Al confine il peso è 0.5 da entrambi i lati — i due tratti
 *  calcolano quindi la stessa identica mistura sull'anello che condividono, e
 *  il passaggio non ha più un bordo.
 */
function matSpline(id, prima, dopo) {
  /*  UN MATERIALE PER TERNA: tipo proprio + i due vicini.
   *
   *  Le texture dei vicini viaggiavano in uniformi CONDIVISI da tutti i tratti,
   *  riscritti in `onBeforeRender` prima di ogni disegno. Il risparmio era
   *  vero — un materiale per tipo invece di uno per ogni accoppiamento
   *  possibile — ma il meccanismo non regge: three.js NON rimanda gli uniformi
   *  alla scheda fra due disegni consecutivi che usano LO STESSO materiale, e
   *  due tratti della stessa famiglia sono esattamente questo. Il secondo
   *  disegnava con i vicini del primo.
   *
   *  Si vedeva soprattutto sulle cupole: una cellula con due figli genera due
   *  pezzi con lo stesso materiale e vicini diversi, e quale dei due vincesse
   *  dipendeva dall'ordine di disegno — cioè dalla posizione della camera. Da
   *  qui lo scambio di texture ruotando attorno all'esserino.
   *
   *  Misurato su un corpo da 165 cellule: 440 pezzi serviti da 30 materiali,
   *  153 terne davvero diverse, 123 pezzi che disegnavano con i vicini di
   *  qualcun altro. Non un caso raro: un quarto del corpo.
   *
   *  Gli uniformi ora sono DEL MATERIALE, non condivisi — la stessa cura che
   *  gli ovali della modalità mesh usano già per le coppie. Il programma resta
   *  uno solo (`customProgramCacheKey` costante), quindi non si ricompila
   *  nulla: si moltiplicano gli oggetti materiale, non gli shader.
   */
  const chiave = id + '|' + (prima || '-') + '|' + (dopo || '-');
  const texA = cellTextures[prima] || TEX_VUOTA, nrmA = cellNormals[prima] || NRM_VUOTA;
  const texB = cellTextures[dopo] || TEX_VUOTA, nrmB = cellNormals[dopo] || NRM_VUOTA;
  let m = splineMats.get(chiave);
  if (m) {
    // le texture possono cambiare dal pannello dei materiali o da una ricarica
    m.userData.uMapA.value = texA; m.userData.uNrmA.value = nrmA;
    m.userData.uMapB.value = texB; m.userData.uNrmB.value = nrmB;
    return m;
  }
  {
    const base = cellMats[id] || cellMats.nutrient;
    m = base.clone();
    m.vertexColors = true;
    m.color.setHex(0xffffff);        // il colore lo porta il vertice
    // clone() non porta con sé gli agganci allo shader: vanno rimessi a mano,
    // altrimenti il tratto perde ondeggio, Fresnel ed emissione pulsante
    const uA = { value: texA }, unA = { value: nrmA };
    const uB = { value: texB }, unB = { value: nrmB };
    m.userData.uMapA = uA; m.userData.uNrmA = unA;
    m.userData.uMapB = uB; m.userData.uNrmB = unB;
    const baseFn = base.onBeforeCompile;
    m.onBeforeCompile = sh => {
      baseFn(sh);
      sh.uniforms.uMapA = uA; sh.uniforms.uNrmA = unA;
      sh.uniforms.uMapB = uB; sh.uniforms.uNrmB = unB;
      sh.vertexShader = 'attribute vec2 aMix;\nvarying vec2 vMixT;\n' + sh.vertexShader;
      sh.vertexShader = sh.vertexShader.replace('#include <begin_vertex>',
        'vMixT = aMix;\n#include <begin_vertex>');
      sh.fragmentShader = 'uniform sampler2D uMapA;\nuniform sampler2D uNrmA;\n'
                        + 'uniform sampler2D uMapB;\nuniform sampler2D uNrmB;\n'
                        + 'varying vec2 vMixT;\n' + sh.fragmentShader;
      sh.fragmentShader = sh.fragmentShader.replace('#include <map_fragment>', `
        #ifdef USE_MAP
          vec4 tex = texture2D( map, vMapUv );
          tex = mix( tex, texture2D( uMapA, vMapUv ), vMixT.x );
          tex = mix( tex, texture2D( uMapB, vMapUv ), vMixT.y );
          diffuseColor *= tex;
        #endif
      `);
      // stessa mistura sul rilievo: se sfumasse solo il colore, la grana
      // cambierebbe di colpo e il confine resterebbe leggibile nella luce
      sh.fragmentShader = sh.fragmentShader.replace('#include <normal_fragment_maps>', `
        #ifdef USE_NORMALMAP_TANGENTSPACE
          vec3 mapN = texture2D( normalMap, vNormalMapUv ).xyz;
          mapN = mix( mapN, texture2D( uNrmA, vNormalMapUv ).xyz, vMixT.x );
          mapN = mix( mapN, texture2D( uNrmB, vNormalMapUv ).xyz, vMixT.y );
          mapN = mapN * 2.0 - 1.0;
          mapN.xy *= normalScale;
          normal = normalize( tbn * mapN );
        #endif
      `);
    };
    m.customProgramCacheKey = () => 'splineBlend';
    splineMats.set(chiave, m);
    (splineMatsPerTipo[id] = splineMatsPerTipo[id] || []).push(m);
  }
  return m;
}

/**
 *  La capienza si alloca su misura del tratto, non sempre al massimo: la gran
 *  parte dei tratti è corta, e con centinaia di tubi in scena prenotare 72
 *  anelli per ciascuno sprecherebbe decine di megabyte. Cresce se un tratto
 *  più lungo capita nello stesso slot, e non torna mai indietro.
 */
function getTubo(i, na) {
  let m = tubi[i];
  if (m && m.userData.cap >= na) return m;
  if (m) { scene.remove(m); m.geometry.dispose(); }
  const cap = clamp(Math.ceil(na / 8) * 8, 8, TUBO_ANELLI);
  const nv = (TUBO_RAD + 1) * cap;
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(nv * 3), 3));
  g.setAttribute('normal', new THREE.BufferAttribute(new Float32Array(nv * 3), 3));
  g.setAttribute('color', new THREE.BufferAttribute(new Float32Array(nv * 3), 3));
  g.setAttribute('uv', new THREE.BufferAttribute(new Float32Array(nv * 2), 2));
  g.setAttribute('aMix', new THREE.BufferAttribute(new Float32Array(nv * 2), 2));
  g.setIndex(new THREE.BufferAttribute(new Uint16Array(TUBO_RAD * Math.max(1, cap - 1) * 6), 1));
  m = new THREE.Mesh(g, blobMatSolid);
  m.frustumCulled = false;
  m.receiveShadow = true;
  m.userData.cap = cap;
  agganciaPulsazione(m);
  scene.add(m);
  tubi[i] = m;
  return m;
}

/**
 *  I PERCORSI SEGUONO L'ALBERO, in profondita'.
 *
 *  Un percorso e' una catena di padri e figli, e nient'altro: si scende dal
 *  nodo di partenza seguendo ogni volta UN figlio, finche' non si arriva a una
 *  foglia. Gli altri figli incontrati per strada non vengono persi: ognuno
 *  apre un percorso nuovo che comincia dal NODO CHE LI PORTA, cosi' il tubo
 *  del ramo nasce dentro quello del padre invece che a mezz'aria.
 *
 *      A                        ABCD   il tronco: scende fino in fondo
 *      +- B                     BEF    il ramo di E, che parte da B
 *      |  +- C                  EG     il ramo di G, che parte da E
 *      |  |  +- D
 *      |  +- E
 *      |     +- F
 *      |     +- G
 *
 *  QUALE FIGLIO PROSEGUE: quello col sottoalbero piu' profondo, a pari merito
 *  il primo. E' cio' che rende il tubo principale il piu' lungo possibile —
 *  proseguire col primo figlio qualunque esso sia farebbe finire il tronco
 *  dentro un moncone di due cellule mentre l'arto lungo diventa un ramo
 *  staccato. Sull'esempio qui sopra i due sottoalberi di B sono pari, quindi
 *  vince C e viene fuori esattamente ABCD / BEF / EG.
 *
 *  Niente piu' fusione per VICINANZA: due cellule che si toccano senza essere
 *  parenti non stanno piu' nello stesso tubo. Era quella a cucire insieme
 *  fratelli e a far entrare la spline da un'appendice per uscire dall'altra.
 *
 *  La morte di una cellula non spezza la catena: il figlio risale al primo
 *  antenato ancora vivo e il tubo prosegue.
 */
function estraiPercorsi(nodi, cr) {
  const vivo = new Set(nodi);
  const padre = new Map(), figli = new Map();
  for (const c of nodi) figli.set(c, []);
  for (const c of nodi) {
    let p = c.parent;
    while (p && !vivo.has(p)) p = p.parent;
    p = (p && vivo.has(p)) ? p : null;
    padre.set(c, p);
    if (p) figli.get(p).push(c);
  }

  /*  Profondita' del sottoalbero di ogni nodo, calcolata in ordine inverso di
   *  visita: iterativa e non ricorsiva, perche' un corpo lungo farebbe
   *  traboccare la pila delle chiamate. */
  const prof = new Map();
  const ordine = [];
  for (const c of nodi) if (!padre.get(c)) {
    const pila = [c];
    while (pila.length) {
      const u = pila.pop();
      ordine.push(u);
      for (const f of figli.get(u)) pila.push(f);
    }
  }
  for (let i = ordine.length - 1; i >= 0; i--) {
    const c = ordine[i];
    let m = 0;
    for (const f of figli.get(c)) m = Math.max(m, prof.get(f) || 0);
    prof.set(c, m + 1);
  }

  const percorsi = [];
  // da fare: [nodo di partenza (null per una radice), primo nodo della catena]
  const daFare = [];
  for (const c of nodi) if (!padre.get(c)) daFare.push([null, c]);
  let guardia = 0;
  while (daFare.length && guardia++ < 100000) {
    const [inizio, primo] = daFare.pop();
    const catena = inizio ? [inizio, primo] : [primo];
    let c = primo;
    for (;;) {
      const f = figli.get(c);
      if (!f || !f.length) break;
      let scelto = f[0];
      for (const x of f) if ((prof.get(x) || 0) > (prof.get(scelto) || 0)) scelto = x;
      for (const x of f) if (x !== scelto) daFare.push([c, x]);
      catena.push(scelto);
      c = scelto;
    }
    /*  Una cellula sola non fa un tubo: resta scoperta e la disegnano le sfere,
     *  che e' quel che serve per un frammento isolato. */
    if (catena.length < 2) continue;
    /*  `gA` non toglie la cupola: la STRINGE, e assottiglia il tubo li' vicino.
     *  Serve al capo di un ramo, che parte dal centro della cellula madre: a
     *  raggio pieno la sua superficie coinciderebbe con quella del tubo del
     *  padre e le due si contenderebbero il test di profondita' a ogni
     *  fotogramma. Rastremato, il ramo entra pulito dentro la madre e la sua
     *  cupola sparisce la' dentro. Il capo LIBERO invece si chiude sempre a
     *  cupola piena. */
    percorsi.push({ cells: catena, gA: !!inizio, gB: false });
  }
  return percorsi;
}

/**
 *  Fissa la topologia del percorso: quanti anelli, dove cadono i confini di
 *  tipo, come si spezza in tratti. Si chiama SOLO quando cambia la struttura
 *  delle cellule — se la suddivisione si rifacesse a ogni fotogramma il
 *  numero di anelli salterebbe col muoversi del corpo e la punta si
 *  ridisegnerebbe ogni volta diversa.
 */
function preparaPercorso(perc) {
  const cells = perc.cells, nP = cells.length - 1;
  let lung = 0, rSum = 0;
  for (let i = 0; i < cells.length; i++) {
    rSum += cells[i].r;
    if (i) lung += cells[i].pos.distanceTo(cells[i - 1].pos);
  }
  const rMedio = rSum / cells.length;
  perc.rMedio = rMedio;
  const passo = Math.max(1e-4, rMedio * .55);

  /*  UN TRATTO PER CELLULA, tagliato a metà strada fra un centro e il
   *  successivo. Prima si tagliava solo dove cambiava il TIPO, e un tratto
   *  poteva coprire sei cellule con un materiale solo.
   *
   *  Il materiale non si può mescolare — è un oggetto, non un numero — quindi
   *  l'unico modo perché ogni cellula porti DAVVERO il suo è darle un pezzo di
   *  tubo tutto suo. Colore e texture, che invece si mescolano, sfumano verso
   *  i due pezzi confinanti: mezzo e mezzo sul taglio, puri sul centro della
   *  cellula. Due cellule dello stesso tipo mescolano una texture con se
   *  stessa, quindi non si vede alcun taglio dove non serve. */
  const bordi = [0];
  for (let i = 0; i < nP; i++) bordi.push((i + .5) / nP);
  bordi.push(1);

  const tAn = [], capAn = [], angAn = [], vAn = [];
  /**
   *  La v non corre 0..1 su tutto il percorso — così la texture si stirava su
   *  tutta la catena. Corre invece 0..1 PER CELLULA: ogni cellula riceve un
   *  giro intero di disegno, e il salto fra un giro e l'altro cade sulla
   *  strozzatura fra due cellule, dove il tubo è più stretto e non si nota.
   *  Sulla sfera la v va da polo a polo: qui i "poli" sono le strozzature e
   *  gli "equatori" i centri delle cellule, che è la stessa cosa allungata.
   */
  for (let k = 0; k < TUBO_CALOTTA; k++) {          // calotta iniziale
    const ang = (1 - k / TUBO_CALOTTA) * Math.PI * .5;
    tAn.push(0); capAn.push(-1); angAn.push(ang);
    vAn.push(.5 * (1 - Math.sin(ang)));
  }
  const tratti = [];
  for (let k = 0; k + 1 < bordi.length; k++) {
    const ta = bordi[k], tb = bordi[k + 1];
    const da = k === 0 ? 0 : tAn.length - 1;        // il confine è già in lista
    if (k === 0) { tAn.push(ta); capAn.push(0); angAn.push(0); vAn.push(ta * nP + .5); }
    let n = Math.round(lung * (tb - ta) / passo);
    n = clamp(n, 1, TUBO_ANELLI - 2 * TUBO_CALOTTA - 2);
    if (tAn.length + n > MAX_ANELLI - TUBO_CALOTTA) n = Math.max(1, MAX_ANELLI - TUBO_CALOTTA - tAn.length);
    for (let s = 1; s <= n; s++) {
      const t = ta + (tb - ta) * s / n;
      tAn.push(t); capAn.push(0); angAn.push(0); vAn.push(t * nP + .5);
    }
    // la cellula rappresentativa del tratto sta al centro del suo intervallo
    const im = clamp(Math.round((ta + tb) * .5 * nP), 0, nP);
    /*  I confini del tratto misurati in CELLULE, non in anelli: è la scala su
     *  cui si misura anche la sfumatura delle texture, per farla combaciare
     *  con quella del colore. Intero = centro di una cellula, mezzo = punto di
     *  mezzo fra due. */
    tratti.push({ tipo: cells[im].type, cella: cells[im], da, a: tAn.length - 1,
                  fA: ta * nP, fB: tb * nP });
  }
  for (let k = TUBO_CALOTTA - 1; k >= 0; k--) {     // calotta finale
    const ang = (1 - k / TUBO_CALOTTA) * Math.PI * .5;
    tAn.push(1); capAn.push(1); angAn.push(ang);
    vAn.push(nP + .5 + .5 * Math.sin(ang));
  }
  tratti[0].da = 0;                                  // la calotta iniziale è del primo tratto
  tratti[tratti.length - 1].a = tAn.length - 1;      // e quella finale dell'ultimo
  for (let k = 0; k < tratti.length; k++) {
    tratti[k].tipoPrima = k > 0 ? tratti[k - 1].tipo : null;
    tratti[k].tipoDopo = k + 1 < tratti.length ? tratti[k + 1].tipo : null;
  }

  perc.tAn = Float32Array.from(tAn);
  perc.capAn = Int8Array.from(capAn);
  perc.angAn = Float32Array.from(angAn);
  perc.vAn = Float32Array.from(vAn);
  perc.M = tAn.length;
  perc.nP = nP;                    // intervalli fra cellule: la scala delle sfumature
  /**
   *  Asse di riferimento del percorso, scelto UNA VOLTA e in coordinate del
   *  corpo: fra i tre assi canonici, quello meno allineato con la direzione
   *  del percorso, così non rischia mai di finire parallelo alla tangente.
   *  Da qui nasce ogni fotogramma il seme del trasporto, ruotato con il corpo.
   *  Il criterio usa il valore assoluto, quindi se il percorso si ricostruisce
   *  al contrario l'asse scelto resta lo stesso.
   */
  const dm = new THREE.Vector3().subVectors(cells[cells.length - 1].restPos, cells[0].restPos);
  if (dm.lengthSq() < 1e-9) dm.set(0, 1, 0);
  dm.normalize();
  const ax = Math.abs(dm.x), ay = Math.abs(dm.y), az = Math.abs(dm.z);
  perc.asse = new THREE.Vector3(
    (ax <= ay && ax <= az) ? 1 : 0,
    (ay < ax && ay <= az) ? 1 : 0,
    (az < ax && az < ay) ? 1 : 0);
  if (perc.asse.lengthSq() === 0) perc.asse.set(0, 0, 1);

  /**
   *  Chiave stabile del percorso: gli id delle sue cellule, ordinati. Non
   *  cambia se il percorso viene ricostruito al contrario o ritagliato in
   *  tratti diversi, ed è quella che permette di ritrovare il riferimento del
   *  fotogramma prima dopo una ricostruzione.
   */
  perc.chiave = cells.map(c => c.id).sort((a, b) => a - b).join(',');

  perc.tratti = tratti;
  perc.pronto = true;
}

// stato di lavoro degli anelli, condiviso: un percorso alla volta
const _anC = new Float32Array(MAX_ANELLI * 3), _anT = new Float32Array(MAX_ANELLI * 3);
const _anU = new Float32Array(MAX_ANELLI * 3), _anW = new Float32Array(MAX_ANELLI * 3);
const _anR = new Float32Array(MAX_ANELLI), _anCol = new Float32Array(MAX_ANELLI * 3);
/*  Schiacciamento della sezione, UN VALORE PER ANELLO e non per tratto.
 *
 *  Due tratti confinanti condividono esattamente l'anello di confine: se lo
 *  schiacciamento fosse una proprieta' del tratto, al confine fra una ciliata e
 *  una epiteliale i due tratti calcolerebbero sezioni diverse sugli stessi
 *  vertici e si aprirebbe una fessura. Interpolato per anello come il raggio,
 *  sul confine i due leggono lo stesso numero e la paletta sfuma nel tubo. */
const _anP = new Float32Array(MAX_ANELLI).fill(1);
const _pv = new THREE.Vector3(), _pt = new THREE.Vector3();
const _tg1 = new THREE.Vector3(), _tg2 = new THREE.Vector3(), _seme = new THREE.Vector3();

/**
 *  Tangente presa su un passo VERO, non su 1e-4 come fa `Curve.getTangent`.
 *
 *  La parametrizzazione centripeta ricalcola i suoi pesi dalle distanze fra i
 *  punti a ogni chiamata, e le cellule si muovono: su un intervallo di 1e-4 il
 *  risultato è dominato da quel ricalcolo invece che dalla forma della curva.
 *  Misurato, la tangente terminale saltava fino a 18° da un fotogramma
 *  all'altro, e siccome il polo della calotta sta a un raggio di distanza
 *  lungo quella direzione, la punta si vedeva scattare da tutte le parti.
 *  Con un passo di mezza cellula la direzione è quella dell'asse dell'arto e
 *  si muove come si muove il corpo.
 */
function tangenteStabile(curva, t, h, out, punti, atteso) {
  const a = clamp(t - h, 0, 1), b = clamp(t + h, 0, 1);
  curva.getPoint(a, _tg1); curva.getPoint(b, _tg2);
  out.copy(_tg2).sub(_tg1);
  // Degenerazione RELATIVA, non assoluta. Se la spline si ripiega — e succede
  // nei primi istanti dopo la nascita, quando il corpo si assesta e le cellule
  // si accavallano — i due campioni quasi coincidono: la differenza resta
  // lunga magari 1e-3, ben sopra qualunque soglia assoluta, ma la sua
  // DIREZIONE è ormai solo rumore. Il riferimento trasportato la segue e
  // frusta attorno all'asse: misurato, fino a 178° in un fotogramma.
  // Sotto un ottavo della lunghezza attesa si passa alla corda fra le due
  // cellule che racchiudono t, che è sempre ben definita.
  const soglia = atteso * .125;
  if (out.lengthSq() > soglia * soglia) return out.normalize();
  const nP = punti.length - 1;
  const i = clamp(Math.floor(t * nP), 0, nP - 1);
  out.subVectors(punti[i + 1], punti[i]);
  if (out.lengthSq() < 1e-16) out.set(0, 1, 0);
  return out.normalize();
}

/** ricalcola gli anelli lungo la spline aggiornata. Gira a ogni fotogramma. */
function piegaPercorso(perc, world, dt) {
  const cells = perc.cells, nP = cells.length - 1;
  const punti = [], raggi = [], cols = [], piatti = [];
  for (const c of cells) {
    if (c.dead) return false;
    const p = cellPulse(c, uCellTime.value);
    let gonfio = 1;
    if (c.def.thrust && c.creature && c.creature.alive) {
      // il punto di controllo si sposta col battito: il tubo rema invece di
      // stare fermo. Il vettore è appeso alla cellula e non si rialloca.
      const q = c._battPos || (c._battPos = new THREE.Vector3());
      gonfio = 1 + .18 * battitoCiliare(c, q);
      punti.push(q);
    } else punti.push(c.pos);
    raggi.push(c.r * p.s * gonfio * 1.06 * (SIZE_MUL[c.def.cat] || 1));
    piatti.push(c.def.piatto ?? 1);
    const t = cellTint(c, world), base = cellBaseColor[c.type] || cellBaseColor.nutrient;
    cols.push(base.r * t.r * p.b, base.g * t.g * p.b, base.b * t.b * p.b);
  }
  if (punti.length < 2) return false;
  const curva = new THREE.CatmullRomCurve3(punti, false, 'centripetal', .5);
  const M = perc.M, tAn = perc.tAn, capAn = perc.capAn, angAn = perc.angAn;

  /**
   *  Memoria della creatura, indicizzata per CHIAVE del percorso e non per
   *  oggetto: ci vivono il seme del riferimento e le tangenti smorzate, e
   *  sopravvivono alle ricostruzioni. È lì che si perdevano prima, ed è per
   *  questo che a ogni cambio di struttura il riferimento tornava libero di
   *  saltare di mezzo giro.
   */
  const crea = perc.cells[0].creature;
  const memoria = crea ? (crea._semiSpline || (crea._semiSpline = new Map())) : null;
  if (memoria && memoria.size > 128) memoria.clear();     // non cresce all'infinito
  let ricordo = memoria ? memoria.get(perc.chiave) : null;
  if (!ricordo) {
    ricordo = { seme: new THREE.Vector3().copy(perc.asse), tan: null };
    if (memoria) memoria.set(perc.chiave, ricordo);
  }
  const seme = ricordo.seme;

  const hCapo = .5 / Math.max(1, nP);          // mezza cellula: l'asse dell'arto
  const hCorpo = 1 / Math.max(1, M - 1);       // un anello
  // lunghezza della spezzata fra i centri: serve a dire quanto DEVE essere
  // lungo il vettore differenza, e quindi a riconoscere quando degenera
  let spezzata = 0;
  for (let i = 1; i < punti.length; i++) spezzata += punti[i].distanceTo(punti[i - 1]);
  const attCapo = Math.max(1e-6, spezzata * hCapo);
  const attCorpo = Math.max(1e-6, spezzata * hCorpo * 2);
  // lunghezza del raccordo di giunzione, in unità di mondo
  const LT = Math.max(1e-6, Math.min(perc.rMedio * 1.8, spezzata * .34));
  /**
   *  La direzione delle due calotte si insegue, non si prende istantanea.
   *
   *  Misurato: la cellula in punta si sposta fino allo 0.082 per fotogramma —
   *  il 68% del proprio raggio — e l'asse fra le ultime due ruota di 22°. Il
   *  polo della calotta sta a un raggio di distanza lungo quell'asse, quindi
   *  AMPLIFICA quel movimento invece di seguirlo, e la punta si vede scattare
   *  come se la mesh venisse rifatta ogni volta. Con una costante di tempo di
   *  70 ms la calotta resta incollata all'arto e lo scatto sparisce; il
   *  ritardo, su una rotazione lenta, vale pochi gradi.
   */
  const k = 1 - Math.exp(-Math.max(1e-4, dt) / .07);
  const t0i = tangenteStabile(curva, 0, hCapo, _pt, punti, attCapo);
  if (!perc.dirA) perc.dirA = t0i.clone(); else perc.dirA.lerp(t0i, k).normalize();
  const t1i = tangenteStabile(curva, 1, hCapo, _pt, punti, attCapo);
  if (!perc.dirB) perc.dirB = t1i.clone(); else perc.dirB.lerp(t1i, k).normalize();
  const T0 = perc.dirA, T1 = perc.dirB;
  const P0 = curva.getPoint(0, _pv).clone();
  const P1 = curva.getPoint(1, _pv).clone();
  const r0 = raggi[0], r1 = raggi[nP];

  // anche le tangenti smorzate stanno nella memoria indicizzata per chiave:
  // se restassero sull'oggetto percorso, ogni ricostruzione le azzererebbe e
  // in quel fotogramma il riferimento tornerebbe libero di saltare
  if (!ricordo.tan || ricordo.tan.length !== M * 3) ricordo.tan = new Float32Array(M * 3);
  const tanPrec = ricordo.tan;
  const kT = 1 - Math.exp(-Math.max(1e-4, dt) / .05);

  /**
   *  ORDINE: prima si fissa la tangente DEFINITIVA — raddrizzata e smorzata —
   *  e solo dopo si costruisce il centro dell'anello con quella.
   *
   *  Prima non era così: il centro della calotta veniva calcolato con la
   *  tangente grezza mentre `_anT` finiva per contenerne una capovolta dalla
   *  guardia di continuità. Centro e normale puntavano da parti opposte, la
   *  cupola si disegnava al rovescio e, con le facce singole, spariva:
   *  restava il bordo circolare aperto sull'ultimo anello di corpo.
   */
  for (let j = 0; j < M; j++) {
    const cap = capAn[j], t = tAn[j], o = j * 3;
    let cx, cy, cz, tx, ty, tz, rr, pp = 1;

    if (cap) {
      const T = cap < 0 ? T0 : T1;
      tx = T.x; ty = T.y; tz = T.z;
    } else {
      tangenteStabile(curva, t, hCorpo, _pt, punti, attCorpo);
      tx = _pt.x; ty = _pt.y; tz = _pt.z;
    }


    // Verso locale della spezzata: serve due volte, prima e dopo lo
    // smorzamento. Prima, perché l'interpolazione parta dall'emisfero giusto;
    // dopo, come garanzia che nulla possa rientrare storto.
    const iS = cap < 0 ? 0 : cap > 0 ? nP - 1 : clamp(Math.floor(t * nP), 0, nP - 1);
    const fx = punti[iS + 1].x - punti[iS].x;
    const fy = punti[iS + 1].y - punti[iS].y;
    const fz = punti[iS + 1].z - punti[iS].z;
    if (tx * fx + ty * fy + tz * fz < 0) { tx = -tx; ty = -ty; tz = -tz; }

    /**
     *  E si insegue nel tempo OGNI tangente, non solo quelle delle calotte. Il
     *  riferimento attorno al tubo è trasportato lungo la catena delle
     *  tangenti: finché quelle possono girare di colpo — e possono, perché la
     *  spline si ricalcola da cellule che nei momenti di assestamento si
     *  spostano di oltre un raggio per fotogramma — il riferimento le segue e
     *  la texture frusta attorno all'asse.
     */
    if (tanPrec) {
      let px = tanPrec[o], py = tanPrec[o + 1], pz = tanPrec[o + 2];
      // se il ricordo è dell'emisfero opposto — percorso ricostruito al
      // contrario — va girato, o l'interpolazione passerebbe per lo zero
      if (px * tx + py * ty + pz * tz < 0) { px = -px; py = -py; pz = -pz; }
      if (px || py || pz) {
        tx = px + (tx - px) * kT; ty = py + (ty - py) * kT; tz = pz + (tz - pz) * kT;
        const l = Math.hypot(tx, ty, tz) || 1; tx /= l; ty /= l; tz /= l;
      }
      tanPrec[o] = tx; tanPrec[o + 1] = ty; tanPrec[o + 2] = tz;
    }

    /**
     *  Ultima parola sul verso, DOPO lo smorzamento, su un riferimento
     *  ASSOLUTO: il segmento della spezzata fra le due cellule che contengono
     *  questo anello.
     *
     *  Prima allineavo ogni anello al precedente, ed era un errore sottile: un
     *  ribaltamento entrato una volta — da una piega della spline, o dal
     *  ripiego sulla corda — si propagava in avanti a tutta la catena e lo
     *  smorzamento ci si adagiava sopra. Misurato: la catena partiva giusta
     *  (+0.98 col verso delle cellule) e finiva rovescia (−1.00). La cupola si
     *  costruiva allora verso l'interno del tubo e la punta restava aperta
     *  sull'ultimo anello di corpo — il bordo circolare che si vedeva.
     *  Con un riferimento locale e assoluto, e messo per ultimo, un errore non
     *  può né propagarsi né rientrare dallo smorzamento.
     */
    if (tx * fx + ty * fy + tz * fz < 0) {
      tx = -tx; ty = -ty; tz = -tz;
      if (tanPrec) { tanPrec[o] = tx; tanPrec[o + 1] = ty; tanPrec[o + 2] = tz; }
    }

    if (cap) {
      const giunz = cap < 0 ? perc.gA : perc.gB;
      const P = cap < 0 ? P0 : P1;
      const R = (cap < 0 ? r0 : r1) * (giunz ? GIUNZ_R : 1);
      const s = Math.sin(angAn[j]) * R * cap;      // avanza lungo la tangente FINALE
      cx = P.x + tx * s; cy = P.y + ty * s; cz = P.z + tz * s;
      rr = R * Math.cos(angAn[j]);
      const i = cap < 0 ? 0 : nP;
      pp = piatti[i];
      _anCol[o] = cols[i * 3]; _anCol[o + 1] = cols[i * 3 + 1]; _anCol[o + 2] = cols[i * 3 + 2];
    } else {
      curva.getPoint(t, _pv);
      cx = _pv.x; cy = _pv.y; cz = _pv.z;
      const f = clamp(t, 0, 1) * nP, i = Math.min(nP - 1, Math.floor(f)), w = f - i;
      rr = raggi[i] + (raggi[i + 1] - raggi[i]) * w;
      pp = piatti[i] + (piatti[i + 1] - piatti[i]) * w;
      /**
       *  Raccordo verso la giunzione: il tubo si assottiglia per entrare nel
       *  ramo madre invece di combaciarci.
       *
       *  Prima il raccordo durava UNA CELLULA, contata sull'indice. Su un
       *  percorso di tre cellule con giunzioni a tutt'e due i capi — un
       *  ponte fra due rami già usati — voleva dire scendere al 52% subito, e
       *  fra il tratto pieno e quello sottile restava una spalla ripida che a
       *  vista è un coperchio piantato sulla salsiccia. Ora il raccordo si
       *  misura in LUNGHEZZA D'ARCO, dura poco meno di due raggi e non prende
       *  mai più di un terzo del percorso, con un profilo a S invece che
       *  lineare: le spalle si ammorbidiscono e il pezzo corto resta pieno in
       *  mezzo.
       */
      if (perc.gA) { const u = clamp(t * spezzata / LT, 0, 1); rr *= GIUNZ_R + (1 - GIUNZ_R) * u * u * (3 - 2 * u); }
      if (perc.gB) { const u = clamp((1 - t) * spezzata / LT, 0, 1); rr *= GIUNZ_R + (1 - GIUNZ_R) * u * u * (3 - 2 * u); }

      _anCol[o] = cols[i * 3] + (cols[(i + 1) * 3] - cols[i * 3]) * w;
      _anCol[o + 1] = cols[i * 3 + 1] + (cols[(i + 1) * 3 + 1] - cols[i * 3 + 1]) * w;
      _anCol[o + 2] = cols[i * 3 + 2] + (cols[(i + 1) * 3 + 2] - cols[i * 3 + 2]) * w;
    }

    _anC[o] = cx; _anC[o + 1] = cy; _anC[o + 2] = cz;
    _anT[o] = tx; _anT[o + 1] = ty; _anT[o + 2] = tz;
    _anR[j] = rr;
    _anP[j] = pp;
  }

  /**
   *  Riferimento trasportato lungo TUTTO il percorso: è questo a far combaciare
   *  i vertici degli anelli condivisi fra un tratto e il successivo.
   *
   *  Il seme però NON si ricava da capo ogni volta. Prima lo si costruiva
   *  dalla tangente — `(-Tz, 0, Tx)`, oppure `(1,0,0)` quando il tubo è quasi
   *  verticale — e bastava che |Ty| attraversasse la soglia perché il seme
   *  saltasse a un vettore completamente diverso: misurato, il riferimento
   *  ruotava fino a 173° da un fotogramma all'altro, mezzo giro. La forma del
   *  tubo non cambia (la sezione è un cerchio) ma tutti i vertici sfrecciano
   *  attorno all'asse, la texture con loro, e si vede come uno sfarfallio.
   *
   *  Ora il seme è quello del fotogramma prima, riproiettato: la rotazione
   *  attorno all'asse resta la minima possibile anche nel tempo, non solo
   *  lungo la curva.
   */
  /**
   *  Il seme del trasporto è quello del fotogramma prima, riproiettato: è la
   *  definizione stessa di riferimento a rotazione minima, estesa al tempo.
   *
   *  Le costruzioni ricavate dalla tangente hanno tutte una soglia — «se il
   *  tubo è quasi verticale prendi quest'altro vettore» — e ogni volta che il
   *  tubo l'attraversava il riferimento saltava di mezzo giro: misurato, fino
   *  a 175° in un fotogramma, con tutti i vertici e la texture che sfrecciano
   *  attorno all'asse. Nemmeno l'orientamento del corpo va bene come àncora:
   *  su un corpo di otto cellule la stima salta di 83° per fotogramma.
   *
   *  Il seme sta quindi in una memoria della creatura, indicizzata per CHIAVE
   *  del percorso e non per oggetto: sopravvive alle ricostruzioni, che
   *  avvengono a ogni cambio di struttura ed erano il punto in cui il
   *  riferimento si perdeva. Solo un percorso mai visto parte dall'asse
   *  precalcolato, ed è giusto così.
   */
  let ux = seme.x, uy = seme.y, uz = seme.z;
  {
    const l = Math.hypot(ux, uy, uz) || 1; ux /= l; uy /= l; uz /= l;
  }
  for (let j = 0; j < M; j++) {
    const o = j * 3, tx = _anT[o], ty = _anT[o + 1], tz = _anT[o + 2];
    const d = ux * tx + uy * ty + uz * tz;
    ux -= tx * d; uy -= ty * d; uz -= tz * d;
    let l = Math.hypot(ux, uy, uz);
    if (l < 1e-6) { ux = 1 - tx * tx; uy = -tx * ty; uz = -tx * tz; l = Math.hypot(ux, uy, uz) || 1; }
    ux /= l; uy /= l; uz /= l;
    _anU[o] = ux; _anU[o + 1] = uy; _anU[o + 2] = uz;
    _anW[o] = ty * uz - tz * uy; _anW[o + 1] = tz * ux - tx * uz; _anW[o + 2] = tx * uy - ty * ux;
    if (j === 0) seme.set(ux, uy, uz);         // da qui riparte il prossimo fotogramma
  }
  return true;
}

/** riversa la fetta di anelli [da..a] nella mesh del tratto */
function scriviTratto(mesh, perc, tratto) {
  const NA = tratto.a - tratto.da + 1;
  const pos = mesh.geometry.attributes.position.array;
  const nor = mesh.geometry.attributes.normal.array;
  const col = mesh.geometry.attributes.color.array;
  const uvs = mesh.geometry.attributes.uv.array;
  const mix = mesh.geometry.attributes.aMix.array;
  const ind = mesh.geometry.index.array;
  const rifaTopologia = mesh.userData.NA !== NA || mesh.userData.tratto !== tratto;
  const M = perc.M;

  for (let k = 0; k < NA; k++) {
    const j = tratto.da + k, o = j * 3;
    const cx = _anC[o], cy = _anC[o + 1], cz = _anC[o + 2];
    const tx = _anT[o], ty = _anT[o + 1], tz = _anT[o + 2];
    const ux = _anU[o], uy = _anU[o + 1], uz = _anU[o + 2];
    const wx = _anW[o], wy = _anW[o + 1], wz = _anW[o + 2];
    const R = _anR[j];
    const ja = Math.max(0, j - 1), jb = Math.min(M - 1, j + 1);
    const dsx = _anC[jb * 3] - _anC[ja * 3], dsy = _anC[jb * 3 + 1] - _anC[ja * 3 + 1], dsz = _anC[jb * 3 + 2] - _anC[ja * 3 + 2];
    const ds = Math.hypot(dsx, dsy, dsz);
    const dr = ds > 1e-9 ? (_anR[jb] - _anR[ja]) / ds : 0;
    const polo = j === 0 || j === M - 1;      // la chiusura è sempre una cupola
    /*  LA TEXTURE SFUMA COME IL COLORE: da centro cellula a centro cellula.
     *
     *  Il colore si interpola fra la cellula `i` e la `i+1` lungo tutto
     *  l'intervallo che le separa — è la stessa regola che vale per il raggio.
     *  La texture invece sfumava su un numero FISSO di anelli, tre, che non
     *  ha niente a che vedere con la distanza fra due cellule: misurato su un
     *  corpo vero, una cellula copre da 3 a 15 anelli. Su una cellula grossa
     *  il colore scivolava per quindici anelli mentre il disegno scattava in
     *  tre — la cucitura si vedeva; su una piccola i tre anelli scavalcavano
     *  il centro della cellula e sconfinavano nella successiva.
     *
     *  Qui il peso si misura in CELLULE: mezza cellula per lato del confine.
     *  Sul confine vale 0.5 — ed è quella la condizione che rende identici i
     *  due tratti sull'anello che condividono — e si spegne esattamente sul
     *  CENTRO della cellula, dove la texture dev'essere quella pura. Le due
     *  rampe dei tratti adiacenti si saldano quindi in un'unica transizione
     *  che va dal centro del padre al centro del figlio, la stessa su cui
     *  viaggia il colore. */
    const f = perc.tAn[j] * perc.nP;          // posizione in unità di cellula
    const mixA = tratto.tipoPrima ? clamp(.5 - (f - tratto.fA), 0, .5) : 0;
    const mixB = tratto.tipoDopo  ? clamp(.5 - (tratto.fB - f), 0, .5) : 0;
    // la v arriva dalla preparazione: continua fra un tratto e l'altro, e
    // completa un giro di texture per ogni cellula attraversata
    const v = perc.vAn[j];
    /*  Sezione ELLITTICA: `A` lungo il riferimento trasportato, `B` di
     *  traverso. A `P` uguale a 1 sono uguali e il tubo e' tondo come prima.
     *
     *  La normale non e' la direzione del punto: per un'ellisse di semiassi A e
     *  B la normale in `(A·cos, B·sin)` ha direzione `(B·cos, A·sin)` — i
     *  coefficienti si scambiano. Usando la direzione del punto, una paletta
     *  schiacciata prenderebbe la luce come se fosse ancora tonda e il
     *  rilievo mentirebbe. */
    const P = _anP[j], A = R, B = R * P;
    for (let i = 0; i <= TUBO_RAD; i++) {
      const co = _TUBO_CO[i], si = _TUBO_SI[i];
      const pcx = co * A, pcw = si * B;                      // punto sull'ellisse
      const ncu = co * B, ncw = si * A;                      // normale sull'ellisse
      const rx = ux * pcx + wx * pcw, ry = uy * pcx + wy * pcw, rz = uz * pcx + wz * pcw;
      const gx = ux * ncu + wx * ncw, gy = uy * ncu + wy * ncw, gz = uz * ncu + wz * ncw;
      let nx, ny, nz;
      if (polo) { const s = j === 0 ? -1 : 1; nx = tx * s; ny = ty * s; nz = tz * s; }
      else { nx = gx - tx * dr * R; ny = gy - ty * dr * R; nz = gz - tz * dr * R; }
      const ln = Math.hypot(nx, ny, nz) || 1;
      const q = (k * (TUBO_RAD + 1) + i) * 3;
      pos[q] = cx + rx; pos[q + 1] = cy + ry; pos[q + 2] = cz + rz;
      nor[q] = nx / ln; nor[q + 1] = ny / ln; nor[q + 2] = nz / ln;
      col[q] = _anCol[o]; col[q + 1] = _anCol[o + 1]; col[q + 2] = _anCol[o + 2];
      if (rifaTopologia) {
        const u2 = (k * (TUBO_RAD + 1) + i) * 2;
        uvs[u2] = i / TUBO_RAD; uvs[u2 + 1] = v;
        mix[u2] = mixA; mix[u2 + 1] = mixB;
      }
    }
  }
  if (rifaTopologia) {
    let e = 0;
    for (let k = 0; k + 1 < NA; k++) for (let i = 0; i < TUBO_RAD; i++) {
      // antiorario visto da fuori: con {u, w, T} destrorso è a,b,c
      const a = k * (TUBO_RAD + 1) + i, b = a + 1, c = a + TUBO_RAD + 1, d = c + 1;
      ind[e++] = a; ind[e++] = b; ind[e++] = c;
      ind[e++] = b; ind[e++] = d; ind[e++] = c;
    }
    mesh.geometry.attributes.uv.needsUpdate = true;
    mesh.geometry.attributes.aMix.needsUpdate = true;
    mesh.geometry.index.needsUpdate = true;
    mesh.geometry.setDrawRange(0, e);
    mesh.userData.NA = NA;
    mesh.userData.tratto = tratto;
  }
  const nv = NA * (TUBO_RAD + 1);
  caricaParziale(mesh.geometry.attributes.position, nv);
  caricaParziale(mesh.geometry.attributes.normal, nv);
  caricaParziale(mesh.geometry.attributes.color, nv);
}

/**
 *  Firma della struttura: cellule vive più i legami diretti. Finché non
 *  cambia, percorsi e suddivisione restano quelli — ed è questa la garanzia
 *  che la mesh non si rigeneri sotto gli occhi.
 */
function firmaStruttura(cr) {
  let s = '';
  for (const c of cr.cells) if (!c.dead) s += c.id + ':' + c.type + ',';
  s += '|';
  // i legami si ordinano prima di concatenarli: `rebuild()` può rimetterli in
  // fila diversamente senza che la struttura sia cambiata davvero, e una firma
  // sensibile all'ordine farebbe rifare i percorsi per niente
  const legami = [];
  for (const con of cr.constraints)
    if (con.direct && !con.a.dead && !con.b.dead)
      legami.push(Math.min(con.a.id, con.b.id) + '-' + Math.max(con.a.id, con.b.id));
  legami.sort();
  return s + legami.join(',');
}

function syncSpline(world) {
  if (renderMode !== 'spline') {
    for (const m of tubi) if (m) m.visible = false;
    return;
  }
  const controlla = (tuboFrame++ % 5) === 0;
  const ora = performance.now() * .001;
  const dt = clamp(ora - (_splineT || ora), 0, .2);
  _splineT = ora;
  let i = 0;
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) {
      if (controlla || !cr._percSpline) {
        const firma = firmaStruttura(cr);
        if (cr._firmaSpline !== firma) {
          cr._firmaSpline = firma;
          const vive = cr.cells.filter(c => !c.dead);
          cr._percSpline = vive.length ? estraiPercorsi(vive, cr) : [];
          for (const p of cr._percSpline) if (p.cells.length >= 2) preparaPercorso(p);
        }
      }
      for (const perc of cr._percSpline) {
        if (perc.cells.length < 2 || !perc.pronto) continue;
        if (!piegaPercorso(perc, world, dt)) continue;
        for (const tr of perc.tratti) {
          if (i >= MAX_TUBI) break;
          /*  Radiografia: il tratto di un tipo nascosto non si disegna, e le sue
           *  cellule NON vengono marcate coperte qui sotto — così `syncInstances`
           *  le ritrova e le rimette come ovali fantasma, esattamente come nelle
           *  modalità a sfere. Prima restavano marchiate e sparivano del tutto.
           *  Un tratto è di un tipo solo, quindi quelli del tipo cercato non
           *  vengono mai saltati. */
          if (tr.cella && nascostaDaRadiografia(tr.cella)) continue;
          const mesh = getTubo(i, tr.a - tr.da + 1);
          /*  Le texture dei vicini viaggiano DENTRO il materiale, scelto per
           *  terna: niente più uniformi condivisi da riscrivere prima di ogni
           *  disegno. Dove non c'è vicino si lega una tessera neutra, che col
           *  peso a zero non cambia nulla ma tiene il sampler occupato. */
          mesh.material = matSpline(tr.tipo, tr.tipoPrima, tr.tipoDopo);
          mesh.userData.wobK = perc.rMedio;
          /*  Il battito luminoso lo porta già il COLORE DEL VERTICE, dove è
           *  interpolato fra una cellula e l'altra insieme al resto della
           *  tinta. Rimetterlo anche qui, come uniforme del pezzo, lo
           *  applicherebbe due volte — e la seconda a gradini, uguale su tutto
           *  il pezzo e diverso da quello accanto: sui nervi si vedrebbe uno
           *  scalino di luce a ogni mezza cellula, proprio dove il colore
           *  invece sfuma. Qui vale 1 e il battito resta quello, uno solo e
           *  continuo. */
          mesh.userData.lum = 1;
          scriviTratto(mesh, perc, tr);
          mesh.visible = true;
          i++;
        }
        // copre solo ciò che ha davvero disegnato: il resto torna fantasma
        for (const c of perc.cells) if (!nascostaDaRadiografia(c)) c._coperta = true;
      }
    }
  }
  for (; i < tubi.length; i++) if (tubi[i]) tubi[i].visible = false;
}

/**
 *  Azzera le coperture prima che mesh e spline rimarchino le loro. Va fatto
 *  in OGNI modalità: uscendone il marchio resterebbe addosso alle cellule e
 *  le sfere non tornerebbero più a disegnarsi.
 */
function resetCoperture(world) {
  for (const v of world.vessels) for (const cr of v.creatures) for (const c of cr.cells) c._coperta = false;
}

/* --- modalità Edit: anello attorno alla cellula in lavorazione ---------- */
let editMode = false;
const anelloSel = new THREE.Mesh(
  new THREE.TorusGeometry(1, .085, 8, 40),
  new THREE.MeshBasicMaterial({ color: 0x39d3c0, transparent: true, opacity: .9,
    depthTest: false, toneMapped: false }));
anelloSel.renderOrder = 950;
anelloSel.frustumCulled = false;
anelloSel.visible = false;
scene.add(anelloSel);

/* --- modalità Edit: albero della parentela in sovraimpressione ----------
 *  Serve a capire dove si sta innestando senza dover girare intorno
 *  all'esserino. Dal padre partono i rami verso TUTTI i fratelli e si fermano
 *  lì: i figli dei fratelli sono rumore per chi sta lavorando altrove. Il ramo
 *  della cellula corrente invece prosegue e apre tutta la sua discendenza.
 *
 *  Sono nastri, non linee: `gl.lineWidth` vale 1 su quasi ogni driver, e un
 *  filo di un pixel sopra un esserino texturizzato non si vede. Ogni ramo è un
 *  quadrilatero rivolto alla camera, con la larghezza chiesta in PIXEL e
 *  riconvertita in unità di mondo alla distanza del ramo: così non ingrassa
 *  avvicinandosi né sparisce da lontano.
 *
 *  Tutto viene disegnato due volte, prima in scuro e più largo: l'esserino
 *  sotto va dal bianco al rosso acceso, e senza quel contorno metà dell'albero
 *  si perde nel colore della cellula che attraversa.
 * -------------------------------------------------------------------- */
const RAMI_MAX = 1600;               // nastri, contorno compreso
const ramiGeo = new THREE.BufferGeometry();
const ramiPos = new Float32Array(RAMI_MAX * 12);
const ramiCol = new Float32Array(RAMI_MAX * 12);
{
  const idx = new Uint16Array(RAMI_MAX * 6);
  for (let i = 0; i < RAMI_MAX; i++) {
    const v = i * 4, k = i * 6;
    idx[k] = v; idx[k + 1] = v + 1; idx[k + 2] = v + 2;
    idx[k + 3] = v; idx[k + 4] = v + 2; idx[k + 5] = v + 3;
  }
  ramiGeo.setIndex(new THREE.BufferAttribute(idx, 1));
}
ramiGeo.setAttribute('position', new THREE.BufferAttribute(ramiPos, 3));
ramiGeo.setAttribute('color', new THREE.BufferAttribute(ramiCol, 3));
const alberoEdit = new THREE.Mesh(ramiGeo, new THREE.MeshBasicMaterial({
  vertexColors: true, transparent: true, opacity: .96,
  depthTest: false, depthWrite: false, toneMapped: false, side: THREE.DoubleSide,
}));
alberoEdit.renderOrder = 948;        // sotto l'anello, sopra tutto il resto
alberoEdit.frustumCulled = false;
alberoEdit.visible = false;
scene.add(alberoEdit);

/*  I colori sono PRE-COMPENSATI. L'albero passa per l'OutputPass insieme a
 *  tutto il resto, e la mappatura tonale ACES sbianca i colori accesi: il
 *  ciano 0x74ffe6 arrivava a schermo come (179,227,218), cioè bianco, e i
 *  fratelli finivano identici al ramo corrente. `toneMapped:false` non serve
 *  a niente qui, perché a mappare è la passata finale, non il materiale.
 *  Questi valori sono quindi la SOLUZIONE INVERSA di ACES (esposizione 1.05)
 *  per il colore che si vuole davvero vedere, indicato qui a fianco. */
const RAMO_ORLO = new THREE.Color(0x161e26);       // → (6,13,20)     il contorno che stacca
const RAMO_PADRE = new THREE.Color(0xff9b43);      // → (237,179,91)  ambra: da qui si dirama tutto
const RAMO_FRATELLO = new THREE.Color(0x6e889b);   // → (125,154,172) spenti: sono vicoli ciechi
const RAMO_CORRENTE = new THREE.Color(0x00a781);   // → (38,184,149)  il ramo su cui si lavora
const RAMO_FONDO = new THREE.Color(0x1484f3);      // → (46,150,224)  dove sprofonda la discendenza
// la discendenza si raffredda scendendo; i colori sono pronti, non si allocano per frame
const SCALA_DISC = [];
for (let i = 0; i <= 8; i++) SCALA_DISC.push(RAMO_CORRENTE.clone().lerp(RAMO_FONDO, i / 8));

const _rA = new THREE.Vector3(), _rB = new THREE.Vector3(), _rD = new THREE.Vector3();
const _rM = new THREE.Vector3(), _rV = new THREE.Vector3(), _rL = new THREE.Vector3();
const _rDx = new THREE.Vector3(), _rDy = new THREE.Vector3();
let _nRami = 0;

/** unità di mondo per pixel alla distanza di `p`: è ciò che tiene la
 *  larghezza costante sullo schermo mentre la camera si avvicina */
function unitaPerPixel(p) {
  return 2 * camera.position.distanceTo(p)
       * Math.tan(camera.fov * Math.PI / 360) / Math.max(1, viewH);
}

function _quad(x0, y0, z0, x1, y1, z1, x2, y2, z2, x3, y3, z3, ca, cb) {
  const o = _nRami * 12, p = ramiPos, q = ramiCol;
  p[o     ] = x0; p[o +  1] = y0; p[o +  2] = z0;
  p[o +  3] = x1; p[o +  4] = y1; p[o +  5] = z1;
  p[o +  6] = x2; p[o +  7] = y2; p[o +  8] = z2;
  p[o +  9] = x3; p[o + 10] = y3; p[o + 11] = z3;
  q[o     ] = ca.r; q[o +  1] = ca.g; q[o +  2] = ca.b;
  q[o +  3] = cb.r; q[o +  4] = cb.g; q[o +  5] = cb.b;
  q[o +  6] = cb.r; q[o +  7] = cb.g; q[o +  8] = cb.b;
  q[o +  9] = ca.r; q[o + 10] = ca.g; q[o + 11] = ca.b;
  _nRami++;
}

/** un ramo da `a` a `b`, largo `largPx` pixel, sfumato fra i due colori */
function ramo(a, b, ca, cb, largPx) {
  if (_nRami >= RAMI_MAX) return;
  _rA.copy(a); _rB.copy(b);
  _rD.subVectors(_rB, _rA);
  if (_rD.lengthSq() < 1e-10) return;
  _rM.addVectors(_rA, _rB).multiplyScalar(.5);
  _rV.subVectors(_rM, camera.position);
  _rL.crossVectors(_rD, _rV);
  if (_rL.lengthSq() < 1e-14) return;               // ramo in asse con lo sguardo
  _rL.normalize().multiplyScalar(unitaPerPixel(_rM) * largPx * .5);
  _quad(_rA.x + _rL.x, _rA.y + _rL.y, _rA.z + _rL.z,
        _rB.x + _rL.x, _rB.y + _rL.y, _rB.z + _rL.z,
        _rB.x - _rL.x, _rB.y - _rL.y, _rB.z - _rL.z,
        _rA.x - _rL.x, _rA.y - _rL.y, _rA.z - _rL.z, ca, cb);
}

/** un rombo rivolto alla camera: segna il nodo, senza il quale l'albero
 *  è solo un groviglio di segmenti */
function nodo(a, col, latoPx) {
  if (_nRami >= RAMI_MAX) return;
  const k = unitaPerPixel(a) * latoPx * .5;
  _rDx.setFromMatrixColumn(camera.matrixWorld, 0).multiplyScalar(k);
  _rDy.setFromMatrixColumn(camera.matrixWorld, 1).multiplyScalar(k);
  _quad(a.x + _rDx.x, a.y + _rDx.y, a.z + _rDx.z,
        a.x + _rDy.x, a.y + _rDy.y, a.z + _rDy.z,
        a.x - _rDx.x, a.y - _rDx.y, a.z - _rDx.z,
        a.x - _rDy.x, a.y - _rDy.y, a.z - _rDy.z, col, col);
}

/* la raccolta degli archi e dei nodi prima del disegno: servono due passate
 * (contorno e colore) sugli stessi elementi, e ricalcolare l'albero due volte
 * sarebbe sciocco */
const _eA = [], _eB = [], _eCa = [], _eCb = [], _eW = [];
const _nP = [], _nC = [], _nL = [];
let _nE = 0, _nN = 0;
function _arco(a, b, ca, cb, w) { _eA[_nE] = a; _eB[_nE] = b; _eCa[_nE] = ca; _eCb[_nE] = cb; _eW[_nE] = w; _nE++; }
function _pallino(p, c, l) { _nP[_nN] = p; _nC[_nN] = c; _nL[_nN] = l; _nN++; }

function costruisciAlberoEdit(c) {
  _nE = 0; _nN = 0;
  const vivo = x => x && !x.dead;
  const LIM = RAMI_MAX / 2;                         // metà bilancio: l'altra è il contorno

  // il ventaglio dei fratelli, che si ferma a loro
  const padre = vivo(c.parent) ? c.parent : null;
  if (padre) {
    _pallino(padre.pos, RAMO_PADRE, 8);
    for (const f of padre.children) {
      if (!vivo(f) || _nE + _nN >= LIM) continue;
      if (f === c) _arco(padre.pos, f.pos, RAMO_PADRE, RAMO_CORRENTE, 5.4);
      else { _arco(padre.pos, f.pos, RAMO_PADRE, RAMO_FRATELLO, 3.2); _pallino(f.pos, RAMO_FRATELLO, 6); }
    }
  }
  _pallino(c.pos, RAMO_CORRENTE, 9);

  // la discendenza, per livelli: si assottiglia e si raffredda scendendo
  let fronte = [c];
  for (let liv = 0; fronte.length && liv < 64 && _nE + _nN < LIM; liv++) {
    const g = SCALA_DISC[Math.min(8, liv)], g1 = SCALA_DISC[Math.min(8, liv + 1)];
    const larg = Math.max(2.4, 5.4 - liv * .5);
    const pross = [];
    for (const p of fronte) {
      for (const f of p.children) {
        if (!vivo(f)) continue;
        if (_nE + _nN >= LIM) break;
        _arco(p.pos, f.pos, g, g1, larg);
        _pallino(f.pos, g1, Math.max(3.5, 7 - liv * .6));
        pross.push(f);
      }
      if (_nE + _nN >= LIM) break;
    }
    fronte = pross;
  }

  // prima tutto il contorno, poi tutto il colore sopra
  _nRami = 0;
  for (let i = 0; i < _nE; i++) ramo(_eA[i], _eB[i], RAMO_ORLO, RAMO_ORLO, _eW[i] + 3.4);
  for (let i = 0; i < _nN; i++) nodo(_nP[i], RAMO_ORLO, _nL[i] + 3.4);
  for (let i = 0; i < _nE; i++) ramo(_eA[i], _eB[i], _eCa[i], _eCb[i], _eW[i]);
  for (let i = 0; i < _nN; i++) nodo(_nP[i], _nC[i], _nL[i]);

  ramiGeo.setDrawRange(0, _nRami * 6);
  ramiGeo.attributes.position.needsUpdate = true;
  ramiGeo.attributes.color.needsUpdate = true;
  alberoEdit.visible = _nRami > 0;
}

/*  Anello dell'esserino selezionato: stessa idea di quello della cellula, ma
 *  attorno a tutto il corpo e sempre, non solo in modifica. Il colore è
 *  pre-compensato per la mappatura tonale (vedi i rami dell'albero): il ciano
 *  chiaro dell'anello della cellula arriva a schermo quasi bianco, e i due
 *  cerchi si sarebbero confusi. Questo esce come un verdeacqua pieno. */
const anelloEss = new THREE.Mesh(
  new THREE.TorusGeometry(1, .022, 8, 64),
  new THREE.MeshBasicMaterial({ color: 0x00a781, transparent: true, opacity: .85,
    depthTest: false, toneMapped: false }));
anelloEss.renderOrder = 946;
anelloEss.frustumCulled = false;
anelloEss.visible = false;
scene.add(anelloEss);

function syncAnelloSel() {
  const cr = world.selected;
  const visto = cr && cr.cells.some(x => !x.dead) && (!world.focus || cr.vessel === world.focus);
  anelloEss.visible = !!visto;
  if (visto) {
    anelloEss.position.copy(cr.centroid);
    anelloEss.scale.setScalar(cr.radius * 1.16 + .04);
    anelloEss.quaternion.copy(camera.quaternion);    // sempre di faccia
  }

  const c = ui.selectedCell;
  if (!editMode || !c || c.dead) { anelloSel.visible = false; alberoEdit.visible = false; return; }
  anelloSel.visible = true;
  anelloSel.position.copy(c.pos);
  anelloSel.scale.setScalar(c.r * 1.9);
  anelloSel.quaternion.copy(camera.quaternion);      // sempre di faccia
  costruisciAlberoEdit(c);
}

/* --- alone di sofferenza ----------------------------------------------
 *  Un anello sfumato che pulsa attorno a chi è in difficoltà: ambra e lento se
 *  ha molta fame, rosso e rapido se sta morendo. Sempre visibile, perché è
 *  l'informazione che serve a colpo d'occhio per intervenire in tempo.
 * -------------------------------------------------------------------- */
const auraTex = (() => {
  const s = 128, cv = document.createElement('canvas');
  cv.width = cv.height = s;
  const g = cv.getContext('2d');
  const grad = g.createRadialGradient(s / 2, s / 2, s * .26, s / 2, s / 2, s * .5);
  grad.addColorStop(0, 'rgba(255,255,255,0)');
  grad.addColorStop(.38, 'rgba(255,255,255,.30)');
  grad.addColorStop(.62, 'rgba(255,255,255,.85)');
  grad.addColorStop(.82, 'rgba(255,255,255,.22)');
  grad.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grad;
  g.beginPath(); g.arc(s / 2, s / 2, s / 2, 0, Math.PI * 2); g.fill();
  return new THREE.CanvasTexture(cv);
})();

const MAX_AURE = 32;
const aure = [];
const AURA_FAME = new THREE.Color(0xffb44a), AURA_MORTE = new THREE.Color(0xff3446);
const _auraCol = new THREE.Color();

function syncAuras(world) {
  const t = performance.now() * .001;      // pulsa anche in pausa
  let i = 0;
  for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) {
      if (!cr.alive || i >= MAX_AURE) continue;
      const fame = 1 - clamp(cr.energy / Math.max(1, cr.capacity), 0, 1);
      const integrita = cr.integrity !== undefined ? cr.integrity : 1;
      const morente = cr.energy <= 1 || integrita < .32;
      /*  TUTTI I CERCHI STANNO SOTTO «Status», allarme compreso: e' quello il
       *  bottone che decide se sopra gli esserini si vedono le loro condizioni,
       *  e un anello rosso che restava acceso a Status spento era l'unica cosa
       *  che quel bottone non governava. Spento, la vasca torna pulita.
       *
       *  Acceso, il colore dice cosa: rosso/arancio urgente per chi muore o ha
       *  fame, altrimenti il colore dello stato mentale — lo stesso
       *  dell'etichetta. `toneMapped:false` sullo sprite lo tiene visibile anche
       *  mentre un effetto luminoso fa buio nella scena. */
      if (!showLabels) continue;
      const allarme = morente || fame >= .72;

      // gravità 0..1: quanto è messo male
      const gravita = morente ? clamp(.6 + (1 - integrita) * .5, .6, 1) : clamp((fame - .72) / .28, 0, .6);
      let sp = aure[i];
      if (!sp) {
        sp = new THREE.Sprite(new THREE.SpriteMaterial({
          map: auraTex, transparent: true, depthWrite: false, toneMapped: false,
          /*  Nessuna prova di profondita'. E' un cartello, non un oggetto:
           *  girato sempre di faccia, quando l'esserino si posa sul fondo il
           *  cerchio sprofondava nel pavimento e ne restava tagliata via la
           *  meta' inferiore, con un bordo netto. Senza la prova passa sopra a
           *  tutto e resta un anello intero. L'ordine di disegno lo tiene
           *  comunque sotto l'anello di selezione e all'albero della modifica. */
          depthTest: false,
        }));
        sp.renderOrder = 900;
        sp.frustumCulled = false;
        scene.add(sp);
        aure[i] = sp;
      }
      // battito: rapido se muore, calmo per il cerchio di stato
      const ritmo = morente ? 5.6 : allarme ? 2.1 : 1.5;
      const battito = .5 + .5 * Math.sin(t * ritmo);
      let raggio = cr.radius * (2.05 + .16 * battito) + .12;
      /*  L'anello resta dentro le pareti e sotto l'orlo: fuori di lì sarebbe
       *  un disco luminoso sospeso nel vuoto, senza più un recipiente attorno.
       *  Verso il BASSO invece non si stringe più: il pavimento non lo taglia
       *  (non fa la prova di profondità) e rimpicciolirlo là sotto voleva dire
       *  che l'allarme si faceva più fioco proprio mentre l'esserino si
       *  accasciava sul fondo, cioè quando serve vederlo. */
      const ves = cr.vessel;
      let spazio = ves.kind === 'tank'
        ? Math.min(ves.w * .5 - Math.abs(cr.centroid.x - ves.pos.x),
                   ves.d * .5 - Math.abs(cr.centroid.z - ves.pos.z))
        : ves.radius - Math.hypot(cr.centroid.x - ves.pos.x, cr.centroid.z - ves.pos.z);
      spazio = Math.min(spazio, ves.pos.y + ves.h - cr.centroid.y);
      raggio = Math.min(raggio, Math.max(cr.radius * 1.15, spazio));
      sp.visible = true;
      sp.position.copy(cr.centroid);
      sp.scale.set(raggio * 2, raggio * 2, 1);
      if (allarme) {
        sp.material.color.copy(morente ? AURA_MORTE : AURA_FAME);
        sp.material.opacity = (morente ? .26 + .42 * battito : .13 + .22 * battito) * (.55 + gravita * .45);
      } else {
        // cerchio di stato: colore dello stato mentale, tenue e calmo
        const st = BRAIN_STATES[cr.state] || BRAIN_STATES.idle;
        sp.material.color.set(st.color);
        sp.material.opacity = .12 + .10 * battito;
      }
      i++;
    }
  }
  for (; i < aure.length; i++) if (aure[i]) aure[i].visible = false;
}

/* --- etichette di stato ---------------------------------------------- */
const labelLayer = document.createElement('div');
labelLayer.style.cssText = 'position:fixed;inset:0;pointer-events:none;z-index:5';
document.body.appendChild(labelLayer);
const labelPool = [];

/*  LA TARGHETTA DEL POV. In alto al centro, stesso stile di quelle che
 *  galleggiano sopra gli esserini in modalita' «Status»: dice chi si sta
 *  seguendo, con stato ed energia che cambiano dal vivo. Sta fissa perche' in
 *  POV la si guarda sempre nello stesso punto, non appesa a un corpo che qui
 *  riempie lo schermo. */
const povBanner = document.createElement('div');
povBanner.style.cssText = 'position:fixed;left:50%;top:54px;transform:translateX(-50%);'
  + 'font:600 11px ui-monospace,monospace;padding:4px 12px;border-radius:6px;'
  + 'background:rgba(8,13,19,.9);border:1px solid rgba(120,190,220,.5);white-space:nowrap;'
  + 'text-shadow:0 1px 2px #000;z-index:12;cursor:pointer;display:none;'
  + 'box-shadow:0 4px 16px rgba(0,0,0,.5)';
/*  E' CLICCABILE: e' il comando POV sempre a portata, qualunque cosa mostri la
 *  scheda a destra. Un click esce dal primo piano. */
povBanner.title = 'Following in POV \u2014 click to leave';
povBanner.onclick = () => { spegniPOV(); if (world.ui) world.ui.refreshInspector(); };
povBanner.onmouseenter = () => povBanner.style.borderColor = 'var(--warn)';
povBanner.onmouseleave = () => povBanner.style.borderColor = 'rgba(120,190,220,.5)';
document.body.appendChild(povBanner);

function aggiornaBannerPOV() {
  if (!povOn || !povCreature || !povCreature.alive) {
    if (povBanner.style.display !== 'none') povBanner.style.display = 'none';
    return;
  }
  const cr = povCreature;
  const st = BRAIN_STATES[cr.state] || BRAIN_STATES.idle;
  povBanner.style.display = 'block';
  povBanner.style.color = st.color;
  povBanner.textContent = `Following: ${cr.name} · ${st.label} · ${Math.round(cr.energy)}⚡`;
  const bpEt = cr.bp && cr.bp.attivo ? cr.bp : null;
  if (bpEt) {
    const b = document.createElement('span');
    b.style.color = '#8ef2c0';
    b.textContent = ` · 🧠${bpEt.nome}`;
    povBanner.appendChild(b);
  }
  const x = document.createElement('span');
  x.style.cssText = 'margin-left:10px;color:#ff9d8f;font-weight:700';
  x.textContent = '✕';
  povBanner.appendChild(x);
}
// acceso all'avvio: è l'informazione che serve subito per capire cosa sta
// facendo un esserino, e cercarla ogni volta era un passaggio di troppo
let showLabels = true;
let showVectors = false;
function syncLabels(world) {
  let i = 0;
  if (showLabels) {
    for (const v of world.vessels) for (const cr of v.creatures) {
      if (!cr.alive || (world.focus && v !== world.focus)) continue;
      let el = labelPool[i];
      if (!el) {
        el = document.createElement('div');
        el.style.cssText = 'position:absolute;transform:translate(-50%,-100%);font:600 10px ui-monospace,monospace;' +
          'padding:2px 6px;border-radius:5px;background:rgba(8,13,19,.7);border:1px solid rgba(120,190,220,.3);white-space:nowrap;text-shadow:0 1px 2px #000';
        labelLayer.appendChild(el); labelPool.push(el);
      }
      _v1.copy(cr.centroid); _v1.y += cr.radius + .16;
      _v1.project(camera);
      if (_v1.z > 1) { el.style.display = 'none'; i++; continue; }
      const st = BRAIN_STATES[cr.state] || BRAIN_STATES.idle;
      el.style.display = 'block';
      el.style.left = ((_v1.x * .5 + .5) * innerWidth) + 'px';
      el.style.top = ((-_v1.y * .5 + .5) * innerHeight) + 'px';
      el.style.color = st.color;
      /*  Chi lo sta pilotando, se non e' il cervello di fabbrica. Va nella
       *  targhetta e non solo nella scheda perche' e' la cosa che spiega un
       *  comportamento che l'algoritmo interno non spiegherebbe, e la si deve
       *  poter leggere guardando la vasca, senza selezionare nessuno.
       *
       *  Il nome del programma ha un colore suo: il resto della riga cambia
       *  tinta con lo stato mentale, e un pezzo che NON la segue si legge
       *  come un'informazione di natura diversa — che e' quel che e'. */
      const bpEt = cr.bp && cr.bp.attivo ? cr.bp : null;
      el.textContent = `${cr.name} · ${st.label} · ${Math.round(cr.energy)}⚡`;
      if (bpEt) {
        const b = document.createElement('span');
        b.style.color = '#8ef2c0';
        b.textContent = ` · 🧠${bpEt.nome}`;
        el.appendChild(b);
      }
      i++;
    }
  }
  for (; i < labelPool.length; i++) labelPool[i].style.display = 'none';
}

/**
 *  Tilt-shift: una fascia orizzontale resta nitida, tutto il resto sfuoca in
 *  modo progressivo. È lo stesso inganno prospettico della fotografia col
 *  banco ottico inclinato: l'occhio legge la sfocatura come profondità di
 *  campo ridottissima, cioè come una scena in miniatura vista da vicino.
 *  La sfocatura è una gaussiana separabile a 9 prese, applicata in due
 *  passaggi (orizzontale e verticale) col raggio modulato dalla distanza
 *  dalla fascia. Il secondo passaggio alza anche un filo la saturazione e il
 *  contrasto, che è l'altra metà dell'effetto modellino.
 */
const TiltShiftShader = {
  uniforms: {
    tDiffuse:    { value: null },
    direzione:   { value: new THREE.Vector2(1, 0) },
    risoluzione: { value: new THREE.Vector2(1 / 1024, 1 / 1024) },
    fuoco:       { value: .5 },     // centro della fascia nitida, in v
    ampiezza:    { value: .13 },    // semiampiezza della fascia nitida
    sfumatura:   { value: .28 },    // quanto lontano si arriva al massimo
    forza:       { value: 6 },      // raggio massimo, in pixel per presa
    satura:      { value: 0 },
  },
  vertexShader: `
    varying vec2 vUv;
    void main() { vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`,
  fragmentShader: `
    uniform sampler2D tDiffuse;
    uniform vec2 direzione, risoluzione;
    uniform float fuoco, ampiezza, sfumatura, forza, satura;
    varying vec2 vUv;
    void main() {
      float d = abs(vUv.y - fuoco);
      float b = clamp((d - ampiezza) / sfumatura, 0.0, 1.0);
      b *= b;                                   // sfoca piano, poi accelera
      vec4 c;
      if (b < 0.004) {
        c = texture2D(tDiffuse, vUv);
      } else {
        vec2 p = direzione * risoluzione * (b * forza);
        c  = texture2D(tDiffuse, vUv - p * 4.0) * 0.0162;
        c += texture2D(tDiffuse, vUv - p * 3.0) * 0.0540;
        c += texture2D(tDiffuse, vUv - p * 2.0) * 0.1216;
        c += texture2D(tDiffuse, vUv - p      ) * 0.1946;
        c += texture2D(tDiffuse, vUv          ) * 0.2272;
        c += texture2D(tDiffuse, vUv + p      ) * 0.1946;
        c += texture2D(tDiffuse, vUv + p * 2.0) * 0.1216;
        c += texture2D(tDiffuse, vUv + p * 3.0) * 0.0540;
        c += texture2D(tDiffuse, vUv + p * 4.0) * 0.0162;
      }
      if (satura > 0.0) {
        float l = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
        c.rgb = mix(vec3(l), c.rgb, 1.0 + satura);
        c.rgb = clamp((c.rgb - 0.5) * 1.07 + 0.5, 0.0, 1.0);
      }
      gl_FragColor = c;
    }`,
};

/* --- post-processing con GTAO ---------------------------------------- */
const composer = new EffectComposer(renderer);
composer.addPass(new RenderPass(scene, camera));
let gtao = null;
if (GTAOPass) {
  gtao = new GTAOPass(scene, camera, innerWidth, innerHeight);
  gtao.output = GTAOPass.OUTPUT.Default;
  gtao.updateGtaoMaterial({ radius: .30, distanceExponent: 1, thickness: .7, scale: 1.7, samples: 16, distanceFallOff: 1, screenSpaceRadius: false });
  gtao.blendIntensity = 1.15;
  gtao.updatePdMaterial({ lumaPhi: 10, depthPhi: 2, normalPhi: 3, radius: 4, radiusExponent: 1, rings: 2, samples: 16 });
  composer.addPass(gtao);
}
const tiltH = new ShaderPass(TiltShiftShader);
const tiltV = new ShaderPass(TiltShiftShader);
tiltH.uniforms.direzione.value.set(1, 0);
tiltV.uniforms.direzione.value.set(0, 1);
tiltV.uniforms.satura.value = .22;              // solo l'ultimo passaggio ritocca il colore
tiltH.enabled = tiltV.enabled = false;
composer.addPass(tiltH);
composer.addPass(tiltV);
composer.addPass(new OutputPass());

/**
 *  La fascia nitida insegue il soggetto: si proietta il bersaglio della
 *  telecamera sullo schermo e si mette lì il centro del fuoco. Così il
 *  recipiente inquadrato resta sempre a fuoco anche ruotando attorno.
 */
const _pFuoco = new THREE.Vector3();
function aggiornaTilt() {
  if (!tiltH.enabled) return;
  _pFuoco.copy(controls.target).project(camera);
  const v = clamp(_pFuoco.y * .5 + .5, 0, 1);
  tiltH.uniforms.fuoco.value = tiltV.uniforms.fuoco.value =
    tiltH.uniforms.fuoco.value + (v - tiltH.uniforms.fuoco.value) * .25;   // insegue morbido
}

// Gli aloni sono quad trasparenti: nel prepass di profondità del GTAO il loro
// rettangolo risulta una superficie piena e proietta un'ombra rettangolare sullo
// sfondo. Li togliamo di mezzo solo per quel passaggio: la scena illuminata è
// già stata disegnata dal RenderPass, quindi restano visibili.
if (gtao) {
  const _gtaoRender = gtao.render.bind(gtao);
  gtao.render = function (renderer, writeBuffer, readBuffer, deltaTime, maskActive) {
    // Nel prepass di profondità l'override rende opaco TUTTO, vetro e acqua
    // compresi: da fuori il guscio del recipiente copriva le cellule e l'AO
    // spariva: si vedeva solo con la telecamera dentro al contenitore.
    const nascosti = [];
    for (const s of aure) if (s && s.visible) { nascosti.push(s); s.visible = false; }
    /*  E fuori anche gli effetti: sono luce e vapore, non materia. Lasciandoli
     *  nel prepass l'occlusione ambientale li spegneva e, peggio, li usava per
     *  spegnere quel che c'era dietro — uno spruzzo d'acido proiettava ombra. */
    for (const s of fxParti) if (s.visible) { nascosti.push(s); s.visible = false; }
    for (const s of ondePool) if (s.visible) { nascosti.push(s); s.visible = false; }
    for (const s of glassParts) if (s.visible) { nascosti.push(s); s.visible = false; }
    _gtaoRender(renderer, writeBuffer, readBuffer, deltaTime, maskActive);
    for (const s of nascosti) s.visible = true;
  };
}

/**
 *  Dimensione della vista, sempre sanificata e verificata a ogni frame.
 *  Se il pannello viene nascosto la finestra può misurare 0×0: i render target
 *  diventano di dimensione nulla e da quel momento OGNI draw call fallisce con
 *  GL_INVALID_FRAMEBUFFER_OPERATION. L'inondazione di messaggi blocca il thread
 *  e non si recupera più. Qui non si scende mai sotto 2 px e, se la vista è
 *  degenere, semplicemente non si disegna.
 */
let viewW = 0, viewH = 0, viewOk = true;
function syncViewport() {
  const cw = innerWidth || 0, ch = innerHeight || 0;
  viewOk = cw >= 4 && ch >= 4;
  const w = Math.max(2, Math.floor(cw)), h = Math.max(2, Math.floor(ch));
  if (w === viewW && h === viewH) return;
  viewW = w; viewH = h;
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  renderer.setSize(w, h);               // aggiorna anche lo stile: il canvas copre la finestra
  composer.setSize(w, h);
  tiltH.uniforms.risoluzione.value.set(1 / w, 1 / h);
  tiltV.uniforms.risoluzione.value.set(1 / w, 1 / h);
  // i punti si misurano in pixel: la conversione dipende da altezza e campo visivo
  uFxScala.value = h / (2 * Math.tan(camera.fov * .5 * Math.PI / 180));
}
addEventListener('resize', syncViewport);

/* --- camera: zoom su un recipiente alla volta ------------------------- */
const cam = { target: new THREE.Vector3(0, 1.2, 0), pos: new THREE.Vector3(0, 3.4, 9), done: true };
function focusVessel(v) {
  if (!v) {   // panoramica: inquadratura ricavata dall'ingombro del bancone
    let minx = Infinity, maxx = -Infinity, minz = Infinity, maxz = -Infinity, maxh = 1;
    for (const vv of world.vessels) {
      const r = vv.kind === 'tank' ? Math.max(vv.w, vv.d) * .5 : vv.radius;
      minx = Math.min(minx, vv.pos.x - r); maxx = Math.max(maxx, vv.pos.x + r);
      minz = Math.min(minz, vv.pos.z - r); maxz = Math.max(maxz, vv.pos.z + r);
      maxh = Math.max(maxh, vv.h);
    }
    if (!isFinite(minx)) { minx = -5; maxx = 5; minz = -5; maxz = 5; }
    const cx = (minx + maxx) * .5, cz = (minz + maxz) * .5;
    const span = Math.max(maxx - minx, maxz - minz);
    cam.target.set(cx, maxh * .38, cz);
    cam.pos.set(cx, span * .52 + maxh, cz + span * 1.02 + 2.5);
  } else {
    const r = v.kind === 'tank' ? Math.max(v.w, v.d) * .75 : v.radius * 2.2;
    cam.target.copy(v.pos).add(new THREE.Vector3(0, v.h * .5, 0));
    cam.pos.copy(cam.target).add(new THREE.Vector3(0, v.h * .7, r + 2.6));
  }
  cam.done = false;
}
let followCell = null;                 // cellula su cui la vista resta centrata

/**
 *  DOVE tenere la cellula seguita — non sempre in mezzo al canvas.
 *
 *  Con il pannello dei materiali aperto in modifica diretta, il centro del
 *  canvas sta SOTTO il pannello: la cellula su cui si sta lavorando finiva
 *  nascosta proprio da ciò che serve a lavorarci. Qui la si porta invece in
 *  mezzo alla striscia di vista che resta libera, fra il bordo destro del
 *  pannello e l'inizio dell'ispettore.
 *
 *  Lo scostamento si misura in PIXEL sullo schermo e si converte in unità di
 *  mondo alla distanza a cui sta la cellula: così vale uguale da vicino e da
 *  lontano, e non cambia se si zooma. `controls.target` è il punto che cade in
 *  mezzo al canvas, quindi per portare la cellula a destra del centro il
 *  bersaglio va spostato a SINISTRA della cellula, non a destra.
 */
const _miraOut = new THREE.Vector3(), _miraDx = new THREE.Vector3();
function miraSeguita(cell, out) {
  out.copy(cell.pos);
  const p = document.getElementById('matpanel');
  if (!editMode || !p || !p.classList.contains('on')) return out;
  const rc = renderer.domElement.getBoundingClientRect();
  const rp = p.getBoundingClientRect();
  if (!rc.width) return out;
  let destra = rc.right;
  const insp = document.getElementById('inspector');
  if (insp) {
    const ri = insp.getBoundingClientRect();
    if (ri.width && ri.left > rp.right) destra = Math.min(destra, ri.left);
  }
  const sinistra = Math.max(rc.left, rp.right);
  // se di striscia libera non ce n'è, si lascia la cellula dov'era: meglio
  // coperta che spinta fuori dall'inquadratura
  if (destra - sinistra < 120) return out;
  const dPix = (sinistra + destra) * .5 - (rc.left + rc.right) * .5;
  if (Math.abs(dPix) < 1) return out;
  const dist = camera.position.distanceTo(cell.pos);
  const mezzaLarghezza = Math.tan(camera.fov * Math.PI / 360) * dist * camera.aspect;
  const off = (dPix / (rc.width * .5)) * mezzaLarghezza;
  _miraDx.setFromMatrixColumn(camera.matrixWorld, 0);        // asse X della camera
  return out.addScaledVector(_miraDx, -off);
}

/* ------------------------------------------------------------------------
 *  POV — GUARDARE DALLA PARTE DELL'ESSERINO
 *
 *  La camera si mette dietro la testa dell'esserino selezionato e guarda dove
 *  il suo cervello ha deciso di andare: la stessa direzione che i «Vectors»
 *  disegnano come freccia, cioe' `desired`. Ma quella direzione BALLA — il
 *  cervello puo' cambiare idea dieci volte al secondo — e una camera che la
 *  seguisse di scatto darebbe la nausea. Quindi non si punta la direzione
 *  vera: si punta una direzione LEVIGATA che le insegue dietro con molto
 *  peso al passato (mezza vita ~0.9 s), cosi' la telecamera vira dolce mentre
 *  l'esserino scatta.
 *
 *  E' un vero primo piano: l'occhio sta sul MUSO dell'esserino — appena
 *  davanti al suo bordo, cosi' il corpo resta dietro la camera e non la
 *  tappa — e guarda dritto avanti lungo la direzione. Non si vede il corpo,
 *  si vede quel che l'esserino ha davanti: e' il suo punto di vista.
 * --------------------------------------------------------------------- */
let povOn = false;
let povCreature = null;
const povDir = new THREE.Vector3(0, 0, 1);   // direzione levigata, in world space
const _povTgt = new THREE.Vector3();          // punto verso cui guardare, se c'e'
let povArmata = false;                        // per prendere la direzione com'e' al primo giro

/**
 *  DOVE GUARDARE in POV. La direzione di marcia (`desired`) da sola non basta:
 *  un esserino che nuota dritto mentre lo attaccano di lato dovrebbe voltarsi
 *  verso chi lo colpisce, non fissare l'orizzonte. Si sceglie un BERSAGLIO a
 *  seconda di cosa sta facendo, e la camera ci punta; solo se non c'e' niente
 *  di saliente si ripiega sulla direzione in cui va.
 *
 *  Torna true e riempie `_povTgt` col punto da guardare, oppure false.
 */
function povGuardaVerso(cr) {
  // sotto attacco fresco: il nemico che colpisce si prende l'attenzione
  const agg = cr.lastDamageFrom;
  if (cr.pain > .35 && agg && agg.alive && agg !== cr) { _povTgt.copy(agg.centroid); return true; }
  // in combattimento: la cellula presa di mira, o il corpo del nemico
  const tc = cr.targetCell;
  if (tc && !tc.dead && tc.creature && tc.creature.alive) { _povTgt.copy(tc.pos); return true; }
  const tcr = cr.targetCreature;
  if (tcr && tcr.alive) { _povTgt.copy(tcr.centroid); return true; }
  // mentre mangia: il boccone
  const tf = cr.targetFood;
  if (tf && !tf.dead && tf.pos) { _povTgt.copy(tf.pos); return true; }
  /*  Fuori da un bersaglio esplicito, quel che i sensi hanno appena riportato
   *  di piu' vicino: una preda avvistata, o del cibo. Cosi' l'esserino «guarda»
   *  quel che sta per inseguire prima ancora di puntarlo. */
  let vic = null, vd = Infinity;
  for (const p of cr.percepts) {
    if (!p || p.dist >= vd) continue;
    if (p.kind === 'creature' && (!p.obj || !p.obj.alive || cr.inTregua(p.obj, world.time))) continue;
    vd = p.dist; vic = p;
  }
  if (vic && vic.pos && vd < 5) { _povTgt.copy(vic.pos); return true; }
  return false;                    // niente di saliente: si guarda dove si va
}
/*  IL CAMPO VISIVO. Largo in POV — 100°, come una lente da azione: dà l'aria
 *  di stare DENTRO alla scena invece di guardarla da fuori, ed e' quel che
 *  fa sembrare il primo piano un primo piano. Fuori dal POV torna ai 45° di
 *  sempre. Non salta: `fovVoluto` e' il bersaglio, e la camera ci arriva
 *  morbida come per la posizione. */
/*  Campo largo in POV: 120° danno l'aria di stare dentro la scena senza la
 *  distorsione feroce degli angoli estremi (a 179 il centro si rimpicciolisce
 *  e i bordi sfuggono; sopra i 179 la proiezione degenera del tutto). */
const CAM_FOV = 45, POV_FOV = 120;
let fovVoluto = CAM_FOV;

function accendiPOV(cr) {
  if (!cr || !cr.alive) return;
  povCreature = cr; povOn = true; povArmata = false;
  followCell = null;              // niente doppio inseguimento
  fovVoluto = POV_FOV;            // campo largo: si e' dentro la scena
  cam.done = true;
}
function spegniPOV() {
  fovVoluto = CAM_FOV;            // si torna al campo normale
  /*  E la camera si ritira DIETRO l'esserino che si seguiva, guardandolo, e
   *  arretra di un bel po': uscire dal primo piano e ritrovarsi col muso
   *  incollato al corpo disorienta. Vale ANCHE quando l'esserino e' appena
   *  morto — anzi soprattutto: e' il caso in cui la camera resterebbe piantata
   *  dentro al cadavere. Non si chiede piu' `alive`, basta che il corpo ci sia
   *  ancora (il centroide resta valido finche' non viene rimosso). */
  const cr = povCreature;
  if (cr && cr.centroid) {
    const R = cr.radius || .5;
    cam.target.copy(cr.centroid);
    cam.pos.copy(cr.centroid)
      .addScaledVector(povDir, -(R * 4.5 + 4.0))
      .add(new THREE.Vector3(0, R * 1.5 + 1.4, 0));
    cam.done = false;
    followCell = null;
  }
  povOn = false; povCreature = null;
  controls.enabled = true;
  povBanner.style.display = 'none';
}

/** guida la camera in POV; torna true se ha preso il comando */
function aggiornaPOV(dt) {
  if (!povOn || !povCreature) return false;
  const cr = povCreature;
  if (!cr.alive) { spegniPOV(); if (world.ui) world.ui.refreshInspector(); return false; }

  // verso il bersaglio se c'e' n'e' uno che conta, altrimenti dove si va
  if (povGuardaVerso(cr)) _v1.copy(_povTgt).sub(cr.centroid);
  else _v1.copy(cr.desired);
  if (_v1.lengthSq() < 1e-8) cr.forward(_v1);
  _v1.normalize();
  /*  NIENTE SGUARDI TROPPO RIPIDI, per due motivi che si curano insieme. Uno:
   *  col muso alzato la vista scavalcava il bordo della vasca e usciva
   *  sull'acqua nera. Due, e piu' insidioso: uno sguardo DRITTO in su mette la
   *  mira esattamente sopra la camera, che e' la singolarita' polare
   *  dell'orbita — e li' la telecamera SALTA via (era questo a farla «uscire
   *  dalla vasca»). Si limita la pendenza a una FRAZIONE dell'orizzontale, e
   *  si garantisce sempre un po' d'orizzontale, cosi' la mira non e' mai
   *  sopra la testa e la pendenza resta dolce. */
  let hor = Math.hypot(_v1.x, _v1.z);
  if (hor < 1e-4) {                 // sguardo verticale puro: l'orizzontale dal muso
    cr.forward(_v1); _v1.y = 0;
    hor = Math.hypot(_v1.x, _v1.z);
    if (hor < 1e-4) { _v1.set(0, 0, 1); hor = 1; }
  }
  _v1.y = clamp(_v1.y, -hor * .8, hor * .55);    // giu' ~39°, su ~29°
  _v1.normalize();
  if (!povArmata) { povDir.copy(_v1); povArmata = true; }
  else {
    /*  Si RUOTA `povDir` verso la voluta, non si fa il lerp: due versori
     *  opposti mescolati passano per lo zero e la normalizzazione li rimette
     *  come prima — la camera si sarebbe piantata a ogni inversione. Girando
     *  di una frazione dell'angolo rimasto a ogni fotogramma, invece, anche
     *  un dietrofront lo si copre, dolce. La frazione e' piccola apposta:
     *  mezza vita ~0.87 s, molto peso alla direzione attuale. */
    const a = 1 - Math.pow(.45, Math.min(dt, .1));
    const cosang = clamp(povDir.dot(_v1), -1, 1);
    const ang = Math.acos(cosang);
    if (ang > 1e-4) {
      _v5.crossVectors(povDir, _v1);
      if (_v5.lengthSq() < 1e-10) {                 // opposti: un asse qualunque, perpendicolare
        _v5.set(0, 1, 0).cross(povDir);
        if (_v5.lengthSq() < 1e-10) _v5.set(1, 0, 0).cross(povDir);
      }
      _v5.normalize();
      povDir.applyAxisAngle(_v5, ang * a).normalize();
    }
  }

  const R = cr.radius;
  /*  L'occhio sta DENTRO il corpo, un po' avanti del centro — `R * .3` lungo
   *  la direzione — con un filo d'alzata per l'altezza della «testa». Col
   *  campo largo cosi' il corpo avvolge i bordi dell'inquadratura e si guarda
   *  fuori da dentro, che e' l'effetto voluto. La mira e' molto piu' avanti,
   *  cosi' lo sguardo e' quasi parallelo alla direzione e non tuffato giu'. */
  /*  L'occhio sta APPENA OLTRE il muso — cosi' il corpo resta dietro la camera
   *  e non le finisce davanti — con un filo d'alzata per l'altezza della
   *  «testa». Piu' avanti di prima proprio per questo: dentro al corpo il
   *  tessuto copriva la lente. La mira e' molto piu' avanti, cosi' lo sguardo
   *  e' quasi parallelo alla direzione e non tuffato in basso. */
  /*  LA POSIZIONE sta all'ALTEZZA DEL CENTRO della creatura — dove sta il
   *  cervello — non rialzata: spinta avanti sul PIANO orizzontale, cosi' il
   *  corpo non le finisce davanti ma l'occhio resta al livello del centro.
   *  La MIRA invece tiene la pendenza vera verso il bersaglio, cosi' si guarda
   *  anche in su o in giu' quando serve. */
  _v3.set(povDir.x, 0, povDir.z);
  if (_v3.lengthSq() < 1e-6) { cr.forward(_v3); _v3.y = 0; }   // sguardo verticale: si usa il muso
  if (_v3.lengthSq() < 1e-6) _v3.set(0, 0, 1);
  _v3.normalize();
  const occhio = _v2.copy(cr.centroid).addScaledVector(_v3, R * .62);
  occhio.y = cr.centroid.y;
  const mira = _v4.copy(cr.centroid).addScaledVector(povDir, R + 2.5);

  // ci si arriva morbidi: il corpo ondeggia, seguirlo di scatto ballerebbe
  const b = 1 - Math.pow(.02, Math.min(dt, .1));
  camera.position.lerp(occhio, b);
  controls.target.lerp(mira, b);
  /*  LA CAMERA RESTA DENTRO IL CONTENITORE. Se l'occhio sporge verso una
   *  parete — l'esserino ci nuota contro guardando fuori — la si ricaccia
   *  dentro con la stessa `contain` che tiene le cellule al loro posto, con un
   *  margine perche' non tocchi il vetro. Cosi' non si vede mai la scena da
   *  fuori la vasca. */
  if (cr.vessel) cr.vessel.contain(camera.position, .32);
  controls.enabled = false;       // in POV l'orbita e' bloccata
  cam.done = true;                 // niente transizioni in mezzo
  controls.update();
  return true;
}

function updateCamera(dt) {
  aggiornaBannerPOV();
  // il campo visivo insegue il suo bersaglio, POV o no: e' indipendente da
  // dove sta la camera, quindi si aggiorna sempre, prima di tutto il resto
  if (Math.abs(camera.fov - fovVoluto) > .04) {
    const a = 1 - Math.pow(.03, Math.min(dt, .1));
    camera.fov += (fovVoluto - camera.fov) * a;
    if (Math.abs(camera.fov - fovVoluto) < .04) camera.fov = fovVoluto;
    camera.updateProjectionMatrix();
  }
  if (aggiornaPOV(dt)) return;
  // La cellula scelta diventa il perno dell'orbita e la vista la insegue:
  // la camera trasla dello stesso spostamento, così l'inquadratura non ruota.
  // Mai durante un trascinamento: la cellula segue il puntatore e la camera
  // seguirebbe lei, col risultato che a scorrere sarebbe tutta la scena.
  if (followCell && !drag.active) {
    if (followCell.dead) followCell = null;
    else {
      _v1.copy(miraSeguita(followCell, _miraOut)).sub(controls.target);
      if (_v1.lengthSq() > 1e-10) {
        _v1.multiplyScalar(.14);
        controls.target.add(_v1);
        camera.position.add(_v1);
      }
    }
  }
  if (!cam.done) {
    const a = 1 - Math.pow(.006, Math.min(dt, .1));      // indipendente dal frame rate
    controls.target.lerp(cam.target, a);
    camera.position.lerp(cam.pos, a);
    if (camera.position.distanceTo(cam.pos) < .02 && controls.target.distanceTo(cam.target) < .02) cam.done = true;
  }
  controls.update();
}
// se l'utente muove la vista, la transizione si interrompe
controls.addEventListener('start', () => { cam.done = true; });

/* =============================================================================
 * 7. MONDO INIZIALE
 * ========================================================================== */

const world = new World();
const tank = world.addVessel('tank');
const jar1 = world.addVessel('jar');
const jar2 = world.addVessel('jar');
world.layout();
for (const v of world.vessels) buildVesselMesh(v);

/** costruisce un esserino da una ricetta di cellule */
/**
 *  Ristruttura e rimette a posto chi puntava alle cellule vecchie: dopo il
 *  rimontaggio gli oggetti Cell sono altri, e cerchio di modifica, perno
 *  dell'orbita e trascinamento in corso resterebbero appesi al nulla.
 */
function ristrutturaEsserino(cr) {
  /*  Dov'era prima. Rimontare il corpo ricalcola le pose di riposo da capo, e
   *  il baricentro che ne esce non e' quello di prima: l'esserino compariva
   *  spostato di lato, come se fosse saltato. Si rimette dov'era. */
  const dove = cr.centroidOf(new THREE.Vector3());
  const n = cr.ristruttura();
  if (!n) return 0;
  const ora = cr.centroidOf(_v1);
  const scarto = dove.sub(ora);
  if (scarto.lengthSq() > 1e-10) {
    // in Verlet si sposta anche `prev`, o la traslazione varrebbe come una
    // spinta e il corpo schizzerebbe via
    for (const c of cr.cells) { c.pos.add(scarto); c.prev.add(scarto); }
    cr.origin.add(scarto);
    cr.centroidOf(cr.centroid);
  }
  if (ui.selectedCell && ui.selectedCell.creature === cr) ui.selectedCell = null;
  if (followCell && followCell.creature === cr) followCell = null;
  if (drag.cell && drag.cell.creature === cr) {
    drag.active = false; drag.cell = null; drag.cells = null;
    controls.enabled = true;
  }
  return n;
}

function buildFromRecipe(vessel, dna, recipe, name) {
  const cr = world.addCreature(dna, vessel, name);
  cr.addCell('brain');
  for (const [type, n] of recipe) for (let i = 0; i < n; i++) cr.addCell(type);
  cr.rebuild();
  // parte già cresciuto a metà e nutrito
  for (const c of cr.cells) { c.age = 18; c.r = c.r0 * .8; }
  cr.energy = cr.capacity * .7;
  return cr;
}

/* --- esserini salvati nel browser ------------------------------------
 *  Si registra il DNA e la SEQUENZA dei tipi cellulari nell'ordine di montaggio:
 *  con lo stesso seme l'algoritmo di assemblaggio è deterministico, quindi
 *  ricostruisce esattamente lo stesso corpo.
 * -------------------------------------------------------------------- */
const SAVE_KEY = 'cells:esserini:v1';

function loadSaved() {
  try {
    const l = JSON.parse(localStorage.getItem(SAVE_KEY));
    return Array.isArray(l) ? l : [];
  } catch (e) { return []; }
}

/**
 *  La struttura vera dell'esserino, non la sola distinta dei tipi.
 *
 *  Salvare `['muscle','muscle','eye',…]` e rimontare per tipo significa
 *  lasciar ridecidere al montaggio automatico dove va ogni cellula: tutto ciò
 *  che era stato costruito a mano — innesti, arti, simmetrie volute — andava
 *  perso, e si riotteneva soltanto quello che il DNA avrebbe generato da solo.
 *  Qui si scrive l'albero come è adesso, con la posa di riposo di ognuna, in
 *  ordine di padre prima del figlio, più gli arti con la loro spalla.
 *
 *  Le morte non si salvano e i loro figli risalgono al primo antenato vivo,
 *  esattamente come fa l'asportazione a mano.
 */
/* ==========================================================================
 *  L'ALBERO DEL CORPO — un formato solo, per leggere e per rimontare
 *
 *  `strutturaDi` serve al salvataggio su file: e' una lista piatta con gli
 *  indici del padre, ottima da serializzare e pessima da leggere per chi
 *  scrive un BrainProgram. Questo e' lo stesso corpo detto ad albero, con
 *  ogni cellula che si porta dietro quel che serve a decidere: che arma e',
 *  quanta corazza ha, su quale arto sta e quanto e' sepolta.
 *
 *  E' LO STESSO FORMATO IN LETTURA E IN SCRITTURA. Si legge il nemico con
 *  `scan`, si legge se stessi con `tree`, si rimonta con `restructure`
 *  passando un albero della stessa forma. In scrittura contano solo `type`,
 *  `children` e — se c'e' — `limb` e `id`; tutto il resto viene ignorato,
 *  cosi' un albero appena letto si puo' modificare e restituire com'e'.
 * ====================================================================== */

/**
 *  UN NODO DEL CORPO.
 *
 *  Tutto quel che descrive la cellula — tipo, identita', ferite, corazza,
 *  profondita' — sta dietro un GETTER, e in strict mode (che e' come gira
 *  ogni BrainProgram) assegnare a una proprieta' che ha solo il getter
 *  LANCIA. E' la differenza fra scoprire di aver sbagliato sulla riga in cui
 *  si e' sbagliato, con tanto di numero nella console del Debug, e scoprirlo
 *  tre passi dopo sotto forma di «il censimento non torna» — o, peggio, non
 *  scoprirlo affatto perche' la modifica e' stata ignorata in silenzio.
 *
 *  Restano modificabili le DUE SOLE cose che `restructure` legge davvero e
 *  che descrivono un progetto invece di un fatto: `children`, cioe' chi si
 *  attacca a chi, e `limb`, cioe' quali cellule formano un arto. Il resto e'
 *  la cellula, e la cellula non si cambia scrivendoci sopra.
 *
 *  I valori si leggono dalla cellula VIVA a ogni accesso: dentro un `think`
 *  non cambia niente, ma un albero tenuto da parte per qualche fotogramma
 *  dice come stanno le cose adesso, non come stavano.
 */
class NodoCorpo {
  constructor(cella, prof, limbIdx) {
    this._c = cella;
    this._prof = prof;
    this._limb = limbIdx;
    /** i figli: e' il piano, e si riordina liberamente */
    this.children = [];
    /*  SIGILLATO. Senza, scrivere `node.limb = 2` o `node.childs = […]` non
     *  darebbe errore: creerebbe una proprieta' nuova che nessuno legge, e il
     *  programma continuerebbe convinto di aver detto qualcosa. Sigillando,
     *  in strict mode ogni nome che non esiste lancia sul posto. Restano
     *  scrivibili le proprieta' che ci sono gia', cioe' `children`. */
    Object.seal(this);
  }
  get type() { return this._c.type; }
  get id() { return this._c.id; }
  get name() { return this._c.def.name; }
  get category() { return this._c.def.cat; }
  get depth() { return this._prof; }
  get alive() { return !this._c.dead; }
  get hp() { return this._c.hp; }
  get hpMax() { return this._c.maxHp; }
  get health() { return this._c.maxHp > 0 ? clamp(this._c.hp / this._c.maxHp, 0, 1) : 0; }
  get armor() { return this._c.armorEff; }
  get vital() { return this._c.vital; }
  get innervation() { return this._c.innerv; }
  get radius() { return this._c.r; }
  get pos() { const p = this._c.pos; return { x: p.x, y: p.y, z: p.z }; }
  get rest() { const p = this._c.restPos; return { x: p.x, y: p.y, z: p.z }; }
  /** vero solo sulle cellule che possono fare male: e' il modo di riconoscerle */
  get weapon() { const d = this._c.def; return (d.cat === 'attack' || !!d.contact || !!d.impact) || undefined; }
  get range() {
    const d = this._c.def;
    if (!this.weapon) return undefined;
    return d.radius || d.reach || (d.contact || d.impact ? this._c.r * 1.4 : 0) || 0;
  }
  get power() {
    const d = this._c.def;
    if (!this.weapon) return undefined;
    return d.dps || d.burst || d.contact || d.impact || 0;
  }
  get ready() { return this.weapon ? (this._c.cool <= 0 && this._c.ricT <= 0) : undefined; }

  /**
   *  E' una cellula di un arto?
   *
   *  E' una DOMANDA, non un'impostazione. Prima era un numero scrivibile, e
   *  quel numero era l'unico posto da cui potesse uscire un corpo storto: un
   *  `NaN`, un gruppo spezzato in due rami, un gruppo che includeva la
   *  radice. Tutte cose che si potevano solo rifiutare o correggere dopo.
   *
   *  Adesso non esiste piu' niente da rifiutare, perche' non c'e' piu' niente
   *  da scrivere: gli arti li ricava `restructureFromTree` da quali cellule
   *  ne facevano parte — che sono le stesse cellule — seguendo l'albero che
   *  gli si e' dato. Chi scrive il programma dice CHI SI ATTACCA A CHI, e gli
   *  arti seguono. Uno stato invalido non e' piu' rappresentabile.
   */
  isLimb() { return this._limb >= 0; }

  /** una copia del piano che punta alle stesse cellule: per provare varianti */
  clone() {
    const n = new NodoCorpo(this._c, this._prof, this._limb);
    for (const f of this.children) n.children.push(f.clone());
    return n;
  }
  /*  Senza questo un `JSON.stringify` emetterebbe il solo `children`: i getter
   *  stanno sul prototipo e non sono enumerabili. Cosi' invece l'albero si
   *  stampa e si serializza per intero, e quel che ne esce e' un albero
   *  semplice che `restructure` accetta comunque. */
  toJSON() {
    const o = { type: this.type, id: this.id, name: this.name, category: this.category,
                depth: this.depth, isLimb: this.isLimb(), hp: this.hp, hpMax: this.hpMax,
                health: this.health, armor: this.armor, vital: this.vital,
                innervation: this.innervation, radius: this.radius,
                pos: this.pos, rest: this.rest };
    if (this.weapon) { o.weapon = true; o.range = this.range; o.power = this.power; o.ready = this.ready; }
    o.children = this.children.map(c => c.toJSON());
    return o;
  }
  toString() { return `${this.name}#${this.id} d${this.depth}${this.isLimb() ? ' limb' : ''}`; }
}

function nodoCella(c, prof, limbIdx) { return new NodoCorpo(c, prof, limbIdx); }

/**
 *  Il corpo di un esserino, ad albero. Le cellule morte non ci sono, e chi
 *  aveva per padre una cellula morta si riappende al primo antenato vivo:
 *  quel che si legge e' il corpo com'e' adesso, non com'era.
 */
function alberoDi(cr) {
  const vive = cr.cells.filter(c => !c.dead);
  if (!vive.length) return null;
  const vivo = new Set(vive);
  const limbIdx = new Map();
  cr.limbs.forEach((L, i) => { for (const c of L.cells) limbIdx.set(c, i); });

  const padreDi = new Map();
  for (const c of vive) {
    let p = c.parent;
    while (p && !vivo.has(p)) p = p.parent;
    padreDi.set(c, p || null);
  }
  const figli = new Map(), radici = [];
  for (const c of vive) {
    const p = padreDi.get(c);
    if (!p) radici.push(c);
    else { if (!figli.has(p)) figli.set(p, []); figli.get(p).push(c); }
  }
  if (!radici.length) return null;
  /*  Un corpo puo' essersi spezzato e avere piu' radici: si tiene la piu'
   *  grossa e le altre si appendono a lei, o l'albero non descriverebbe
   *  l'esserino ma solo un suo pezzo. */
  const radice = radici.find(c => c.type === 'brain') || radici[0];

  const nodi = new Map();
  const out = nodoCella(radice, 0, limbIdx.has(radice) ? limbIdx.get(radice) : -1);
  nodi.set(radice, out);
  // discesa iterativa: una catena lunga non deve poter sfondare lo stack
  const pila = [radice];
  while (pila.length) {
    const c = pila.pop();
    const mio = nodi.get(c);
    for (const f of (figli.get(c) || [])) {
      if (nodi.has(f)) continue;
      const n = nodoCella(f, mio.depth + 1, limbIdx.has(f) ? limbIdx.get(f) : -1);
      nodi.set(f, n); mio.children.push(n); pila.push(f);
    }
  }
  // i tronconi staccati si appendono alla radice: meglio storti che assenti
  for (const c of radici) {
    if (c === radice || nodi.has(c)) continue;
    const n = nodoCella(c, 1, limbIdx.has(c) ? limbIdx.get(c) : -1);
    nodi.set(c, n); out.children.push(n); pila.push(c);
    while (pila.length) {
      const k = pila.pop(), mio = nodi.get(k);
      for (const f of (figli.get(k) || [])) {
        if (nodi.has(f)) continue;
        const nf = nodoCella(f, mio.depth + 1, limbIdx.has(f) ? limbIdx.get(f) : -1);
        nodi.set(f, nf); mio.children.push(nf); pila.push(f);
      }
    }
  }
  return out;
}

/** tutti i nodi di un albero, in una lista piatta */
function alberoPiatto(albero, max = MAX_CELLULE + 8) {
  const out = [];
  if (!albero || typeof albero !== 'object') return out;
  const pila = [albero], visti = new Set();
  while (pila.length && out.length <= max) {
    const n = pila.pop();
    if (!n || typeof n !== 'object' || visti.has(n)) continue;
    visti.add(n); out.push(n);
    const f = n.children;
    if (Array.isArray(f)) for (let i = f.length - 1; i >= 0; i--) pila.push(f[i]);
  }
  return out;
}

function strutturaDi(cr) {
  const vive = cr.cells.filter(c => !c.dead);
  const vivo = new Set(vive);
  const padreDi = new Map();
  for (const c of vive) {
    let p = c.parent;
    while (p && !vivo.has(p)) p = p.parent;
    padreDi.set(c, p || null);
  }
  const figli = new Map(), radici = [];
  for (const c of vive) {
    const p = padreDi.get(c);
    if (!p) radici.push(c);
    else { if (!figli.has(p)) figli.set(p, []); figli.get(p).push(c); }
  }
  // discesa iterativa: una catena di 260 cellule non deve poter sfondare lo stack
  const ordine = [], indice = new Map(), pila = radici.slice().reverse();
  while (pila.length) {
    const c = pila.pop();
    if (indice.has(c)) continue;
    indice.set(c, ordine.length);
    ordine.push(c);
    const f = figli.get(c);
    if (f) for (let i = f.length - 1; i >= 0; i--) pila.push(f[i]);
  }
  const r4 = v => Math.round(v * 1e4) / 1e4;
  const celle = ordine.map(c => {
    const p = padreDi.get(c);
    const o = { t: c.type, p: p && indice.has(p) ? indice.get(p) : -1,
                x: r4(c.restPos.x), y: r4(c.restPos.y), z: r4(c.restPos.z) };
    // il marchio si scrive solo quando c'e': un salvataggio di un corpo
    // cresciuto da solo non deve ingrassare di un campo sempre falso
    if (c.manuale) o.m = 1;
    return o;
  });
  const arti = cr.limbs
    .filter(L => L.base && indice.has(L.base))
    .map(L => ({ b: indice.get(L.base), s: L.side,
                 d: [r4(L.dir.x), r4(L.dir.y), r4(L.dir.z)],
                 c: L.cells.filter(c => indice.has(c)).map(c => indice.get(c)) }));
  return { celle, arti };
}

function saveCreature(cr, nome) {
  const list = loadSaved().filter(s => s.nome !== nome);
  const st = strutturaDi(cr);
  list.push({
    nome, quando: Date.now(), v: 2,
    dna: { ...cr.dna },
    celle: st.celle, arti: st.arti,
    // la vecchia distinta resta: la usa l'etichetta del menù, ed è la scialuppa
    // per un salvataggio riaperto da una versione che non conosce la struttura
    cellule: st.celle.map(c => c.t),
  });
  list.sort((a, b) => a.nome.localeCompare(b.nome));
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(list)); return true; }
  catch (e) { world.log('Browser storage full: not saved'); return false; }
}

function deleteSaved(nome) {
  const list = loadSaved().filter(s => s.nome !== nome);
  try { localStorage.setItem(SAVE_KEY, JSON.stringify(list)); return true; }
  catch (e) { return false; }
}

/* --- ESSERINI SU FILE ------------------------------------------------------
 *  Lo stesso record che va in `localStorage`, ma su disco: cosi' un esserino
 *  si passa a un'altra persona, si tiene fuori dal browser — dove basta
 *  svuotare la cache per perderlo — e si mette sotto controllo di versione.
 *
 *  Il formato non e' nuovo: e' `strutturaDi` piu' il DNA, cioe' l'albero delle
 *  cellule con la posa di riposo di ognuna e gli arti con la loro spalla.
 *  Inventarne un secondo avrebbe voluto dire mantenerne due.
 * ------------------------------------------------------------------------ */
function esserinoInFile(cr) {
  const st = strutturaDi(cr);
  return {
    formato: 'cells.creature', v: 2,
    nome: cr.name, quando: Date.now(),
    dna: { ...cr.dna },
    celle: st.celle, arti: st.arti,
    cellule: st.celle.map(c => c.t),
  };
}

function esportaEsserino(cr) {
  const rec = esserinoInFile(cr);
  const testo = JSON.stringify(rec, null, 1);
  const nomeFile = (cr.name || 'creature').replace(/[^\w\-. ]+/g, '_').trim() + '.cells.json';
  const url = URL.createObjectURL(new Blob([testo], { type: 'application/json' }));
  const a = document.createElement('a');
  a.href = url; a.download = nomeFile;
  document.body.appendChild(a); a.click(); a.remove();
  // l'oggetto vive finche' il download non e' partito: un attimo basta
  setTimeout(() => URL.revokeObjectURL(url), 4000);
  world.log(`<b>${cr.name}</b> exported as <b>${nomeFile}</b> (${(testo.length / 1024).toFixed(1)} kB)`);
}

/**
 *  Legge un file e ci rimette dentro l'esserino.
 *
 *  Accetta sia il formato del file sia un record uscito dai salvataggi del
 *  browser — sono la stessa cosa a meno dell'etichetta — e in mancanza della
 *  struttura si ripiega sulla vecchia distinta dei tipi, che ricostruisce un
 *  corpo simile invece di rifiutare tutto.
 */
function importaEsserino(testo, vessel, nomeFile) {
  let rec;
  try { rec = JSON.parse(testo); }
  catch (e) { world.log('That file is not readable JSON'); return null; }
  if (!rec || !rec.dna || (!Array.isArray(rec.celle) && !Array.isArray(rec.cellule))) {
    world.log('That file does not contain a creature'); return null;
  }
  const ves = vessel || ui.activeVessel || jar1;
  if (ves.vivi > 11) { world.log('Vessel full.'); return null; }
  rec = { ...rec, nome: nomeUnico(rec.nome || (nomeFile || 'imported').replace(/\.[^.]*$/, '')) };
  const cr = spawnSaved(rec, ves);
  if (!cr) { world.log('Import failed'); return null; }
  world.selected = cr;
  world.log(`<b>${cr.name}</b> imported into ${ves.name} (${cr.cells.length} cells)`);
  ui.refreshInspector(); ui.refreshVessels();
  return cr;
}

/*  IL FILE LASCIATO CADERE SULLA FINESTRA. Vale ovunque, non solo sulla tela:
 *  mirare la tela mentre si trascina e' un compito in piu' senza motivo. Si
 *  annulla `dragover` perche' altrimenti il browser aprirebbe il file al posto
 *  della pagina, che e' il suo comportamento di fabbrica. */
addEventListener('dragover', e => { e.preventDefault(); e.dataTransfer.dropEffect = 'copy'; });
addEventListener('drop', e => {
  const f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];
  if (!f) return;
  e.preventDefault();
  const r = new FileReader();
  /*  Un .js non e' un esserino: e' un cervello, e va addosso a un esserino che
   *  esiste gia'. Quello sotto al cursore se c'e' — lasciare cadere il file
   *  proprio su di lui e' il modo piu' diretto di dire quale — altrimenti il
   *  selezionato. */
  if (/\.(m?js)$/i.test(f.name)) {
    const sotto = pickCell(e);
    const cr = (sotto && sotto.cell.creature.alive ? sotto.cell.creature : null) || world.selected;
    if (!cr || !cr.alive) {
      world.log(`<b>${f.name}</b> is a brain program: drop it on a living creature, or select one first`);
      return;
    }
    r.onload = () => {
      avviaBrainProgram(cr, String(r.result), f.name.replace(/\.[^.]*$/, ''));
      world.selected = cr;
      ui.refreshInspector();
    };
    r.onerror = () => world.log(`Could not read <b>${f.name}</b>`);
    r.readAsText(f);
    return;
  }
  r.onload = () => importaEsserino(String(r.result), vesselAt(e) || ui.activeVessel, f.name);
  r.onerror = () => world.log(`Could not read <b>${f.name}</b>`);
  r.readAsText(f);
});

function spawnSaved(rec, vessel) {
  const cr = world.addCreature({ ...rec.dna }, vessel, rec.nome);
  if (Array.isArray(rec.celle) && rec.celle.length) {
    // struttura esatta: le cellule si posano dove erano, non dove il
    // montaggio automatico le rimetterebbe
    const fatte = [];
    for (const s of rec.celle) {
      if (!CELL_TYPES[s.t] || cr.cells.length >= MAX_CELLULE) { fatte.push(null); continue; }
      const cell = new Cell(cr, s.t, cr.rng);
      cell.restPos.set(s.x, s.y, s.z);
      cell.pos.copy(cr.origin).add(cell.restPos);   // alla nascita l'orientamento è identità
      cell.prev.copy(cell.pos);
      if (s.m) cell.manuale = true;
      cr._register(cell, s.p >= 0 ? fatte[s.p] || null : null);
      fatte.push(cell);
    }
    for (const a of rec.arti || []) {
      const base = fatte[a.b];
      if (!base) continue;
      // il costruttore legge limbs.length per la fase: si accoda DOPO averlo
      // creato, così l'ordine degli arti resta quello salvato
      const limb = new Limb(cr, base, new THREE.Vector3(a.d[0], a.d[1], a.d[2]), a.s || 1);
      cr.limbs.push(limb);
      for (const i of a.c) {
        const c = fatte[i];
        if (c && c !== base && !c.limb) { c.limb = limb; limb.cells.push(c); }
      }
      limb.refresh();
    }
    cr.dirty = true;
  } else {
    // formato vecchio: c'era solo la distinta dei tipi, decide il montaggio
    const tipi = (rec.cellule || []).slice();
    if (tipi[0] !== 'brain') tipi.unshift('brain');     // il montaggio parte dal cervello
    for (const t of tipi) if (CELL_TYPES[t]) cr.addCell(t);
  }
  cr.rebuild();
  for (const c of cr.cells) { c.age = 18; c.r = c.r0 * .8; }
  cr.energy = cr.capacity * .7;
  return cr;
}

/**
 *  Corredo con cui nasce un esserino nuovo: chiude la catena percepire →
 *  raggiungere → ingerire, e porta già l'arma dettata dall'indole del DNA,
 *  perché senza non potrebbe aprire una preda viva. I muscoli vengono prima
 *  dell'arma di proposito: così esiste già un arto su cui montarla in punta.
 */
/**
 *  Garantisce un nome non già in uso: se occupato, appende un numero.
 *  `escluso` è l'esserino che il nome ce l'ha già e se lo può tenere — serve a
 *  chi si RINOMINA, che altrimenti si troverebbe in conflitto con se stesso e
 *  diventerebbe «Pippo 2».
 */
function nomeUnico(base, escluso) {
  const usati = new Set();
  for (const v of world.vessels) for (const c of v.creatures) if (c !== escluso) usati.add(c.name);
  if (!usati.has(base)) return base;
  let i = 2;
  while (usati.has(base + ' ' + i)) i++;
  return base + ' ' + i;
}

/**
 *  UNA RICETTA E' UNA PROPORZIONE, non un elenco di conteggi.
 *
 *  Le ricette scritte in questo file dicono «sedici muscoli, venti nervose» e
 *  quei numeri hanno senso soltanto rispetto al corpo per cui furono scritti,
 *  duecentocinquanta cellule. Con la manopola del pannello a 400 lo stesso
 *  elenco darebbe un esserino identico a prima che poi cresce a caso; a 50
 *  darebbe un corpo già oltre il tetto. Qui i conteggi si rileggono per quello
 *  che sono — percentuali del corpo — e si riscalano.
 *
 *  Il riparto è a RESTO MAGGIORE: si prende la parte intera di ognuno e le
 *  cellule avanzate vanno a chi ha il resto più grosso, finché il totale
 *  torna quello voluto. Arrotondare ognuno per conto suo, invece, sballa la
 *  somma — e con un fattore piccolo la sballa sempre per eccesso, perché il
 *  minimo di una cellula si applicherebbe a tutti i quattordici tipi.
 */
function ricettaScalata(recipe) {
  const k = scalaCorpo();
  if (Math.abs(k - 1) < 1e-9) return recipe;
  let somma = 0;
  for (const [, n] of recipe) somma += n;
  /*  Sotto il MINIMO VITALE non si scende. Il preset «Minimale» sono sette
   *  cellule piu' il cervello, ed e' il minimo verificato per vivere da soli:
   *  un quinto di quello fa un corpo di due cellule senza stomaco, che non e'
   *  un esserino piccolo, e' un esserino rotto. La proporzione vale finche'
   *  c'e' qualcosa da ridurre; una ricetta gia' al minimo resta com'e'. */
  const voluto = Math.max(Math.min(somma, MINIMO_VITALE), Math.round(somma * k));
  const parti = recipe.map(([t, n]) => {
    const esatto = n * k;
    const intero = Math.floor(esatto);
    return { t, intero, resto: esatto - intero };
  });
  let dati = parti.reduce((a, p) => a + p.intero, 0);
  parti.sort((a, b) => b.resto - a.resto);
  for (let i = 0; dati < voluto && i < parti.length * 4; i++) { parti[i % parti.length].intero++; dati++; }
  // se invece si è dato troppo (può capitare solo per arrotondamento del
  // totale), si toglie a chi ha il resto più piccolo
  for (let i = parti.length - 1; dati > voluto && i >= 0; i--)
    if (parti[i].intero > 0) { parti[i].intero--; dati--; }
  const out = [];
  // si rispetta l'ordine originale: il montaggio lo usa come ordine di cantiere
  for (const [t] of recipe) {
    const p = parti.find(q => q.t === t && q.usata !== true);
    if (!p) continue;
    p.usata = true;
    if (p.intero > 0) out.push([t, p.intero]);
  }
  return out;
}

function ricettaBase(dna) {
  const arma = dna.aggression > .6 ? 'acid'
             : dna.aggression > .32 ? 'nettle' : 'electric';
  return [['gastric', 3], ['muscle', 6], ['olfact', 2], ['eye', 1],
          ['touch', 2], [arma, 2], ['nerve', 3], ['epithelial', 2]];
}

