/**
 *  LA FORMA D'ONDA DELL'ARCHETIPO, costruita armonica per armonica.
 *
 *  Le quattro forme di serie del browser sono quattro, e si sentono: due
 *  esserini che pescano «triangle» hanno la stessa identica materia sotto. Con
 *  una `PeriodicWave` lo spettro se lo disegna ognuno per conto suo — e le
 *  fasi si tirano a caso, che non cambia l'analisi in frequenza ma cambia la
 *  forma dell'onda nel tempo, e quindi come reagisce al distorsore.
 */
function ondaArchetipo(ctx, a, rng, quanto) {
  /*  `quanto` differenzia le tre onde della stessa gola: la prima e' quasi
   *  pura, la terza e' ruvida. Con tre onde quasi uguali il wobble che ne
   *  cambia il dosaggio non si sente — misurato, spostava il centroide di
   *  cinque punti su cento — perche' mescolare tre cose simili da' sempre la
   *  stessa cosa. Con tre materiali diversi lo stesso wobble diventa un
   *  timbro che si trasforma. */
  const alfa = a.alfa * (quanto || 1);
  const n = a.nArm + 1;
  const re = new Float32Array(n), im = new Float32Array(n);
  for (let k = 1; k < n; k++) {
    let amp = Math.pow(k, -alfa);
    if (k % 2 === 1) amp *= 1 + a.dispari; else amp *= 1 - a.dispari * .55;
    if (a.picco) amp *= 1 + a.picco[1] * Math.exp(-Math.pow((k - a.picco[0]) / 2.2, 2));
    if (amp < .0015) amp = 0;                    // sotto -56 dB non serve a nessuno
    amp *= .78 + rng() * .44;                    // ogni gola e' la sua
    const fase = rng() * Math.PI * 2;
    re[k] = amp * Math.cos(fase);
    im[k] = amp * Math.sin(fase);
  }
  return ctx.createPeriodicWave(re, im, { disableNormalization: false });
}

/**
 *  IL VAGARE: una passeggiata casuale lenta, in un buffer da quattro secondi
 *  che gira in tondo.
 *
 *  E' il pezzo che vale piu' di tutti gli altri messi insieme. Mandato sul
 *  `detune` di un oscillatore fa quello che fa una laringe: l'altezza non sta
 *  mai ferma, si sposta di qualche centesimo in continuazione, senza schema.
 *  Un LFO no — un LFO e' periodico, e la periodicita' e' esattamente quello
 *  che tradisce la macchina. Lo stesso buffer, letto piu' piano, serve anche
 *  per l'ampiezza.
 *
 *  Il giro va chiuso a mano: se la fine non combacia con l'inizio, ogni
 *  quattro secondi si sente uno scatto.
 */
let _bufVagare = null;
function bufferVagare(ctx) {
  if (_bufVagare && _bufVagare.sampleRate === ctx.sampleRate) return _bufVagare;
  const sr = ctx.sampleRate, n = sr * 4;
  const b = ctx.createBuffer(1, n, sr);
  const d = b.getChannelData(0);
  let v = 0, w = 0;
  for (let i = 0; i < n; i++) {
    v += .05 * ((Math.random() * 2 - 1) - v);
    w += .35 * (v - w);
    d[i] = w;
  }
  let mx = 1e-6;
  for (let i = 0; i < n; i++) if (Math.abs(d[i]) > mx) mx = Math.abs(d[i]);
  for (let i = 0; i < n; i++) d[i] /= mx;
  // e si chiude l'anello sfumando la coda sull'inizio
  const f = (sr * .25) | 0;
  for (let i = 0; i < f; i++) {
    const u = i / f;
    d[n - f + i] = d[n - f + i] * (1 - u) + d[i] * u;
  }
  return (_bufVagare = b);
}

function timbroDi(cr) {
  const firma = firmaDNA(cr.dna);
  if (cr._timbro && cr._timbroFirma === firma) return cr._timbro;
  cr._timbroFirma = firma;
  const rng = makeRng((cr.dna.seed * 2246822519 + 374761393) % 4294967296);
  const d = cr.dna;
  /*  LA TAGLIA NON ENTRA QUI. Il timbro dice com'e' fatta la voce, non quanto
   *  e' grosso il corpo: quella parte la aggiunge `fattoreTaglia` a ogni
   *  fotogramma, cosi' un esserino che cresce si abbassa mentre cresce invece
   *  di restare per sempre la gemma che era. Quel che resta qui e' l'altezza
   *  di riferimento per un corpo di taglia media. */

  /*  L'ALTEZZA DI BASE scende col corpo e sale col metabolismo: un animale
   *  grande ha una cassa grande e una voce bassa, e uno che brucia in fretta
   *  parla in fretta e acuto. Non e' una metafora, e' la stessa regola dei
   *  richiami veri. */
  /*  L'ARCHETIPO. Si tira a sorte, ma con il pollice sulla bilancia: chi e'
   *  aggressivo pesca piu' spesso ruggiti e felini, chi brucia in fretta
   *  insetti e uccelli, chi e' rigido e lento cetacei. Non e' deterministico —
   *  due predatori uguali possono essere uno un ruggito e l'altro un barrito —
   *  perche' un bestiario in cui la voce si deduce dalle statistiche e' un
   *  bestiario noioso. */
  /*  I PESI, e non sono uniformi apposta. Il bestiario deve suonare come una
   *  pozza d'acqua sporca, non come un documentario: le gole — ticchettii,
   *  ruggiti, sibili d'insetto, mostri d'abisso — pesano il doppio o il triplo
   *  delle voci pulite. La balena in particolare e' scesa a un terzo di quel
   *  che valeva: e' bellissima da sentire una volta ogni tanto, ma con dieci
   *  esserini in vasca ce n'erano sempre due o tre e il fondo diventava un
   *  disco di rilassamento. Adesso e' un incontro raro. */
  const inclina = [
    .8 + d.curiosity * .7,                          // human
    1.6 + d.growth * 1.6,                           // gurgle
    .35 + d.rigidity * .45,                         // whale: rara di proposito
    .9,                                             // mammal
    .9 + d.aggression * .7,                         // feline
    1.6 + d.aggression * 2.6,                       // roar
    .9 + d.aggression * .7 + d.growth * .6,         // trumpet
    1.4 + d.fear * 1.8,                             // croak
    2.0 + d.metabolism * 2.6,                       // insect
    .7 + d.metabolism * .9 + d.fear * .5,           // bird
    2.2 + d.aggression * 2.0 + d.curiosity * .5,    // predator
    2.0 + d.aggression * 2.2 + (1 - d.metabolism),  // saurian
    2.4 + d.aggression * 1.4 + d.growth * 1.0,      // guttural
  ];
  let somma = 0; for (const x of inclina) somma += x;
  let tiro = rng() * somma, iArch = 0;
  for (let i = 0; i < inclina.length; i++) { tiro -= inclina[i]; if (tiro <= 0) { iArch = i; break; } }
  const A = VOCI_ARCHETIPI[iArch];
  const fra = (r) => r[0] + rng() * (r[1] - r[0]);

  const base = (34 + 116 * TAGLIA_RIF * (.55 + d.metabolism * .8)) * fra(A.base);

  /*  I RAPPORTI FRA LE TRE FREQUENZE. Con simmetria alta si prendono rapporti
   *  semplici — quinte, ottave — e la voce suona intonata; con simmetria bassa
   *  si scelgono rapporti storti, che battono fra loro e danno quel ringhio
   *  irregolare da bestia. */
  const ordine = clamp((d.symmetry - 1) / 3, 0, 1);
  const semplici = [1, 1.5, 2.0, 2.5, 3.0];
  const storti   = [1, 1.37, 1.94, 2.41, 2.78];
  const scegli = (i) => semplici[i] * ordine + storti[i] * (1 - ordine);
  const r2 = scegli(1 + ((rng() * 2) | 0));
  const r3 = scegli(2 + ((rng() * 3) | 0));

  /*  LA FRASE, ed e' lunga ESATTAMENTE 32 passi. Si tirano durate da un
   *  insieme musicale — sedicesimi, ottavi, quarti, mezze — finche' non si
   *  arriva a trentadue, e l'ultima si accorcia per far quadrare il conto.
   *  Nessuna frase puo' sforare: e' questo a tenere insieme il coro.
   *
   *  Poi la si stende su una griglia di 32 caselle, cosi' a ogni passo si sa
   *  in un accesso se li' comincia qualcosa e cosa. */
  /*  DUE POZZI DI DURATE, non uno. Prima note e pause pescavano dallo stesso
   *  insieme, e uscivano note da quattro e sei passi: un verso animale tirato
   *  per due secondi non e' un verso, e' una sirena. Adesso le NOTE sono corte
   *  — quasi sempre uno o due sedicesimi — e sono le PAUSE a potersi allungare.
   *  E' cosi' che sono fatti i richiami veri: emissioni brevi separate da
   *  silenzi lunghi, e il silenzio e' quel che fa aspettare la prossima. */
  const durateNota  = [1, 1, 1, 1, 1, 2, 2, 2, 3, 4];
  const duratePausa = [1, 1, 2, 2, 3, 3, 4, 4, 6, 6];
  const frase = [];
  const quantoTace = .26 + (1 - clamp(d.aggression, 0, 1)) * .34;
  let resto = PASSI_FRASE;
  while (resto > 0) {
    const pausa = frase.length > 0 && rng() < quantoTace;
    const pozzo = pausa ? duratePausa : durateNota;
    let lung = pozzo[(rng() * pozzo.length) | 0];
    if (lung > resto) lung = resto;
    frase.push({
      pausa,
      lung,
      grado: (rng() * 3) | 0,                       // quale dei tre toni
      // ogni tanto un salto d'ottava: e' quel che rende una frase un canto
      ott: rng() < .16 ? 2 : (rng() < .13 ? .5 : 1),
      /*  E anche dentro il suo passo la nota non dura tutto: staccata, non
       *  tenuta. Con .45–.95 anche una nota da un sedicesimo suonava piena
       *  fino al passo dopo e le emissioni si saldavano una all'altra. */
      tenuta: .26 + rng() * .34,
    });
    resto -= lung;
  }
  /*  `griglia[i]` e' l'evento che COMINCIA al passo i, oppure null. Con la
   *  griglia il sequencer non deve inseguire nessun accumulatore: legge l'ora,
   *  divide, e sa cosa deve suonare. */
  const griglia = new Array(PASSI_FRASE).fill(null);
  let cursore = 0;
  for (const ev of frase) { griglia[cursore] = ev; cursore += ev.lung; }

  /*  Meta', uguale o doppia velocita'. Un metabolismo lento canta in note
   *  lunghe, uno veloce sminuzza — e siccome sono potenze di due della
   *  griglia, restano tutti allineati fra loro. */
  const divisione = d.metabolism < .34 ? 2 : d.metabolism > .72 ? .5 : 1;

  const forme = ['sine', 'triangle', 'sawtooth', 'square'];
  return (cr._timbro = {
    base,
    rapporti: [1, r2 * (1 + (rng() - .5) * .03), r3 * (1 + (rng() - .5) * .03)],
    arch: A.nome,
    /*  Tre onde COSTRUITE, una per oscillatore, tutte e tre dallo stesso
     *  archetipo ma nessuna uguale all'altra: e' la stessa gola vista da tre
     *  angoli, non tre strumenti diversi. Restano anche le forme di serie,
     *  che servono al lamento e all'urlo finale. */
    onde: null, _semeOnda: (rng() * 4294967296) | 0,
    forme: [
      forme[(rng() * 2) | 0],
      forme[(rng() * 2) | 0],
      forme[(rng() * 3) | 0],
    ],
    /*  L'IMPERFEZIONE, ed e' la voce vera dell'insieme. `jit` e' di quanti
     *  centesimi vaga l'altezza, `shim` di quanto respira l'ampiezza. Un
     *  ruggito ne ha tre volte tanto di una nota di balena, e non e' un
     *  dettaglio: e' la differenza fra una bestia sotto sforzo e una calma. */
    jit: A.jit * (.7 + rng() * .7),
    shim: A.shim * (.7 + rng() * .7),
    soffio: A.soffio * (.6 + rng() * .9),
    sub: A.sub * (.5 + rng()),
    scoop: fra(A.scoop),
    bocca: A.bocca * (.7 + rng() * .6),
    /*  Il ticchettio, se la famiglia ce l'ha: quanto veloce e quanto profondo.
     *  E' la cosa piu' riconoscibile fra tutte quelle che questa voce sa fare
     *  — a orecchie chiuse un esserino che ticchetta lo si distingue dagli
     *  altri nove prima ancora di aver capito che nota sta facendo. */
    clic: A.clic ? [fra(A.clic[0]), A.clic[1] * (.7 + rng() * .6)] : null,
    wobEx: A.wobEx || 1,
    pesi: [.55 + rng() * .3, .3 + rng() * .3, .18 + rng() * .25],
    // ondeggio lento e ciclico di ciascuna: e' questo a rendere il verso vivo
    vibRate: [fra(A.vib) * .8, fra(A.vib), fra(A.vib) * 1.25],
    vibProf: [fra(A.vibP) * .7, fra(A.vibP), fra(A.vibP) * 1.3],  // in centesimi
    /*  GORGOGLIO: tremolo, e adesso su DUE SCALE DI TEMPO. Quello veloce e'
     *  il borbottio; sotto c'e' un respiro lentissimo, mezzo hertz scarso, che
     *  gonfia e sgonfia il verso come il fiato di una balena o un battito. E'
     *  quello lento a dare l'impressione di una bestia grossa e viva; da solo,
     *  il tremolo veloce suonava elettronico. */
    gorgRate: fra(A.gorg) * (.85 + d.growth * .4),
    gorgProf: A.gorgP * (.7 + rng() * .6),
    respRate: fra(A.resp),
    respProf: .22 + rng() * .3,
    /*  FORMANTI, e stanno molto piu' in basso di prima. Le due risonanze
     *  danno la vocale; portandole sotto il chilohertz la vocale diventa una
     *  «o» o una «u» di gola invece di una «e» nasale, ed e' li' che vivono i
     *  richiami dei cetacei. */
    /*  I FORMANTI, e vengono dall'archetipo. E' qui che si decide se il verso
     *  ha una bocca umana o una gola di rana: due picchi bassi e vicini fanno
     *  una «u» di petto, uno basso e uno alto una vocale aperta, due alti un
     *  fischio. La tinta li sposta un po' dentro la famiglia, ma non li porta
     *  in un'altra famiglia. */
    formanti: [
      fra(A.f[0]) * (.9 + d.hue * .2),
      fra(A.f[1]) * (1.1 - d.hue * .2),
    ],
    /*  Q BASSI. Un passa-banda stretto e' una vocale precisa, quasi nasale;
     *  allargandolo la risonanza diventa un'ombra sul suono invece che una
     *  bocca che pronuncia, ed e' molto piu' morbido. */
    formQ: [A.q[0] * (.75 + rng() * .5), A.q[1] * (.75 + rng() * .5)],
    // quanto e' sporco: l'aggressivita' distorce, la rigidita' impiega
    dist: clamp(A.dist * (.7 + rng() * .6) + d.aggression * .12, 0, .7),
    piega: clamp(d.rigidity * .28 - .06 + rng() * .12, 0, .26),
    // ANELLO: modulazione ad anello, il carattere piu' alieno di tutti
    anelloHz: 11 + rng() * 74 * (1 - ordine),
    anelloMix: A.anello * (.5 + rng()) * (1 - ordine * .5),
    /*  IL PASSA-BASSO, e adesso taglia sul serio. A tremila hertz passava
     *  ancora tutta la grana del distorsore e il verso restava un ronzio
     *  elettrico; sotto i cinquecento resta solo il corpo del suono. */
    cupo: fra(A.cupo),
    /*  E un SECONDO passa-basso in cascata, poco piu' su del primo. Due poli
     *  invece di uno: la pendenza raddoppia e quel che sta sopra il taglio
     *  sparisce davvero, invece di affacciarsi attenuato. E' questa la
     *  differenza fra un suono filtrato e un suono smorzato. */
    velo: fra(A.velo),
    /*  MANDATE GENEROSE. Un verso cosi' filtrato, secco, sarebbe un brontolio
     *  in una scatola; e' la coda lunga a dargli lo spazio intorno e a farlo
     *  somigliare a un richiamo che attraversa l'acqua. Chi e' rigido riverbera
     *  come una conchiglia, chi e' curioso rimbalza in eco per la vasca — ma
     *  adesso partono tutti da un fondo alto. */
    riv: .22 + d.rigidity * .26 + rng() * .12,
    eco: .20 + d.curiosity * .30 + rng() * .12,
    /*  LA FRASE: la voce non e' un filo continuo, e' un CANTO. Note e pause
     *  in una sequenza che si ripete sempre uguale — e' la frase a rendere un
     *  esserino riconoscibile a orecchie chiuse, molto piu' del timbro: due
     *  bestie con la stessa gola ma due ritmi diversi si distinguono subito,
     *  due con lo stesso ritmo e gole diverse molto meno.
     *
     *  Le pause sono lunghe quanto le note e a volte di piu': un richiamo
     *  animale e' fatto per metа' di silenzio, ed e' il silenzio a far
     *  aspettare la nota dopo. Chi e' calmo tace di piu', chi e' aggressivo
     *  riempie.
     *
     *  Il passo — la durata dell'unita' ritmica — scende col metabolismo: un
     *  animale lento canta lento. */
    frase, griglia, divisione,
    pan: 0,
  });
}

/* --- UNA VOCE ------------------------------------------------------------
 *  Tre oscillatori, ognuno col suo ondeggio lento; la somma passa da un
 *  modulatore ad anello, poi dal distorsore, poi dai due formanti in
 *  parallelo, poi dal tremolo del gorgoglio, e infine dal pannello spaziale.
 * ---------------------------------------------------------------------- */
class Voce {
  constructor(cr) {
    const A = audio, ctx = A.ctx, t = timbroDi(cr);
    this.cr = cr; this.t = t;
    this.morta = false;
    /*  Non c'e' nessun punto di partenza da scegliere: la voce si aggancia
     *  alla griglia dove la griglia sta adesso. Chi nasce a meta' battuta
     *  entra a meta' battuta, come chi si unisce a un canto gia' cominciato.
     *  `prossimo` e' il primo passo ancora da programmare. */
    this.prossimo = Math.ceil(ctx.currentTime / (PASSO_DUR * t.divisione));
    this.nota = null;

    this.osc = []; this.oscG = []; this.vib = []; this.vibG = [];
    /*  Il guadagno di somma e' generoso perche' a valle si perde parecchio: i
     *  due formanti sono passa-banda stretti, e un passa-banda con Q otto
     *  lascia passare una fetta sottile dello spettro. Misurato, con .28 qui la
     *  voce usciva a -61 dBFS al master, cioe' inudibile. */
    const somma = ctx.createGain();
    somma.gain.value = .62;

    /*  Le tre onde si costruiscono una volta sola per timbro e si tengono:
     *  `createPeriodicWave` non e' gratis e la voce si rifa' a ogni cambio di
     *  DNA, non a ogni fotogramma. */
    /*  Le onde appartengono a UN contesto audio: spegnendo e riaccendendo il
     *  suono il contesto e' nuovo e quelle vecchie non ci si possono usare. */
    if (!t.onde || t._ondeCtx !== ctx) {
      t._ondeCtx = ctx;
      const rw = makeRng(t._semeOnda >>> 0);
      const arc = VOCI_ARCHETIPI.find(a => a.nome === t.arch) || VOCI_ARCHETIPI[0];
      t.onde = [ondaArchetipo(ctx, arc, rw, 1.55),   // tonda
                ondaArchetipo(ctx, arc, rw, 1.0),    // il carattere della famiglia
                ondaArchetipo(ctx, arc, rw, .58)];   // ruvida
    }
    const vagBuf = bufferVagare(ctx);
    this.vagare = [];

    for (let i = 0; i < 3; i++) {
      const o = ctx.createOscillator();
      o.setPeriodicWave(t.onde[i]);
      o.frequency.value = t.base * t.rapporti[i];
      const g = ctx.createGain();
      g.gain.value = t.pesi[i];
      // ondeggio: un LFO sul detune, lento e ciclico — questo e' il VIBRATO,
      // volontario e periodico, come quello di chi canta
      const lfo = ctx.createOscillator();
      lfo.type = 'sine';
      lfo.frequency.value = t.vibRate[i];
      const lg = ctx.createGain();
      lg.gain.value = t.vibProf[i];
      lfo.connect(lg).connect(o.detune);
      lfo.start();
      /*  E questo e' il JITTER, che e' un'altra cosa: non e' voluto e non ha
       *  periodo. Tre letture dello stesso vagare a velocita' diverse, cosi'
       *  i tre oscillatori sbandano ognuno per conto suo e non all'unisono —
       *  se sbandassero insieme sarebbe di nuovo un vibrato, solo storto. */
      const vg = ctx.createBufferSource();
      vg.buffer = vagBuf; vg.loop = true;
      vg.playbackRate.value = .55 + i * .37 + Math.random() * .3;
      const vgG = ctx.createGain(); vgG.gain.value = t.jit * (1 + i * .22);
      vg.connect(vgG).connect(o.detune);
      vg.start(ctx.currentTime + Math.random() * 3.5);   // partenze sfasate
      this.vagare.push(vg);
      /*  IL WOBBLE. Ogni onda ha un suo respiro sull'AMPIEZZA, lento e a una
       *  velocita' che non ha rapporto con quella delle altre due. E' un
       *  effetto periodico — ognuno preso da solo e' un ciclo regolare — ma
       *  tre cicli incommensurabili non tornano mai insieme, e quindi la
       *  MISCELA delle tre onde non e' mai la stessa due volte: il timbro si
       *  muove per conto suo mentre la nota tiene.
       *
       *  E' l'altra meta' del problema «suona elettronico». Il vagare risolve
       *  l'altezza che sta troppo ferma; questo risolve lo SPETTRO che sta
       *  troppo fermo — e in una gola vera lo spettro si muove molto piu' di
       *  quanto si muova l'intonazione. */
      const wob = ctx.createOscillator();
      wob.type = i === 2 ? 'triangle' : 'sine';
      const wHz = (.11 + Math.random() * .95) * (1 + i * .77);
      wob.frequency.value = wHz;
      /*  E IL WOBBLE STESSO NON VA A VELOCITA' FISSA: sotto c'e' un secondo
       *  modulatore lentissimo che gli sposta il periodo di meta'. Un LFO a
       *  ritmo costante, per quanto lento, alla lunga si conta — e appena si
       *  conta si sente la macchina. Cosi' invece accelera e rallenta da solo,
       *  e non c'e' un tempo da riconoscere. */
      const wm = ctx.createOscillator();
      wm.type = 'sine'; wm.frequency.value = .017 + Math.random() * .075;
      const wmg = ctx.createGain(); wmg.gain.value = wHz * (.35 + Math.random() * .4);
      wm.connect(wmg).connect(wob.frequency);
      wm.start(ctx.currentTime + Math.random() * 2);
      this.vib.push(wm); this.vibG.push(wmg);

      const wg = ctx.createGain();
      wg.gain.value = t.pesi[i] * (.55 + Math.random() * .45) * t.wobEx;
      wob.connect(wg).connect(g.gain);
      // sfasati fra loro, ma gia' in moto: partendo fino a sei secondi dopo,
      // per i primi versi il wobble semplicemente non c'era
      wob.start(ctx.currentTime + Math.random() * 1.2);
      this.vib.push(wob); this.vibG.push(wg);

      o.connect(g).connect(somma);
      o.start();
      this.osc.push(o); this.oscG.push(g); this.vib.push(lfo); this.vibG.push(lg);
    }

    /*  IL SOTTOTONO: un'ottava sotto la fondamentale, stonato di poco. E' il
     *  raddoppio di periodo che fa una laringe spinta oltre il suo regime — i
     *  ruggiti ne sono pieni, una balena quasi per niente — e da' quella
     *  ruvidezza che nessun filtro sa imitare. */
    if (t.sub > .01) {
      const sb = ctx.createOscillator();
      sb.setPeriodicWave(t.onde[0]);
      sb.frequency.value = t.base * .5;
      sb.detune.value = -14 - Math.random() * 20;
      const sg = ctx.createGain(); sg.gain.value = t.sub;
      sb.connect(sg).connect(somma);
      sb.start();
      this.sub = sb; this.subG = sg;
    }

    /*  IL FIATO: aria che passa. Entra prima dei formanti, cosi' se lo prende
     *  la stessa bocca del resto della voce invece di sembrarci appoggiato
     *  sopra. Senza, il verso e' pulitissimo e proprio per questo finto. */
    if (t.soffio > .01) {
      const nb = ctx.createBufferSource();
      nb.buffer = rumoreAudio(ctx); nb.loop = true;
      nb.playbackRate.value = .7 + Math.random() * .6;
      const nf = ctx.createBiquadFilter();
      nf.type = 'bandpass'; nf.frequency.value = t.formanti[1] * .85; nf.Q.value = .8;
      const ng = ctx.createGain(); ng.gain.value = t.soffio * .55;
      nb.connect(nf).connect(ng).connect(somma);
      nb.start();
      this.soffio = nb; this.soffioF = nf;
    }

    /*  LO SHIMMER: la stessa passeggiata, letta lentissima, sul volume. Le
     *  ampiezze di una voce vera non stanno ferme piu' di quanto ci stiano le
     *  altezze. */
    const vs = ctx.createBufferSource();
    vs.buffer = vagBuf; vs.loop = true;
    vs.playbackRate.value = .21 + Math.random() * .2;
    const vsG = ctx.createGain(); vsG.gain.value = t.shim * .62;
    vs.connect(vsG).connect(somma.gain);
    vs.start(ctx.currentTime + Math.random() * 3.5);
    this.vagare.push(vs);

    /*  MODULAZIONE AD ANELLO. Il segnale si moltiplica per una sinusoide:
     *  nascono somme e differenze di frequenze che non stanno in nessuna scala,
     *  ed e' il suono piu' «non terrestre» che si possa fare con due nodi.
     *  Passa solo una parte del segnale, o diventa un campanaccio. */
    const anello = ctx.createGain(); anello.gain.value = 0;
    const anelloOsc = ctx.createOscillator();
    anelloOsc.type = 'sine'; anelloOsc.frequency.value = t.anelloHz;
    anelloOsc.connect(anello.gain); anelloOsc.start();
    this.anelloOsc = anelloOsc;
    const anelloMix = ctx.createGain(); anelloMix.gain.value = t.anelloMix;
    const direttoMix = ctx.createGain(); direttoMix.gain.value = 1 - t.anelloMix * .6;
    somma.connect(anello); anello.connect(anelloMix);
    somma.connect(direttoMix);

    const preDist = ctx.createGain(); preDist.gain.value = 1;
    anelloMix.connect(preDist); direttoMix.connect(preDist);

    const dist = ctx.createWaveShaper();
    dist.curve = curvaDistorsione(t.dist, t.piega);
    /*  Niente sovracampionamento QUI. Sulle voci gira di continuo, e a otto
     *  voci il costo si vede nel fotogramma; l'aliasing che evita si sente
     *  soltanto sui transienti duri, che una voce continua non ha. I colpi,
     *  che di transienti vivono, se lo tengono. */
    dist.oversample = 'none';
    preDist.connect(dist);

    /*  FORMANTI: due passa-banda stretti in parallelo. Sono le risonanze del
     *  tratto vocale, ed e' la loro posizione a far sentire una vocale invece
     *  di un ronzio. Accanto c'e' anche il segnale intero passato al
     *  passa-basso, o la voce sarebbe tutta gola e niente corpo. */
    const f1 = ctx.createBiquadFilter();
    f1.type = 'bandpass'; f1.frequency.value = t.formanti[0]; f1.Q.value = t.formQ[0];
    const f2 = ctx.createBiquadFilter();
    f2.type = 'bandpass'; f2.frequency.value = t.formanti[1]; f2.Q.value = t.formQ[1];
    const g1 = ctx.createGain(); g1.gain.value = 2.2;
    const g2 = ctx.createGain(); g2.gain.value = 1.4;
    const corpo = ctx.createBiquadFilter();
    corpo.type = 'lowpass'; corpo.frequency.value = t.cupo; corpo.Q.value = .8;
    const gc = ctx.createGain(); gc.gain.value = 1.15;
    dist.connect(f1).connect(g1);
    dist.connect(f2).connect(g2);
    dist.connect(corpo).connect(gc);
    this.f1 = f1; this.f2 = f2; this.corpo = corpo;

    const misto = ctx.createGain(); misto.gain.value = 1;
    g1.connect(misto); g2.connect(misto); gc.connect(misto);

    /*  IL VELO: un secondo passa-basso, ma su TUTTO il miscuglio, formanti
     *  compresi. Il primo taglia solo il ramo del corpo, e i due passa-banda
     *  gli passavano accanto portandosi dietro la loro grana: bastava quella a
     *  tenere il verso in superficie. Con un velo unico sopra ogni cosa il
     *  suono arriva smorzato per intero, come sentito attraverso l'acqua —
     *  che e' esattamente dove queste bestie vivono. */
    const velo = ctx.createBiquadFilter();
    velo.type = 'lowpass'; velo.frequency.value = t.velo; velo.Q.value = .55;
    this.velo = velo;

    /*  E IL WOBBLE ANCHE SULLA BOCCA. Tre LFO lentissimi, uno per formante e
     *  uno sul velo, ognuno col suo periodo: le risonanze non stanno mai dove
     *  stavano un secondo fa. Sommato al movimento che i formanti hanno gia'
     *  a ogni nota, il risultato e' che la vocale non si ferma mai — che e'
     *  quello che fa una bocca aperta mentre esce un verso.
     *
     *  Si sommano al valore automatizzato dell'AudioParam invece di
     *  sostituirlo: le rampe per nota continuano a funzionare sotto. */
    for (const [par, prof, giro] of [[f1.frequency, t.formanti[0] * .38, .09],
                                     [f2.frequency, t.formanti[1] * .44, .13],
                                     [velo.frequency, t.velo * .52, .06]]) {
      const w = ctx.createOscillator();
      w.type = Math.random() < .5 ? 'sine' : 'triangle';
      const gHz = giro + Math.random() * .45;
      w.frequency.value = gHz;
      // anche la bocca cambia ritmo mentre si muove
      const wm = ctx.createOscillator();
      wm.type = 'sine'; wm.frequency.value = .011 + Math.random() * .05;
      const wmg = ctx.createGain(); wmg.gain.value = gHz * (.4 + Math.random() * .45);
      wm.connect(wmg).connect(w.frequency);
      wm.start(ctx.currentTime + Math.random() * 2);
      this.vib.push(wm); this.vibG.push(wmg);
      const wg = ctx.createGain(); wg.gain.value = prof * (.6 + Math.random() * .8) * t.wobEx;
      w.connect(wg).connect(par);
      w.start(ctx.currentTime + Math.random() * 1.5);
      this.vib.push(w); this.vibG.push(wg);
    }

    /*  GORGOGLIO: due tremoli in rapporto irrazionale. Uno solo darebbe una
     *  pulsazione regolare, da sirena; due che non tornano mai in fase danno
     *  quel borbottio che non si riesce a contare. */
    const trem = ctx.createGain(); trem.gain.value = 1 - t.gorgProf * .5 - t.respProf * .5;
    const l1 = ctx.createOscillator(); l1.type = 'sine'; l1.frequency.value = t.gorgRate;
    const l2 = ctx.createOscillator(); l2.type = 'triangle'; l2.frequency.value = t.gorgRate * 1.618;
    /*  Il terzo e' il RESPIRO: mezzo hertz scarso, che gonfia e sgonfia tutto
     *  il verso. E' lui a far sembrare la bestia grossa — un tremolo veloce da
     *  solo suona elettronico, un tremolo lento suona vivo. */
    const l3 = ctx.createOscillator(); l3.type = 'sine'; l3.frequency.value = t.respRate;
    const lg1 = ctx.createGain(); lg1.gain.value = t.gorgProf * .40;
    const lg2 = ctx.createGain(); lg2.gain.value = t.gorgProf * .24;
    const lg3 = ctx.createGain(); lg3.gain.value = t.respProf;
    l1.connect(lg1).connect(trem.gain); l2.connect(lg2).connect(trem.gain);
    l3.connect(lg3).connect(trem.gain);
    l1.start(); l2.start(); l3.start();
    this.gorg = [l1, l2, l3];

    /*  IL TICCHETTIO GUTTURALE, per chi ce l'ha.
     *
     *  Un'onda quadra a venti-quaranta hertz sul guadagno del tremolo: il
     *  suono si apre e si chiude decine di volte al secondo. Sotto i quindici
     *  hertz si contano ancora i battiti e si sente un tremolo; sopra, non si
     *  contano piu' e diventa una raganella — che e' il verso che fa una gola
     *  con qualcosa in mezzo.
     *
     *  Due accortezze, e servono tutte e due. La prima: il ticchettio RESPIRA,
     *  perche' un ticchettio costante e' un ronzio e non un verso — un lento
     *  gli apre e chiude la profondita', cosi' va e viene a ondate. La seconda:
     *  la velocita' stessa non e' ferma, altrimenti si riconosce il periodo. */
    if (t.clic) {
      const cl = ctx.createOscillator(); cl.type = 'square';
      cl.frequency.value = t.clic[0];
      const clv = ctx.createOscillator(); clv.type = 'sine';
      clv.frequency.value = .07 + Math.random() * .22;
      const clvg = ctx.createGain(); clvg.gain.value = t.clic[0] * .3;
      clv.connect(clvg).connect(cl.frequency);

      const clg = ctx.createGain(); clg.gain.value = t.clic[1] * .42;
      const onda = ctx.createOscillator(); onda.type = 'sine';
      onda.frequency.value = .05 + Math.random() * .19;
      const og = ctx.createGain(); og.gain.value = t.clic[1] * .38;
      onda.connect(og).connect(clg.gain);

      cl.connect(clg).connect(trem.gain);
      cl.start(); clv.start(); onda.start();
      this.gorg.push(cl, clv, onda);
    }
    misto.connect(velo).connect(trem);

    // inviluppo generale della voce, guidato dallo stato mentale
    const vol = ctx.createGain(); vol.gain.value = 0;
    trem.connect(vol);
    this.vol = vol;

    /*  SPAZIALIZZAZIONE. `HRTF` e non `equalpower`: costa di piu' ma e' quello
     *  che mette davvero un suono dietro la testa invece che solo a sinistra o
     *  a destra, ed e' meta' del lavoro se il punto e' capire DOVE sta la
     *  bestia che sta gorgogliando. */
    const pan = ctx.createPanner();
    /*  `equalpower` e non `HRTF` per le voci. L'HRTF costa parecchio e serve a
     *  distinguere davanti da dietro e sopra da sotto; qui la telecamera guarda
     *  la vasca da fuori, quindi quella distinzione non la usa nessuno, mentre
     *  destra-sinistra e la distanza — che equalpower fa lo stesso — sono
     *  tutto. Misurato con otto voci: 22 fotogrammi al secondo contro 30 senza
     *  audio, e la panoramica HRTF era la voce piu' grossa del conto. I colpi
     *  restano in HRTF: sono pochi, brevi, e li' la posizione esatta vale la
     *  spesa.
     *
     *  Distanza di riferimento e caduta tarate sulla SCALA DI QUESTA SCENA: la
     *  telecamera guarda una vasca da cinque o sei unita' stando fuori a dieci
     *  o quindici. Coi valori di libreria — un metro e caduta piena — a quella
     *  distanza restava un decimo del segnale e non si sentiva piu' niente. */
    pan.panningModel = 'equalpower';
    pan.distanceModel = 'inverse';
    pan.refDistance = 3.5;
    pan.rolloffFactor = .75;
    pan.maxDistance = 45;
    vol.connect(pan);
    this.pan = pan;

    const secco = ctx.createGain(); secco.gain.value = .85;
    const riv = ctx.createGain(); riv.gain.value = t.riv;
    const eco = ctx.createGain(); eco.gain.value = t.eco;
    pan.connect(secco).connect(A.secco);
    pan.connect(riv).connect(A.mandRiv);
    pan.connect(eco).connect(A.mandEco);
    this.nodi = [somma, anello, anelloMix, direttoMix, preDist, dist, f1, f2, g1, g2,
                 corpo, gc, misto, velo, trem, lg1, lg2, lg3, vol, pan, secco, riv, eco];
  }

  /** posizione, volume e agitazione: tutto quel che cambia da un fotogramma all'altro */
  aggiorna(dt, ora) {
    const cr = this.cr, t = this.t, ctx = audio.ctx;
    const p = cr.centroid;
    if (this.pan.positionX) {
      this.pan.positionX.setTargetAtTime(p.x, ora, .05);
      this.pan.positionY.setTargetAtTime(p.y, ora, .05);
      this.pan.positionZ.setTargetAtTime(p.z, ora, .05);
    } else this.pan.setPosition(p.x, p.y, p.z);

    const agitato = cr.state === 'attack' || cr.state === 'hunt' ? 1
                  : cr.state === 'flee' || cr.state === 'hurt' ? .8
                  : cr.state === 'feed' ? .45 : .2;

    /*  LA FRASE SCORRE — ma non sul suo cronometro: sulla griglia comune.
     *  Si guarda l'ora, si divide per la durata di un passo, e si sa dove
     *  siamo. Nessuna deriva possibile, e nessun bisogno di accordarsi con
     *  nessuno: chi legge lo stesso orologio e' sincronizzato e basta.
     *
     *  Si programma un filo IN ANTICIPO — cinquanta millesimi — perche' un
     *  attacco fatto partire dal fotogramma cadrebbe dove capita entro i
     *  sedici millesimi del fotogramma stesso, e sedici millesimi di
     *  sbandamento fra dieci voci si sentono tutti. Cosi' invece l'inviluppo
     *  e' agganciato all'istante esatto del passo, al campione.
     *
     *  Nelle pause la voce tace davvero: quel che si sente e' la coda del
     *  riverbero, che e' esattamente cio' che deve restare. */
    const passoDur = PASSO_DUR * t.divisione;
    const orizzonte = ora + AUDIO_ANTICIPO;
    let giri = 0;
    while (this.prossimo * passoDur < orizzonte && giri++ < 64) {
      const quando = this.prossimo * passoDur;
      const ev = t.griglia[((this.prossimo % PASSI_FRASE) + PASSI_FRASE) % PASSI_FRASE];
      this.prossimo++;
      if (!ev) continue;                       // passo interno a una nota lunga
      this.nota = ev.pausa ? null : ev;
      const g = this.vol.gain;
      const t0 = Math.max(ora, quando);
      g.cancelScheduledValues(t0);
      if (ev.pausa || !cr.alive) {
        g.setTargetAtTime(0, t0, .14);
      } else {
        const forte = (.55 + agitato * .95) * volPerc(audio.vol.voci) * VOCE_GUADAGNO;
        const durata = ev.lung * passoDur;
        const tenuta = durata * ev.tenuta;
        /*  Attacco lungo e rilascio lungo. Un attacco corto e' un colpo di
         *  plettro: qui non deve MAI sentirsi l'istante in cui la nota
         *  comincia, deve sentirsi che era gia' li' e si e' avvicinata. */
        g.setValueAtTime(Math.max(1e-4, g.value), t0);
        // attacco svelto, o su una nota corta non farebbe in tempo a parlare
        g.linearRampToValueAtTime(forte, t0 + Math.min(.11, durata * .38));
        g.setTargetAtTime(0, t0 + tenuta, Math.max(.07, tenuta * .38));

        /*  L'ATTACCO SCIVOLA. Nessuna gola parte sull'intonazione giusta: la
         *  prende in un decimo di secondo, salendoci o cascandoci sopra a
         *  seconda della bestia — il miagolio sale, il ruggito casca. Si
         *  automatizza il `detune` intrinseco, mentre il vagare continua a
         *  sommarcisi sopra: le due cose non si pestano i piedi. */
        const sc = t.scoop * (.7 + Math.random() * .6);
        const quanto = Math.min(.14, durata * .35);
        for (const o of this.osc) {
          o.detune.cancelScheduledValues(t0);
          o.detune.setValueAtTime(sc, t0);
          o.detune.linearRampToValueAtTime(0, t0 + quanto);
        }
        // e la bocca prende una forma nuova per questa nota
        const ap = (Math.random() - .5) * 2 * t.bocca;
        this.bocca1 = 1 + ap * .55;
        this.bocca2 = 1 - ap * .75;
        this.veloMul = 1.35 + Math.random() * .5;
      }
    }
    const nota = this.nota;

    // un corpo stordito o avvelenato stona: il tono scende e si sporca
    const male = clamp(cr.stunned * .5 + cr.corrosione + cr.raggomitolo * .5, 0, 1.4);
    /*  E LA VOCE SEGUE LA TAGLIA, contata sulle cellule vive a ogni
     *  fotogramma: poche cellule, tono alto; molte, tono basso. Il paragone e'
     *  con un corpo di taglia media, non con quello che l'esserino era alla
     *  nascita — cosi' vale per la taglia in se', e per giunta segue la
     *  crescita mentre avviene. */
    /*  E CON UN ESPONENTE. Il rapporto grezzo fra le taglie e' compresso: un
     *  corpo da dodici cellule ne usciva appena tre volte piu' acuto di uno da
     *  centosessanta, e all'orecchio erano quasi la stessa bestia. Elevandolo
     *  a 1.35 le distanze si aprono — i piccoli salgono davvero — mentre il
     *  fondo resta a .36: la fondamentale di un colosso finisce sotto i
     *  quaranta hertz, dove un altoparlante da portatile non restituisce piu'
     *  niente, ma i formanti stanno molto piu' su e l'orecchio ricostruisce
     *  l'altezza dalla serie armonica — e' il colosso a restare distinguibile
     *  da un corpo da trecento cellule, che con un pavimento piu' alto non lo
     *  era piu'. */
    const taglia = clamp(Math.pow(fattoreTaglia(cr) / TAGLIA_RIF, 1.35), .36, 6.5);

    /*  E SALE CON LA CORSA E COL DOLORE. `vel` e' lo spostamento del baricentro
     *  per passo di fisica, quindi va moltiplicato per la frequenza dei passi
     *  per avere unita' al secondo. `pain` sale a ogni colpo incassato e cala
     *  da solo: e' la misura di quanto l'esserino sta subendo adesso.
     *
     *  E' la stessa cosa che fa una voce vera sotto sforzo o sotto minaccia —
     *  la laringe si tende e il tono sale — e serve a rendere leggibile
     *  all'orecchio la differenza fra una bestia che passeggia e una che sta
     *  scappando o venendo aggredita. */
    const corsa = clamp(cr.vel.length() * 60, 0, 3.2);
    const subisce = clamp(cr.pain, 0, 2);
    const su = 1 + corsa * .17 + subisce * .26 + agitato * .08;

    const fBase = clamp(t.base * taglia * su, 18, 900);
    const salto = nota ? nota.ott : 1;
    const grado = nota ? nota.grado : 0;
    for (let i = 0; i < 3; i++) {
      /*  Il grado della nota RUOTA i tre rapporti invece di sostituirli: i tre
       *  oscillatori restano nella stessa relazione fra loro — che e' il timbro
       *  — e insieme si spostano sul grado della frase. */
      const r = t.rapporti[(i + grado) % 3] / t.rapporti[grado];
      this.osc[i].frequency.setTargetAtTime(
        fBase * r * salto * (1 - male * .28), ora, .08);
    }
    /*  Anche il colore segue: un corpo piccolo non e' solo piu' acuto, e' piu'
     *  CHIARO. Muovere la sola altezza e lasciare filtro e formanti dov'erano
     *  darebbe un gigante che parla in falsetto invece di una bestia piccola. */
    const chiaro = Math.sqrt(taglia);
    this.corpo.frequency.setTargetAtTime(clamp(t.cupo * chiaro, 90, 3600) * (1 - male * .45), ora, .3);
    /*  LA BOCCA SI MUOVE DENTRO LA NOTA. Formanti fermi sono un filtro;
     *  formanti che si spostano sono una bocca che cambia forma mentre il
     *  verso esce, ed e' quello che fa un animale vero — nessun richiamo sta
     *  sulla stessa vocale dal principio alla fine. I due si muovono in senso
     *  OPPOSTO, che e' come si aprono le vocali. */
    const b1 = this.bocca1 || 1, b2 = this.bocca2 || 1;
    this.f1.frequency.setTargetAtTime(clamp(t.formanti[0] * chiaro * b1, 70, 2000), ora, .09);
    this.f2.frequency.setTargetAtTime(clamp(t.formanti[1] * chiaro * b2, 180, 4200), ora, .09);
    if (this.soffioF)
      this.soffioF.frequency.setTargetAtTime(clamp(t.formanti[1] * chiaro * b2 * .85, 150, 5000), ora, .12);
    if (this.sub)
      this.sub.frequency.setTargetAtTime(fBase * .5 * (1 - male * .28), ora, .09);

    /*  E IL SUONO SI APRE QUANDO E' FORTE. Anche questo lo fa qualunque cosa
     *  con dei polmoni: piu' spinge, piu' esce roba in alto. Un taglio fisso
     *  dava sempre lo stesso colore a qualunque volume, che e' la firma di un
     *  filtro e non di una gola. */
    this.veloMul = (this.veloMul || 1) + (1 - (this.veloMul || 1)) * Math.min(1, dt * 2.6);
    this.velo.frequency.setTargetAtTime(
      clamp(t.velo * chiaro * this.veloMul, 200, 6000), ora, .08);
  }

  spegni() {
    if (this.morta) return;
    this.morta = true;
    const ora = audio.ctx.currentTime;
    this.vol.gain.cancelScheduledValues(ora);
    this.vol.gain.setTargetAtTime(0, ora, .12);
    const stop = ora + .6;
    for (const o of this.osc) o.stop(stop);
    for (const o of this.vib) o.stop(stop);
    for (const o of this.gorg) o.stop(stop);
    for (const v of this.vagare) { try { v.stop(stop); } catch (e) {} }
    if (this.sub) this.sub.stop(stop);
    if (this.soffio) { try { this.soffio.stop(stop); } catch (e) {} }
    this.anelloOsc.stop(stop);
    setTimeout(() => { for (const n of this.nodi) try { n.disconnect(); } catch (e) {} }, 900);
  }
}

/* --- avvio, spegnimento, catena comune ---------------------------------- */
function audioAvvia() {
  if (audio.ctx) {
    if (audio.ctx.state === 'suspended') audio.ctx.resume();
    return true;
  }
  const AC = window.AudioContext || window.webkitAudioContext;
  if (!AC) return false;
  const ctx = audio.ctx = new AC();

  const master = ctx.createGain();
  master.gain.value = volPerc(audio.vol.master);
  /*  Un compressore in fondo, non per «alzare il volume» ma perche' sette voci
   *  piu' una mischia sommano picchi che tagliano. Misurato in combattimento
   *  con quattro voci e attacchi in corso: -11 dBFS di media e picchi a .81,
   *  cioe' a un soffio dal fondo scala. Con questa taratura — soglia bassa e
   *  rapporto alto — le scene piene si tengono, e quelle tranquille non se ne
   *  accorgono perche' restano molto sotto la soglia. */
  const comp = ctx.createDynamicsCompressor();
  comp.threshold.value = -24; comp.knee.value = 10;
  comp.ratio.value = 12; comp.attack.value = .003; comp.release.value = .25;
  master.connect(comp).connect(ctx.destination);

  const secco = ctx.createGain(); secco.gain.value = 1; secco.connect(master);

  const conv = ctx.createConvolver();
  /*  Coda misurata. Tre secondi e mezzo di riverbero con dieci voci sopra
   *  diventano una nebbia: le note si sovrappongono alle code di quelle prima
   *  e non si distingue piu' chi ha cantato cosa. Due secondi e mezzo, e con
   *  un decadimento piu' ripido, danno ancora lo spazio dell'acqua senza
   *  seppellirci dentro la frase. */
  conv.buffer = creaRiverbero(ctx, 2.4, 2.9);
  const mandRiv = ctx.createGain(); mandRiv.gain.value = 1;
  const ritRiv = ctx.createGain(); ritRiv.gain.value = .38;
  mandRiv.connect(conv).connect(ritRiv).connect(master);

  /*  ECO A FEEDBACK con un passa-basso nell'anello: ogni ripetizione torna piu'
   *  scura della precedente, che e' quel che fa una stanza vera. Senza il
   *  filtro le ripetizioni restano squillanti e si sente il nastro. */
  const del = ctx.createDelay(2);
  del.delayTime.value = .47;
  const fb = ctx.createGain(); fb.gain.value = .52;
  const fbLp = ctx.createBiquadFilter();
  fbLp.type = 'lowpass'; fbLp.frequency.value = 760;
  del.connect(fbLp).connect(fb).connect(del);
  const mandEco = ctx.createGain(); mandEco.gain.value = 1;
  const ritEco = ctx.createGain(); ritEco.gain.value = .55;
  mandEco.connect(del).connect(ritEco).connect(master);

  Object.assign(audio, { master, comp, secco, mandRiv, mandEco, pronto: true });
  return true;
}

function audioSpegni() {
  for (const v of audio.voci.values()) v.spegni();
  audio.voci.clear();
  if (audio.ctx && audio.ctx.state === 'running') audio.ctx.suspend();
}

/** aggiorna l'ascoltatore dalla telecamera: e' lui a definire destra e sinistra */
function audioAscoltatore(ora) {
  const l = audio.ctx.listener;
  const p = camera.position;
  _v1.set(0, 0, -1).applyQuaternion(camera.quaternion);
  _v2.set(0, 1, 0).applyQuaternion(camera.quaternion);
  if (l.positionX) {
    l.positionX.setTargetAtTime(p.x, ora, .04);
    l.positionY.setTargetAtTime(p.y, ora, .04);
    l.positionZ.setTargetAtTime(p.z, ora, .04);
    l.forwardX.setTargetAtTime(_v1.x, ora, .04);
    l.forwardY.setTargetAtTime(_v1.y, ora, .04);
    l.forwardZ.setTargetAtTime(_v1.z, ora, .04);
    l.upX.setTargetAtTime(_v2.x, ora, .04);
    l.upY.setTargetAtTime(_v2.y, ora, .04);
    l.upZ.setTargetAtTime(_v2.z, ora, .04);
  } else {
    l.setPosition(p.x, p.y, p.z);
    l.setOrientation(_v1.x, _v1.y, _v1.z, _v2.x, _v2.y, _v2.z);
  }
}

/**
 *  Ogni fotogramma: chi merita una voce, chi la perde, e dove sta.
 *
 *  Le voci si danno ai piu' VICINI alla telecamera, non a tutti: dieci voci
 *  sono gia' una sessantina di oscillatori, e la undicesima non si
 *  distinguerebbe comunque nel mucchio.
 */
/**
 *  L'esserino sotto il puntatore, se ce n'e' uno vivo.
 *
 *  Serve per ISOLARLO: passandogli sopra il mouse si sente lui solo, e questa
 *  e' la sola maniera pratica di capire com'e' fatta una voce quando in vasca
 *  ce ne sono sette che cantano insieme. Il resto tace finche' il puntatore
 *  non se ne va — non si abbassa, tace, perche' un fondo attenuato lascerebbe
 *  comunque il riverbero degli altri addosso a quello che si vuole sentire.
 */
function _ascoltatoDaSolo() {
  const c = hoverCell;
  if (!c || c.dead || !c.creature || !c.creature.alive) return null;
  return c.creature;
}

function audioAggiorna(dt) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  const ora = audio.ctx.currentTime;
  audioAscoltatore(ora);

  const solo = _ascoltatoDaSolo();
  const cand = [];
  /*  Si scrive DOPO aver deciso le voci, in fondo alla funzione: qui la mappa
   *  e' ancora quella del fotogramma prima. */
  if (solo) cand.push([0, solo]);               // lui e nessun altro
  else for (const v of world.vessels) {
    if (world.focus && v !== world.focus) continue;
    for (const cr of v.creatures) {
      if (!cr.alive || !cr.cells.length) continue;
      cand.push([cr.centroid.distanceToSquared(camera.position), cr]);
    }
  }
  cand.sort((a, b) => a[0] - b[0]);
  const vivi = new Set();
  for (let i = 0; i < Math.min(AUDIO_MAX_VOCI, cand.length); i++) vivi.add(cand[i][1]);

  for (const [cr, voce] of audio.voci) {
    if (!vivi.has(cr)) { voce.spegni(); audio.voci.delete(cr); }
  }
  for (const cr of vivi) {
    let voce = audio.voci.get(cr);
    /*  Se il genoma e' cambiato, `timbroDi` restituisce un oggetto NUOVO: la
     *  voce che sta suonando ha ancora dentro le frequenze vecchie, cablate
     *  negli oscillatori, e va rifatta. Cambiare il DNA e sentire ancora la
     *  voce di prima sarebbe la cosa piu' strana di tutte. */
    if (voce && voce.t !== timbroDi(cr)) { voce.spegni(); voce = null; }
    if (!voce) { voce = new Voce(cr); audio.voci.set(cr, voce); }
    voce.aggiorna(dt, ora);
  }

  aggiornaOraAudio(solo);
  aggiornaFraseAudio(solo);

  // il tetto ai colpi si scarica da solo
  audio.colpiT += dt;
  if (audio.colpiT > .1) { audio.colpiT = 0; audio.colpiOra = Math.max(0, audio.colpiOra - COLPI_SFOGO); }
}

/* --- COLPI: sintesi a evento ---------------------------------------------
 *  Ogni attacco e' una piccola macchina a se': sorgente, filtro, inviluppo,
 *  mandate. Nascono e muoiono nel giro di un secondo, e i nodi si sconnettono
 *  da soli quando l'inviluppo e' finito — un `OscillatorNode` fermato non si
 *  puo' riusare, quindi tanto vale buttarlo.
 * ---------------------------------------------------------------------- */
/**
 *  Questo colpo si sente da dove stiamo guardando?
 *
 *  Le voci gia' lo fanno — `audioAggiorna` salta i recipienti che non sono
 *  quello a fuoco — ma i colpi no, e si sentivano risse da vasche fuori
 *  campo: un rumore senza niente da guardare, che non si capisce da dove
 *  venga. Guardando dentro un recipiente si sente quel recipiente.
 *
 *  Quando non c'e' un esserino a cui appendere il suono (certi effetti
 *  esistono senza padrone) si decide dalla posizione, prendendo il recipiente
 *  piu' vicino: e' esatto quanto serve, visto che i recipienti sono ben
 *  separati nello spazio.
 */
function _quiSiSente(cr, pos) {
  /*  Col puntatore su un esserino conta solo lui, e prima di ogni altra
   *  regola: si vuole sentire quella bestia li', vasca a fuoco o no. */
  const solo = _ascoltatoDaSolo();
  if (solo) {
    if (cr) return cr === solo;
    if (!pos) return false;
    /*  Un effetto senza padrone si assegna a chi gli sta piu' vicino, misurato
     *  sulla SUPERFICIE e non sul centro: un colosso il cui baricentro e'
     *  lontano puo' benissimo avere un fianco appoggiato li'. Una soglia in
     *  unita' fisse non funzionava — in un vasetto stanno tutti dentro qualche
     *  unita' e la soglia lasciava passare l'intera vasca. */
    let vicino = null, min = Infinity;
    for (const v of world.vessels) {
      for (const c of v.creatures) {
        if (!c.alive || !c.cells.length) continue;
        const d = pos.distanceTo(c.centroid) - c.radius;
        if (d < min) { min = d; vicino = c; }
      }
    }
    return vicino === solo;
  }
  const f = world.focus;
  if (!f) return true;                          // panoramica: si sente tutto
  if (cr && cr.vessel) return cr.vessel === f;
  if (!pos) return true;
  let vicino = null, min = Infinity;
  for (const v of world.vessels) {
    const d = v.pos.distanceToSquared(pos);
    if (d < min) { min = d; vicino = v; }
  }
  return vicino === f;
}

function _colpoBus(pos, riv, eco, sc) {
  const ctx = audio.ctx;
  const g = ctx.createGain(); g.gain.value = 1;
  const pan = ctx.createPanner();
  pan.panningModel = 'HRTF'; pan.distanceModel = 'inverse';
  pan.refDistance = 4; pan.rolloffFactor = .7; pan.maxDistance = 45;
  if (pan.positionX) {
    pan.positionX.value = pos.x; pan.positionY.value = pos.y; pan.positionZ.value = pos.z;
  } else pan.setPosition(pos.x, pos.y, pos.z);
  g.connect(pan);
  const s = ctx.createGain(); s.gain.value = .9 * sc; pan.connect(s).connect(audio.secco);
  const r = ctx.createGain(); r.gain.value = riv * sc; pan.connect(r).connect(audio.mandRiv);
  const e = ctx.createGain(); e.gain.value = eco * sc; pan.connect(e).connect(audio.mandEco);
  return { ing: g, pulisci: (quando) => setTimeout(() => {
    try { g.disconnect(); pan.disconnect(); s.disconnect(); r.disconnect(); e.disconnect(); } catch (x) {}
  }, quando * 1000 + 400) };
}

function _sorgenteRumore(dur) {
  const ctx = audio.ctx;
  const n = ctx.createBufferSource();
  n.buffer = rumoreAudio(ctx);
  n.loop = true;
  n.playbackRate.value = .8 + Math.random() * .5;
  return n;
}

/**
 *  Il suono di un attacco. Il carattere e' del TIPO d'arma — un acido sfrigola
 *  e una scarica schiocca, sempre — ma altezza, sporcizia e coda vengono dal
 *  genoma di chi colpisce: la stessa arma su due esserini diversi non fa lo
 *  stesso rumore, come non lo fa lo stesso urlo in due gole diverse.
 */
function audioAttacco(kind, pos, cr) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  if (!_quiSiSente(cr, pos)) return;
  if (audio.colpiOra > COLPI_TETTO.attacco) return;   // e l'attacco ha la precedenza
  audio.colpiOra++;
  const ctx = audio.ctx, ora = ctx.currentTime;
  const t = cr ? timbroDi(cr) : null;
  const alt = t ? clamp(t.base / 120, .4, 2.6) : 1;      // la voce decide l'altezza
  const sporco = t ? t.dist : .4;
  const V = volPerc(audio.vol.colpi);

  if (kind === 'acid') {
    /*  ACIDO: deve FRIGGERE. Tutta la sostanza sta negli scoppiettii del
     *  buffer; qui sopra ci va solo il colore. Passa-alto perche' friggere e'
     *  un suono acuto — sotto i mille hertz non c'e' niente da sentire — e
     *  una gobba sui quattromila, che e' dove stanno le bolle piccole. */
    /*  E STA IN BASSO. Acido e scarica sono tutti e due fatti di granelli di
     *  rumore, e messi nella stessa banda si somigliavano troppo: da lontano
     *  non si capiva quale delle due armi stesse colpendo. Adesso li separa
     *  un'ottava e mezza — l'acido sotto, la scarica sopra — che e' anche
     *  giusto di suo: una roba che scioglie borbotta, una scintilla schiocca. */
    const b = _colpoBus(pos, .25, .12, .55 * V);
    const dur = .40 + Math.random() * .14;
    const src = ctx.createBufferSource();
    src.buffer = _bufferFrittura(ctx, dur, sporco);
    src.playbackRate.value = clamp(alt * .72, .5, 1.15);   // grana piu' grossa

    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass'; hp.frequency.value = 520 * alt; hp.Q.value = .7;
    const pk = ctx.createBiquadFilter();
    pk.type = 'peaking'; pk.frequency.value = 1900 * alt; pk.Q.value = 1.1; pk.gain.value = 7;
    // e un tetto sopra, o le bolle piu' minute risalgono dove sta la scarica
    const tetto = ctx.createBiquadFilter();
    tetto.type = 'lowpass'; tetto.frequency.value = 3400 * alt; tetto.Q.value = .6;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, ora);
    g.gain.linearRampToValueAtTime(.75, ora + .03);
    g.gain.setValueAtTime(.75, ora + dur * .5);
    g.gain.exponentialRampToValueAtTime(.001, ora + dur);
    src.connect(hp).connect(pk).connect(tetto).connect(g).connect(b.ing);

    /*  E un filo di CORROSIONE sotto: gli stessi scoppietti passati bassi e
     *  risonanti. E' la parte che fa sentire che sta mangiando qualcosa
     *  invece di friggere nel vuoto. */
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.Q.value = 6; lp.frequency.value = 300 * alt;
    const gl = ctx.createGain(); gl.gain.value = .85;
    src.connect(lp).connect(gl).connect(g);

    src.start(ora); b.pulisci(dur + .3);

  } else if (kind === 'spark') {
    /*  SCARICA: un arco che sputa. Tutta la sostanza sta nel buffer — vedi
     *  `_bufferScarica` — e qui sopra ci vanno soltanto la colorazione e il
     *  peso. Il passa-alto tiene la scarica dov'e' il suo posto, in alto: un
     *  arco e' sottile, il tonfo grave lo fa solo l'aria di un fulmine. */
    const b = _colpoBus(pos, .34, .26, .95 * V);
    const dur = .74 + Math.random() * .30;
    const src = ctx.createBufferSource();
    src.buffer = _bufferScarica(ctx, dur, sporco);
    src.playbackRate.value = clamp(alt * 1.3, .9, 2.1);   // grana piu' fine

    // sopra l'acido di un'ottava e mezza buona: un arco e' sottile e squillante
    const hp = ctx.createBiquadFilter();
    hp.type = 'highpass'; hp.frequency.value = 1800 * alt; hp.Q.value = .7;
    /*  E TIENE. Prima l'inviluppo cascava esponenzialmente dall'istante zero,
     *  quindi per due terzi della durata non c'era quasi piu' niente: la
     *  scarica finiva subito e il resto era coda. Ora resta su per un terzo
     *  buono e poi cala: e' quello a farla sentire come un contatto che
     *  continua a saltare invece che come un botto. */
    const g = ctx.createGain();
    g.gain.setValueAtTime(.95, ora);
    g.gain.linearRampToValueAtTime(.72, ora + dur * .14);
    g.gain.setValueAtTime(.72, ora + dur * .42);
    g.gain.exponentialRampToValueAtTime(.0015, ora + dur);
    src.connect(hp).connect(g).connect(b.ing);

    /*  Il CANTO dell'arco: una risonanza stretta e alta che l'arco eccita, e
     *  che gli da' quel timbro metallico. Sfarfalla perche' un arco fermo
     *  suonerebbe un fischio. */
    const ris = ctx.createBiquadFilter();
    ris.type = 'bandpass'; ris.Q.value = 11;
    const fr = (3900 + Math.random() * 3400) * alt;
    ris.frequency.setValueAtTime(fr, ora);
    for (let i = 1; i <= 6; i++)
      ris.frequency.setValueAtTime(fr * (.72 + Math.random() * .55), ora + dur * i / 7);
    const rg = ctx.createGain();
    rg.gain.setValueAtTime(.7, ora);
    rg.gain.setValueAtTime(.7, ora + dur * .4);      // tiene anche lei
    rg.gain.exponentialRampToValueAtTime(.001, ora + dur * .92);
    src.connect(ris).connect(rg).connect(b.ing);

    // lo schiocco dell'aria: corto e sotto, giusto per dargli un corpo
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(260 * alt, ora);
    o.frequency.exponentialRampToValueAtTime(84 * alt, ora + .07);
    // meno grave di prima: il grave adesso e' roba dell'acido
    const og = ctx.createGain();
    og.gain.setValueAtTime(.26, ora);
    og.gain.exponentialRampToValueAtTime(.001, ora + .09);
    o.connect(og).connect(b.ing);

    src.start(ora); o.start(ora); o.stop(ora + .14); b.pulisci(dur + .3);

  } else if (kind === 'wave') {
    /*  SONICO: un URLO. Non e' un'onda d'aria, e' una gola che urla, e la
     *  differenza fra le due cose sta tutta nella RUVIDEZZA: una nota tenuta,
     *  per quanto forte e distorta, resta un suono di sintetizzatore. Un urlo
     *  vero e' un'oscillazione che va in crisi — le corde vocali smettono di
     *  battere regolari, si spaccano in due o tre regimi che convivono, e
     *  l'intonazione trema senza riprendersi. E' quello a far rizzare i peli.
     *
     *  Qui la crisi si ottiene con tre cose insieme: un SOTTOTONO all'ottava
     *  bassa leggermente stonato, che e' il raddoppio di periodo che fa una
     *  laringe forzata; una gemella scordata di pochi centesimi, che batte; e
     *  un TREMOLIO di intonazione a scatti irregolari, riprogrammato una
     *  ventina di volte lungo l'urlo. Poi formanti alti, distorsione, e il
     *  soffio della turbolenza sopra a tutto.
     */
    // scende di sei decibel: era il colpo piu' forte del mucchio e schiacciava
    const b = _colpoBus(pos, .5, .34, .5 * V);
    const dur = .55 + Math.random() * .3;
    /*  L'altezza segue la taglia, ma COMPRESSA. Al primo tentativo l'urlo
     *  moltiplicava tutto per `alt` come gli altri colpi, e su un esserino
     *  grosso finiva a duecento hertz con niente sopra il chilohertz: misurato,
     *  zero per cento dell'energia in alto. Non era un urlo, era un rantolo.
     *  Un animale grande urla piu' basso di uno piccolo, non urla in cantina:
     *  il fondo va tenuto alto per tutti. */
    const f0 = clamp(230 + (t ? t.base : 110) * 2.2, 270, 1000) * (.9 + Math.random() * .25);
    const altU = clamp(.6 + alt * .5, .72, 1.55);   // per formanti e soffio

    // la gola: distorsione forte, e' quel che porta un grido oltre il parlato
    const ws = ctx.createWaveShaper();
    ws.curve = curvaDistorsione(clamp(.55 + sporco * .5, .5, 1), .3);
    ws.oversample = '2x';

    /*  I FORMANTI dell'urlo stanno in ALTO. Una vocale bassa da' un ruggito;
     *  sono i due picchi sopra il chilohertz — e la punta attorno ai tremila,
     *  quella che nel canto chiamano formante del cantante — a rendere un
     *  grido percettibile sopra qualunque altra cosa stia suonando. */
    const somma = ctx.createGain(); somma.gain.value = .62;
    somma.connect(ws);
    const usc = ctx.createGain();
    for (const [fr, q, amp] of [[ (t ? t.formanti[0] * 2.6 : 900) * altU, 4.5, 1.1 ],
                                [ 1900 * altU, 5.5, 1 ],
                                [ 3100 * altU, 7, .9 ]]) {
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass'; f.frequency.value = clamp(fr, 300, 5200); f.Q.value = q;
      const fg = ctx.createGain(); fg.gain.value = amp;
      ws.connect(f).connect(fg).connect(usc);
    }
    const dritto = ctx.createGain(); dritto.gain.value = .35;
    ws.connect(dritto).connect(usc);

    const g = ctx.createGain();
    g.gain.setValueAtTime(0, ora);
    g.gain.linearRampToValueAtTime(1, ora + .022);     // un grido non sfuma dentro
    g.gain.setValueAtTime(1, ora + dur * .45);
    g.gain.exponentialRampToValueAtTime(.001, ora + dur);
    usc.connect(g).connect(b.ing);

    /*  Le tre voci della crisi. Il contorno e' quello di un grido: sale di
     *  colpo sopra l'intonazione di partenza, ci resta, poi si sfianca. */
    const osc = [];
    for (const [mul, tipo, amp] of [[1, 'sawtooth', 1], [1.006, 'sawtooth', .7],
                                    [.5, 'square', .38]]) {
      const o = ctx.createOscillator(); o.type = tipo;
      const base = f0 * mul * (mul === .5 ? .985 : 1);   // il sottotono e' stonato
      o.frequency.setValueAtTime(base * .82, ora);
      o.frequency.linearRampToValueAtTime(base * 1.12, ora + .05);
      // il tremolio: scatti irregolari, e nessuno di loro trema come gli altri
      for (let k = 1; k <= 18; k++) {
        const u = k / 19;
        o.frequency.setValueAtTime(base * (1.12 - u * .34) * (1 + (Math.random() - .5) * .12),
                                   ora + .05 + (dur - .05) * u);
      }
      const og = ctx.createGain(); og.gain.value = amp;
      o.connect(og).connect(somma);
      o.start(ora); o.stop(ora + dur + .05);
      osc.push(o);
    }

    /*  LA TURBOLENZA: l'aria che passa forzata. Senza, l'urlo resta pulito e
     *  suona cantato; e' il soffio a farlo sentire come uno sforzo. */
    const n = _sorgenteRumore();
    const nb = ctx.createBiquadFilter();
    nb.type = 'bandpass'; nb.Q.value = .8;
    nb.frequency.setValueAtTime(2800 * altU, ora);
    nb.frequency.exponentialRampToValueAtTime(1200 * altU, ora + dur);
    const ng = ctx.createGain();
    ng.gain.setValueAtTime(0, ora);
    ng.gain.linearRampToValueAtTime(.3, ora + .04);
    ng.gain.exponentialRampToValueAtTime(.001, ora + dur * .9);
    n.connect(nb).connect(ng).connect(b.ing);
    n.start(ora); n.stop(ora + dur);

    /*  E sotto resta un filo di ONDA: e' pur sempre un colpo che spinge, e
     *  senza niente di grave non avrebbe peso addosso. Poco pero': con mezzo
     *  guadagno si prendeva lei tutto lo spettro e l'urlo spariva sotto. */
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(130 * alt, ora);
    o.frequency.exponentialRampToValueAtTime(40 * alt, ora + .3);
    const og = ctx.createGain();
    og.gain.setValueAtTime(.26, ora);
    og.gain.exponentialRampToValueAtTime(.001, ora + .34);
    o.connect(og).connect(b.ing);
    o.start(ora); o.stop(ora + .5);
    b.pulisci(dur + .4);

  } else if (kind === 'gas') {
    /*  GAS: un SOFFIO, cioe' aria che esce da una fessura stretta.
     *
     *  Prima era rumore rosa — due passa-basso in fila — con una gobba sui
     *  trecento hertz: un rombo sordo, che e' il suono di un tubo grosso e non
     *  quello di uno sbuffo. Un soffio vive in ALTO, fra i due e i cinquemila
     *  hertz, e la sua forma e' quella di una fessura che si apre e si
     *  richiude: la banda si allarga in fretta e poi si stringe, e il picco
     *  scende mentre la pressione cala.
     *
     *  Ed e' piu' forte: era il colpo piu' silenzioso del mucchio e in mezzo
     *  agli altri spariva, mentre e' un attacco ad area che va sentito. */
    const b = _colpoBus(pos, .35, .18, .95 * V);
    const dur = .85 + Math.random() * .3;

    // la fessura: passa-banda che si apre, poi si chiude scendendo
    const n = _sorgenteRumore();
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.setValueAtTime(1500 * alt, ora);
    bp.frequency.linearRampToValueAtTime(3400 * alt, ora + dur * .22);
    bp.frequency.exponentialRampToValueAtTime(900 * alt, ora + dur);
    bp.Q.setValueAtTime(2.6, ora);
    bp.Q.linearRampToValueAtTime(.7, ora + dur * .3);      // stretta, poi larga
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, ora);
    g.gain.linearRampToValueAtTime(.62, ora + .09);
    g.gain.setValueAtTime(.62, ora + dur * .35);
    g.gain.exponentialRampToValueAtTime(.001, ora + dur);
    n.connect(bp).connect(g).connect(b.ing);

    /*  E sotto, il corpo dello sbuffo: la stessa aria passata bassa, appena
     *  accennata. Da sola era tutto il suono; adesso e' il peso sotto il
     *  sibilo, e senza di lei il soffio sarebbe di lattina. */
    const n2 = _sorgenteRumore();
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.frequency.value = 620 * alt; lp.Q.value = .8;
    const g2 = ctx.createGain();
    g2.gain.setValueAtTime(0, ora);
    g2.gain.linearRampToValueAtTime(.22, ora + .14);
    g2.gain.exponentialRampToValueAtTime(.001, ora + dur * .9);
    n2.connect(lp).connect(g2).connect(b.ing);

    n.start(ora); n.stop(ora + dur + .05);
    n2.start(ora); n2.stop(ora + dur + .05);
    b.pulisci(dur + .3);

  } else if (kind === 'ink') {
    /*  INCHIOSTRO: un tonfo sordo e una nuvola che si allarga. Tutto sotto i
     *  seicento hertz: e' l'unica arma che non fa male, e non deve spaventare. */
    const b = _colpoBus(pos, .5, .25, .7 * V);
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(180 * alt, ora);
    o.frequency.exponentialRampToValueAtTime(46 * alt, ora + .45);
    const og = ctx.createGain();
    og.gain.setValueAtTime(.6, ora);
    og.gain.exponentialRampToValueAtTime(.001, ora + .5);
    o.connect(og).connect(b.ing);
    const n = _sorgenteRumore();
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 600;
    const ng = ctx.createGain();
    ng.gain.setValueAtTime(0, ora);
    ng.gain.linearRampToValueAtTime(.25, ora + .1);
    ng.gain.exponentialRampToValueAtTime(.001, ora + .9);
    n.connect(lp).connect(ng).connect(b.ing);
    o.start(ora); o.stop(ora + .55); n.start(ora); n.stop(ora + .95); b.pulisci(1);

  } else if (kind === 'venom') {
    /*  URTICANTE: una lama che entra.
     *
     *  Prima era un'onda quadra che saliva da 900 a 2600 hertz: intonata, e
     *  una cosa che si infilza non canta. Il gesto vero e' fatto di tre
     *  momenti, e sono tre suoni diversi in fila stretta:
     *    - il FILO, la risonanza metallica del colpo, acutissima e cortissima;
     *    - la SPINTA, che entrando si fa via via piu' sorda: e' il passa-banda
     *      che scende, e da' la direzione — dentro, non fuori;
     *    - la CARNE che si apre, un risonante grave che casca.
     *  Nessuno dei tre ha un'altezza riconoscibile, ed e' voluto.
     */
    const b = _colpoBus(pos, .2, .1, .6 * V);

    // il filo
    const n1 = _sorgenteRumore();
    const ris = ctx.createBiquadFilter();
    ris.type = 'bandpass'; ris.Q.value = 16 + Math.random() * 10;
    ris.frequency.setValueAtTime((4200 + Math.random() * 1600) * alt, ora);
    ris.frequency.exponentialRampToValueAtTime(2600 * alt, ora + .05);
    const g1 = ctx.createGain();
    g1.gain.setValueAtTime(0, ora);
    g1.gain.linearRampToValueAtTime(.8, ora + .0015);
    g1.gain.exponentialRampToValueAtTime(.001, ora + .055);
    n1.connect(ris).connect(g1).connect(b.ing);
    n1.start(ora); n1.stop(ora + .07);

    // la spinta che entra
    const n2 = _sorgenteRumore();
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.Q.value = 1.3;
    bp.frequency.setValueAtTime(2700 * alt, ora + .004);
    bp.frequency.exponentialRampToValueAtTime(430 * alt, ora + .09);
    const g2 = ctx.createGain();
    g2.gain.setValueAtTime(0, ora + .004);
    g2.gain.linearRampToValueAtTime(.7, ora + .012);
    g2.gain.exponentialRampToValueAtTime(.001, ora + .095);
    n2.connect(bp).connect(g2).connect(b.ing);
    n2.start(ora); n2.stop(ora + .12);

    // la carne che si apre
    const n3 = _sorgenteRumore();
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.Q.value = 8 + Math.random() * 4;
    lp.frequency.setValueAtTime(680 * alt, ora + .012);
    lp.frequency.exponentialRampToValueAtTime(110 * alt, ora + .075);
    const g3 = ctx.createGain();
    g3.gain.setValueAtTime(0, ora + .012);
    g3.gain.linearRampToValueAtTime(.55, ora + .02);
    g3.gain.exponentialRampToValueAtTime(.001, ora + .085);
    n3.connect(lp).connect(g3).connect(b.ing);
    n3.start(ora); n3.stop(ora + .1);
    b.pulisci(.2);

  } else if (kind === 'impact') {
    /*  COLPO DI TENTACOLO: carne colpita.
     *
     *  Prima era un oscillatore triangolare che scendeva da 220 a 55 hertz con
     *  un quarto di secondo di coda — che e' parola per parola la ricetta con
     *  cui si sintetizza un TOM, ed e' quello che si sentiva. Un tamburo e'
     *  esattamente l'opposto di un corpo: e' accordato, la sua coda e' pulita e
     *  dura, e la pelle e' fatta apposta per continuare a vibrare. La carne
     *  non e' accordata e non risuona: assorbe. Qualunque cosa la colpisca e'
     *  finita in meno di un decimo di secondo.
     *
     *  Quindi via l'oscillatore intonato, e tre pezzi di rumore smorzato:
     *    - lo SCHIAFFO, la banda media del contatto, trenta millesimi e basta;
     *    - la CARNE, un risonante che precipita — e' il tessuto molle che si
     *      sposta, ed e' l'unico modo di far sentire «bagnato» invece di
     *      «cavo»; su un tamburo la stessa figura non esiste;
     *    - il PESO, un tonfo grave cortissimo, che da' la massa senza dare
     *      una nota: dura settanta millesimi contro i duecentocinquanta di
     *      prima, ed e' li' che stava tutta l'impressione di tamburo.
     *  Sopra, due spruzzi minuscoli sfasati di qualche millesimo: un colpo su
     *  un corpo non e' mai un transiente solo e pulito.
     */
    const b = _colpoBus(pos, .3, .12, .85 * V);
    const durc = .075 + Math.random() * .03;

    // lo schiaffo
    const ns = _sorgenteRumore();
    const bp = ctx.createBiquadFilter();
    bp.type = 'bandpass'; bp.Q.value = 1.1;
    bp.frequency.setValueAtTime((1250 + Math.random() * 700) * alt, ora);
    bp.frequency.exponentialRampToValueAtTime(520 * alt, ora + .035);
    const gs = ctx.createGain();
    gs.gain.setValueAtTime(0, ora);
    gs.gain.linearRampToValueAtTime(.9, ora + .0012);
    gs.gain.exponentialRampToValueAtTime(.001, ora + .034);
    ns.connect(bp).connect(gs).connect(b.ing);
    ns.start(ora); ns.stop(ora + .05);

    /*  la carne: un passa-basso risonante che casca da ottocento a novanta in
     *  sessanta millesimi. E' la stessa figura di un risucchio ma al contrario
     *  — li' saliva, qui precipita — ed e' quel che rende il colpo molle. */
    const nc = _sorgenteRumore();
    const lp = ctx.createBiquadFilter();
    lp.type = 'lowpass'; lp.Q.value = 9 + Math.random() * 4;
    lp.frequency.setValueAtTime((760 + Math.random() * 260) * alt, ora);
    lp.frequency.exponentialRampToValueAtTime(88 * alt, ora + durc * .8);
    const gc = ctx.createGain();
    gc.gain.setValueAtTime(0, ora);
    gc.gain.linearRampToValueAtTime(.85, ora + .003);
    gc.gain.exponentialRampToValueAtTime(.001, ora + durc);
    nc.connect(lp).connect(gc).connect(b.ing);
    nc.start(ora); nc.stop(ora + durc + .02);

    /*  il peso. Resta un grave, ma senza discesa lunga: e' un tonfo, e un
     *  tonfo non ha il tempo di far sentire dove va a finire. */
    const o = ctx.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(96 * alt, ora);
    o.frequency.exponentialRampToValueAtTime(52 * alt, ora + .04);
    const og = ctx.createGain();
    og.gain.setValueAtTime(.55, ora);
    og.gain.exponentialRampToValueAtTime(.001, ora + .07);
    o.connect(og).connect(b.ing);
    o.start(ora); o.stop(ora + .09);

    // gli spruzzi
    for (let i = 0; i < 2; i++) {
      const t0 = ora + .006 + Math.random() * .016;
      const nz = _sorgenteRumore();
      const f = ctx.createBiquadFilter();
      f.type = 'bandpass'; f.Q.value = 2.5;
      f.frequency.value = (700 + Math.random() * 1800) * alt;
      const gz = ctx.createGain();
      gz.gain.setValueAtTime(0, t0);
      gz.gain.linearRampToValueAtTime(.2 + Math.random() * .22, t0 + .001);
      gz.gain.exponentialRampToValueAtTime(.001, t0 + .012 + Math.random() * .01);
      nz.connect(f).connect(gz).connect(b.ing);
      nz.start(t0); nz.stop(t0 + .04);
    }
    b.pulisci(.2);
  }
}

/**
 *  IL VERSO DI DOLORE. Non e' un campione: e' la VOCE di quell'esserino,
 *  strapazzata — stesso timbro, stesse formanti, ma il tono parte alto e
 *  crolla, la distorsione sale e il gorgoglio si stringe in un rantolo.
 *
 *  E' questo a farlo riconoscere come SUO: un urlo generico direbbe soltanto
 *  «qualcuno ha preso un colpo», questo dice chi.
 */
function audioDolore(cr, quanto, pos) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  if (!cr || !cr.alive) return;
  if (!_quiSiSente(cr, pos)) return;
  const ctx = audio.ctx, ora = ctx.currentTime;
  // uno per esserino ogni tot: l'acido fa danno sessanta volte al secondo
  const ult = audio.ultimoDolore.get(cr) || 0;
  const soglia = clamp(.42 - quanto * .02, .16, .42);
  if (ora - ult < soglia) return;
  audio.ultimoDolore.set(cr, ora);
  if (audio.colpiOra > COLPI_TETTO.dolore) return;
  audio.colpiOra++;

  const t = timbroDi(cr);
  const forza = clamp(quanto / 14, .18, 1);
  /*  E ANCHE L'URLETTO SEGUE LA TAGLIA. La voce lo faceva gia' da un pezzo, il
   *  lamento no: usciva sempre alla stessa altezza, e una bestiola da otto
   *  cellule strillava come un colosso. E' lo stesso fattore che usa la voce,
   *  contato sulle cellule vive, quindi i due si muovono insieme — il lamento
   *  suona come la voce di CHI lo emette, che e' tutto il punto. */
  const tg = clamp(fattoreTaglia(cr) / TAGLIA_RIF, .45, 3.2);
  // volume contenuto: un lamento non deve coprire il colpo che l'ha causato
  const b = _colpoBus(pos || cr.centroid, t.riv * .8, t.eco * .7,
                      (.3 + forza * .42) * volPerc(audio.vol.colpi));
  const dur = .18 + forza * .5;

  const somma = ctx.createGain(); somma.gain.value = .5;
  for (let i = 0; i < 3; i++) {
    const o = ctx.createOscillator();
    o.type = t.forme[i];
    const f = t.base * tg * t.rapporti[i];
    // parte sopra e crolla: e' il profilo di un grido, non di un richiamo
    o.frequency.setValueAtTime(f * (1.5 + forza * 1.1), ora);
    o.frequency.exponentialRampToValueAtTime(Math.max(24, f * .62), ora + dur);
    const g = ctx.createGain(); g.gain.value = t.pesi[i];
    o.connect(g).connect(somma);
    o.start(ora); o.stop(ora + dur + .1);
  }
  const ws = ctx.createWaveShaper();
  ws.curve = curvaDistorsione(clamp(t.dist + .3, 0, 1), clamp(t.piega + .12, 0, .5));
  const f1 = ctx.createBiquadFilter();
  const chiaro = Math.sqrt(tg);          // corpo piccolo, timbro piu' chiaro
  f1.type = 'bandpass'; f1.frequency.value = t.formanti[0] * 1.25 * chiaro; f1.Q.value = t.formQ[0];
  const f2 = ctx.createBiquadFilter();
  f2.type = 'bandpass'; f2.frequency.value = t.formanti[1] * 1.1 * chiaro; f2.Q.value = t.formQ[1];
  const misto = ctx.createGain(); misto.gain.value = 1;
  somma.connect(ws);
  ws.connect(f1).connect(misto);
  ws.connect(f2).connect(misto);
  // il rantolo: tremolo veloce che si spegne insieme al grido
  const trem = ctx.createGain(); trem.gain.value = .7;
  const lfo = ctx.createOscillator(); lfo.type = 'square';
  lfo.frequency.setValueAtTime(t.gorgRate * 2.4, ora);
  lfo.frequency.exponentialRampToValueAtTime(Math.max(2, t.gorgRate * .7), ora + dur);
  const lg = ctx.createGain(); lg.gain.value = .3;
  lfo.connect(lg).connect(trem.gain); lfo.start(ora); lfo.stop(ora + dur + .1);
  misto.connect(trem);

  const env = ctx.createGain();
  env.gain.setValueAtTime(0, ora);
  env.gain.linearRampToValueAtTime(.4 + forza * .3, ora + .012);
  env.gain.exponentialRampToValueAtTime(.001, ora + dur);
  trem.connect(env).connect(b.ing);
  b.pulisci(dur + .3);
}

/**
 *  L'URLO FINALE.
 *
 *  E' il lamento portato alle estreme conseguenze, e la differenza sta tutta
 *  nel CONTORNO: un urletto di dolore parte alto e ricade subito, perche' dopo
 *  si continua a vivere. Questo parte alto, tiene, e poi CASCA per un'ottava e
 *  mezza senza piu' risalire, mentre il tremolo rallenta fino a diventare un
 *  rantolo e la distorsione cresce. Alla fine il fiato: un soffio grave che si
 *  spegne, che e' quel che resta quando la voce non c'e' piu'.
 *
 *  Segue la taglia come tutto il resto — una bestiola muore acuta, un colosso
 *  muore grave — ed e' volutamente non fortissimo: e' un momento, non un
 *  fuoco d'artificio, e in una mischia ne muoiono tre alla volta.
 */
function audioMorte(cr, pos) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  if (!cr) return;
  // `cr.alive` e' gia' falso quando questo suona: la guardia non lo controlla
  if (!_quiSiSente(cr, pos)) return;
  const ctx = audio.ctx, ora = ctx.currentTime;

  const t = timbroDi(cr);
  const tg = clamp(fattoreTaglia(cr) / TAGLIA_RIF, .45, 3.2);
  const dur = 1.0 + Math.random() * .55;
  const b = _colpoBus(pos || cr.centroid, t.riv, t.eco * .9, .62 * volPerc(audio.vol.colpi));

  const somma = ctx.createGain(); somma.gain.value = .5;
  for (let i = 0; i < 3; i++) {
    const o = ctx.createOscillator();
    o.type = t.forme[i];
    const f = t.base * tg * t.rapporti[i];
    /*  Sale, tiene, casca. Il gradino a meta' e' quel che lo fa sentire come
     *  un cedimento invece che come una discesa: prima resiste, poi molla. */
    o.frequency.setValueAtTime(f * (1.9 + Math.random() * .5), ora);
    o.frequency.linearRampToValueAtTime(f * 1.6, ora + dur * .22);
    o.frequency.exponentialRampToValueAtTime(Math.max(20, f * .34), ora + dur * .82);
    // e nell'ultimo tratto vaneggia: l'intonazione non tiene piu'
    for (let k = 1; k <= 4; k++)
      o.frequency.setValueAtTime(Math.max(18, f * (.34 - k * .03) * (1 + (Math.random() - .5) * .3)),
                                 ora + dur * (.82 + k * .04));
    const g = ctx.createGain(); g.gain.value = t.pesi[i];
    o.connect(g).connect(somma);
    o.start(ora); o.stop(ora + dur + .15);
  }

  // la gola si sporca mentre cede
  const ws = ctx.createWaveShaper();
  ws.curve = curvaDistorsione(clamp(t.dist + .45, 0, 1), clamp(t.piega + .2, 0, .5));
  const chiaro = Math.sqrt(tg);
  const f1 = ctx.createBiquadFilter();
  f1.type = 'bandpass'; f1.frequency.setValueAtTime(t.formanti[0] * 1.3 * chiaro, ora);
  f1.frequency.exponentialRampToValueAtTime(Math.max(60, t.formanti[0] * .5 * chiaro), ora + dur);
  f1.Q.value = t.formQ[0];
  const f2 = ctx.createBiquadFilter();
  f2.type = 'bandpass'; f2.frequency.setValueAtTime(t.formanti[1] * 1.15 * chiaro, ora);
  f2.frequency.exponentialRampToValueAtTime(Math.max(140, t.formanti[1] * .45 * chiaro), ora + dur);
  f2.Q.value = t.formQ[1];
  const misto = ctx.createGain(); misto.gain.value = 1;
  somma.connect(ws);
  ws.connect(f1).connect(misto);
  ws.connect(f2).connect(misto);

  /*  IL RANTOLO: il tremolo parte veloce e RALLENTA fino a due battiti al
   *  secondo. E' quel rallentamento a leggersi come una cosa che si ferma —
   *  un tremolo costante suonerebbe soltanto come un effetto. */
  const trem = ctx.createGain(); trem.gain.value = .62;
  const lfo = ctx.createOscillator(); lfo.type = 'square';
  lfo.frequency.setValueAtTime(t.gorgRate * 3.2, ora);
  lfo.frequency.exponentialRampToValueAtTime(2.2, ora + dur * .9);
  const lg = ctx.createGain(); lg.gain.value = .38;
  lfo.connect(lg).connect(trem.gain); lfo.start(ora); lfo.stop(ora + dur + .15);
  misto.connect(trem);

  const env = ctx.createGain();
  env.gain.setValueAtTime(0, ora);
  env.gain.linearRampToValueAtTime(.72, ora + .03);
  env.gain.setValueAtTime(.72, ora + dur * .45);
  env.gain.exponentialRampToValueAtTime(.001, ora + dur);
  trem.connect(env).connect(b.ing);

  /*  L'ULTIMO FIATO, che parte quando la voce e' gia' quasi finita: rumore
   *  passa-basso che si spegne. Senza, l'urlo finisce e basta; con, finisce
   *  e poi c'e' ancora qualcosa che esce. */
  const t0 = ora + dur * .62;
  const n = _sorgenteRumore();
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass'; lp.Q.value = 3.5;
  lp.frequency.setValueAtTime(520 * chiaro, t0);
  lp.frequency.exponentialRampToValueAtTime(120 * chiaro, t0 + dur * .5);
  const ng = ctx.createGain();
  ng.gain.setValueAtTime(0, t0);
  ng.gain.linearRampToValueAtTime(.3, t0 + .07);
  ng.gain.exponentialRampToValueAtTime(.001, t0 + dur * .5);
  n.connect(lp).connect(ng).connect(b.ing);
  n.start(t0); n.stop(t0 + dur * .55);

  b.pulisci(dur + .8);
}


/**
 *  LO STRAPPO: una cellula viene staccata di dosso in combattimento.
 *
 *  Non e' un colpo, e' un cedimento. Tre pezzi:
 *
 *  1. LA LACERAZIONE. Rumore in un passa-banda strettissimo il cui centro
 *     SALE di colpo e poi ricade: e' quel profilo — su e giu' in un quinto di
 *     secondo — che l'orecchio legge come «qualcosa che si apre», e non ci
 *     vuole nessun campione per ottenerlo.
 *  2. IL TONFO. Una sinusoide che cade sotto i cinquanta hertz: il peso della
 *     cosa che si stacca.
 *  3. LA GOLA. Le formanti della VITTIMA per un istante: e' quel che rende lo
 *     strappo di quell'esserino e non uno strappo qualunque.
 *
 *  Suona sulla cellula persa, non sul centro del corpo: si sente da che parte
 *  e' stato aperto.
 */
/**
 *  IL GRANO DELLO STRAPPO, disegnato campione per campione.
 *
 *  Uno sweep continuo di rumore filtrato suona come una frustata, non come
 *  qualcosa che si lacera: era il difetto della versione prima. Un tessuto che
 *  cede non fa UN suono, ne fa cento minuscoli in fila — le fibre non mollano
 *  tutte insieme, mollano una dopo l'altra, e l'orecchio riconosce lo strappo
 *  proprio da quella grana irregolare. Nessun filtro applicato a un rumore
 *  continuo la riproduce: la struttura sta nel tempo, non nello spettro.
 *
 *  Quindi il suono si scrive a mano in un buffer, in quattro tempi:
 *    1. la TRAZIONE, rumore basso che cresce mentre il tessuto si tende;
 *    2. la LACERAZIONE, granelli fitti che via via si diradano;
 *    3. lo SCHIOCCO, il granello grosso: la cellula si e' staccata;
 *    4. la coda, quattro fibre che cedono in ritardo.
 *
 *  Costa un buffer da qualche migliaio di campioni e un nodo solo a riprodurlo,
 *  meno di quanto costerebbe fare la stessa cosa con una catena di oscillatori.
 */
function _bufferStrappo(ctx, dur, ruvido) {
  const sr = ctx.sampleRate, n = Math.ceil(sr * dur) + 64;
  const buf = ctx.createBuffer(1, n, sr);
  const d = buf.getChannelData(0);

  /*  Un granello: rumore che decade in due o sei millesimi. E' corto apposta —
   *  piu' e' corto piu' suona come una rottura e meno come un fruscio. */
  const granello = (p, lung, amp) => {
    const k = 5.5 + Math.random() * 4;
    for (let i = 0; i < lung && p + i < n; i++) {
      const e = Math.exp(-k * i / lung);
      d[p + i] += amp * e * (Math.random() * 2 - 1);
    }
  };

  const finTraz = Math.floor(n * .30);
  const finLac = Math.floor(n * .74);

  // 1. TRAZIONE: fruscio che cresce, con qualche fibra che gia' cede
  for (let i = 0; i < finTraz; i++) {
    const u = i / finTraz;
    d[i] += (Math.random() * 2 - 1) * .05 * u * u;
  }
  for (let p = 0; p < finTraz; p += (sr * (.010 + Math.random() * .022)) | 0)
    granello(p, (sr * .0018) | 0, .06 + Math.random() * .10 * (p / finTraz));

  /*  2. LACERAZIONE: i granelli partono fitti e si diradano. E' il verso
   *  giusto — le fibre cedono in valanga e poi restano le ultime — e
   *  all'incontrario suonerebbe come qualcosa che si avvita. */
  let p = finTraz;
  while (p < finLac) {
    const u = (p - finTraz) / (finLac - finTraz);
    granello(p, (sr * (.0012 + Math.random() * .0035)) | 0,
             (.32 + Math.random() * .55 * ruvido) * (1 - u * .55));
    const passo = .0016 + u * u * .011 + Math.random() * .004;
    p += Math.max(24, (sr * passo) | 0);
  }

  // 3. LO SCHIOCCO: si e' staccata
  granello(finLac, (sr * .012) | 0, .95);

  // 4. le ultime fibre, in ritardo e sparse
  for (let q = finLac + ((sr * .012) | 0); q < n; q += (sr * (.008 + Math.random() * .03)) | 0)
    granello(q, (sr * .002) | 0, .10 + Math.random() * .16);

  return buf;
}

/**
 *  IL GRANO DELLA FRITTURA.
 *
 *  Friggere e' un rumore di fondo con dentro CENTINAIA DI SCOPPIETTII al
 *  secondo, ognuno minuscolo: sono bolle che si aprono. Un passa-banda che
 *  scende su rumore continuo — quel che c'era prima — da un frullio, un
 *  soffio che cala, e non ha nessuno scoppiettio dentro: e' esattamente la
 *  differenza fra sentir friggere e sentir soffiare.
 *
 *  Le ampiezze hanno la coda lunga apposta (una potenza quarta): quasi tutti
 *  gli scoppietti sono impercettibili e ogni tanto ne salta fuori uno grosso.
 *  Distribuirli uniformi darebbe una grattugia, non una padella.
 */
function _bufferFrittura(ctx, dur, densita) {
  const sr = ctx.sampleRate, n = Math.ceil(sr * dur) + 64;
  const buf = ctx.createBuffer(1, n, sr);
  const d = buf.getChannelData(0);

  // l'olio: un sibilo di fondo che ondeggia piano
  let lento = 0;
  for (let i = 0; i < n; i++) {
    lento += .0006 * ((Math.random() * 2 - 1) - lento * 6);
    d[i] = (Math.random() * 2 - 1) * (.05 + Math.abs(lento) * 9);
  }

  // e le bolle
  const quante = Math.floor(dur * (280 + densita * 420));
  for (let k = 0; k < quante; k++) {
    const p = (Math.random() * (n - 80)) | 0;
    const lung = Math.max(8, (sr * (.0003 + Math.random() * .0011)) | 0);
    const r = Math.random();
    const amp = .10 + r * r * r * r * 1.5;      // coda lunga: pochi scoppi grossi
    for (let i = 0; i < lung; i++)
      d[p + i] += amp * Math.exp(-7 * i / lung) * (Math.random() * 2 - 1);
  }
  return buf;
}

/**
 *  IL GRANO DELLA SCARICA.
 *
 *  Un arco elettrico non e' una nota che scende: e' un contatto che si rompe e
 *  si riprende centinaia di volte al secondo, a caso. La versione prima era un
 *  dente di sega che cascava da 1400 a 90 hertz, ed e' la figura del raggio
 *  laser dei cartoni — discendente, intonata, continua. Una scarica vera non
 *  ha nessuna delle tre: sta in alto, non ha altezza, ed e' fatta a pezzi.
 *
 *  Il buffer ha tre cose sovrapposte:
 *    1. lo SCHIANTO iniziale, quasi un impulso: due millesimi e via;
 *    2. l'ARCO che sputa, rumore acceso e spento a tratti irregolari — e' il
 *       contatto che salta, ed e' tutto qui il carattere elettrico;
 *    3. le SCINTILLE, clic isolati che continuano mentre l'arco si spegne.
 */
function _bufferScarica(ctx, dur, caos) {
  const sr = ctx.sampleRate, n = Math.ceil(sr * dur) + 64;
  const buf = ctx.createBuffer(1, n, sr);
  const d = buf.getChannelData(0);

  // 1. lo schianto
  const sch = (sr * .0022) | 0;
  for (let i = 0; i < sch; i++)
    d[i] += Math.exp(-9 * i / sch) * (Math.random() * 2 - 1);

  /*  2. l'arco. Ogni tratto dura da mezzo a cinque millesimi e puo' essere
   *  acceso o spento: e' la discontinuita' a suonare elettrica, e piu' spesso
   *  si spegne piu' l'arco sembra instabile. */
  let p = sch;
  const acceso = .72 - caos * .22;
  while (p < n) {
    const lung = Math.max(16, (sr * (.0005 + Math.random() * .0048)) | 0);
    if (Math.random() < acceso) {
      const e = Math.exp(-1.9 * p / n);       // l'arco dura, non si spegne subito
      const amp = (.22 + Math.random() * .7) * e;
      for (let i = 0; i < lung && p + i < n; i++) d[p + i] += amp * (Math.random() * 2 - 1);
    }
    p += lung;
  }

  /*  3. le scintille: clic corti e isolati, sempre piu' radi. Sono loro a far
   *  durare la scarica nell'orecchio dopo che l'arco e' finito. */
  for (let q = sch; q < n; ) {
    const e = 1 - q / n;
    const lung = (sr * (.0004 + Math.random() * .0012)) | 0;
    const amp = (.3 + Math.random() * .6) * e * e;
    for (let i = 0; i < lung && q + i < n; i++)
      d[q + i] += amp * Math.exp(-6 * i / lung) * (Math.random() * 2 - 1);
    q += Math.max(64, (sr * (.004 + Math.random() * .05 * (1 - e))) | 0);
  }
  return buf;
}

/**
 *  LO STRAPPO: un tentacolo ha portato via una cellula.
 *
 *  Sopra la grana ci vanno due colorazioni dello stesso buffer, in parallelo:
 *  una BANDA LARGA che scende, che e' la parte secca dello strappo, e un
 *  PASSA-BASSO RISONANTE che scende piu' in fretta, che e' quel che lo fa
 *  sentire bagnato invece che di carta. Sotto, il CEDIMENTO: una nota grave
 *  che casca, il peso della cosa che si stacca.
 *
 *  La taglia della cellula persa allunga e abbassa tutto: portar via una
 *  cellula grossa non e' lo stesso suono piu' forte, e' un suono piu' cupo.
 */
function audioStrappo(cr, pos, grande) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  if (!_quiSiSente(cr, pos)) return;
  if (audio.colpiOra > COLPI_TETTO.strappo) return;
  audio.colpiOra++;
  const ctx = audio.ctx, ora = ctx.currentTime;
  const t = cr ? timbroDi(cr) : null;
  const alt = t ? clamp(t.base / 90, .55, 2.2) : 1;
  const ruvido = t ? clamp(.5 + t.dist, .5, 1.4) : .8;
  const g = clamp(grande || .1, .04, .2) / .1;          // il raggio della cellula persa
  const dur = (.17 + Math.random() * .07) * (.8 + g * .3);
  const b = _colpoBus(pos, .5, .28, 1.15 * volPerc(audio.vol.colpi));

  const src = ctx.createBufferSource();
  src.buffer = _bufferStrappo(ctx, dur, ruvido);
  src.playbackRate.value = clamp(alt / (.75 + g * .35), .55, 1.9);

  // secco: la banda larga che scende mentre lo strappo procede
  const bp = ctx.createBiquadFilter();
  bp.type = 'bandpass'; bp.Q.value = .9;
  bp.frequency.setValueAtTime(2600 * alt, ora);
  bp.frequency.exponentialRampToValueAtTime(620 * alt, ora + dur);
  const gs = ctx.createGain(); gs.gain.value = 1.5;
  src.connect(bp).connect(gs).connect(b.ing);

  /*  bagnato: un risonante che casca. Senza questo lo strappo e' di carta;
   *  con questo e' di qualcosa che era vivo. */
  const lp = ctx.createBiquadFilter();
  lp.type = 'lowpass'; lp.Q.value = 7;
  lp.frequency.setValueAtTime(1700 * alt, ora);
  lp.frequency.exponentialRampToValueAtTime(240 * alt, ora + dur * .85);
  const gb = ctx.createGain(); gb.gain.value = .9;
  src.connect(lp).connect(gb).connect(b.ing);

  // il cedimento: il peso che si stacca
  const o = ctx.createOscillator(); o.type = 'triangle';
  o.frequency.setValueAtTime(130 * alt, ora + dur * .6);
  o.frequency.exponentialRampToValueAtTime(38 * alt, ora + dur * .6 + .16);
  const og = ctx.createGain();
  og.gain.setValueAtTime(0, ora);
  og.gain.setValueAtTime(0, ora + dur * .6);
  og.gain.linearRampToValueAtTime(.5 * g, ora + dur * .6 + .008);
  og.gain.exponentialRampToValueAtTime(.001, ora + dur * .6 + .2);
  o.connect(og).connect(b.ing);

  src.start(ora); o.start(ora); o.stop(ora + dur + .3);
  b.pulisci(dur + .45);
}

/**
 *  LO SLURP: l'esserino sta assorbendo un boccone.
 *
 *  Il carattere «risucchio» sta tutto in UNA cosa: un passa-basso RISONANTE
 *  il cui taglio sale in fretta. E' la stessa figura che fa una bocca che si
 *  chiude su qualcosa di bagnato, e a orecchio non ha alternative — nessuna
 *  quantita' di rumore filtrato in modo statico suona come un risucchio.
 *  Sotto c'e' la deglutizione, una sinusoide che scende.
 *
 *  Si ripete finche' mangia, ma non piu' di una volta ogni mezzo secondo: la
 *  digestione avviene a ogni fotogramma, e senza freno sarebbe un ronzio.
 */
function audioPasto(cr, pos) {
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') return;
  if (!cr) return;
  if (!_quiSiSente(cr, pos)) return;
  const ctx = audio.ctx, ora = ctx.currentTime;
  const ult = audio.ultimoPasto.get(cr) || 0;
  if (ora - ult < .55 + Math.random() * .45) return;
  audio.ultimoPasto.set(cr, ora);
  if (audio.colpiOra > COLPI_TETTO.pasto) return;
  audio.colpiOra++;

  const t = timbroDi(cr);
  /*  L'ALTEZZA LA FA LA TAGLIA, non il genoma. Una gola grande e' una cavita'
   *  grande e risuona piu' in basso: e' la stessa regola della voce e del
   *  lamento, e prima qui non c'era — l'inghiottimento usciva alla stessa
   *  altezza per una bestiola da otto cellule e per un colosso. Il genoma ci
   *  mette solo una sfumatura, perche' fra due gole della stessa misura la
   *  differenza c'e' ma e' piccola. */
  const tg = clamp(fattoreTaglia(cr) / TAGLIA_RIF, .45, 3.2);
  const alt = clamp(Math.pow(tg, .62) * (.8 + clamp(t.base / 160, .1, .8) * .3), .5, 2.3);
  const b = _colpoBus(pos || cr.centroid, .28, .14, .45 * volPerc(audio.vol.colpi));

  /*  INGHIOTTIRE, non risucchiare. La differenza fra i due sta in un dettaglio
   *  solo, ed e' la DIREZIONE della risonanza: risucchiando la cavita' si
   *  stringe e il picco sale, inghiottendo il boccone scende in gola e il
   *  picco casca.
   *
   *  E una deglutizione vera ha DUE tempi: la gola si chiude e spinge, poi si
   *  riapre e finisce di far passare. E' quel secondo colpo, piu' piccolo e
   *  piu' grave del primo, a rendere il suono riconoscibile — con un colpo
   *  solo resta un «blop» qualunque.
   *
   *  MA NON E' UN COLPO. La prima versione attaccava in dodici millesimi con
   *  una risonanza a Q venti: quella e' la ricetta di un impulso, e infatti
   *  schioccava. Una gola e' fatta di carne bagnata, non ha spigoli e non
   *  parte di scatto — quindi attacchi lunghi quattro volte tanto, risonanze
   *  larghe la meta', e tutto quanto sotto un passa-basso comune che toglie
   *  la parte alta del rumore, che e' proprio quella che si sente come clic. */
  const morbido = ctx.createBiquadFilter();
  /*  Il tetto va alzato insieme a tutto il resto, o taglierebbe proprio la
   *  parte dove adesso arrivano le risonanze. Resta comunque un tetto: serve
   *  a togliere la punta del rumore bianco, che e' quel che si sente come
   *  clic, non a scurire il suono. */
  morbido.type = 'lowpass'; morbido.frequency.value = 950 * alt; morbido.Q.value = .5;
  /*  E una dissolvenza in entrata su TUTTO, dopo il filtro: qualunque cosa
   *  faccia il pezzo che c'e' sotto, l'inizio del suono e' comunque rotondo.
   *  E' l'unico modo di essere sicuri che non resti un fronte da qualche
   *  parte — basta un componente che attacchi secco per far tornare il
   *  tamburo, e cercarlo a orecchio uno alla volta e' una perdita di tempo. */
  const entrata = ctx.createGain();
  entrata.gain.setValueAtTime(0, ora);
  entrata.gain.setTargetAtTime(1, ora, .011);
  morbido.connect(entrata).connect(b.ing);

  /*  IL GLUG E' UNA SINUSOIDE, non piu' rumore filtrato.
   *
   *  Erano due modi di ottenere la stessa figura — un picco che si sposta — ma
   *  non suonano affatto uguali: un passa-basso risonante su rumore bianco
   *  lascia comunque passare tutto il resto dello spettro, e quel resto e'
   *  fruscio. Con l'oscillatore c'e' solo la riga che si muove e nient'altro.
   *  Il rumore resta, ma sotto e appena accennato: serve a dare la grana di
   *  una cosa bagnata, non a fare il suono.
   *
   *  Gli inviluppi sono CURVE e non rampe: `setTargetAtTime` sale in modo
   *  esponenziale e la sua pendenza iniziale e' finita, mentre una rampa
   *  lineare parte con uno spigolo — e lo spigolo si sente come una pelle
   *  percossa anche quando la rampa dura decine di millesimi. */
  const glug = (t0, forza, da, a, quanto, grana) => {
    const o = ctx.createOscillator(); o.type = 'sine';
    /*  IL BEND E' LINEARE, e non e' un dettaglio. `setTargetAtTime` fa quasi
     *  tutto il salto nei primi millesimi e poi si trascina verso il bersaglio
     *  senza arrivarci: si sente uno scatto seguito da una coda ferma. La
     *  rampa lineare si muove alla stessa velocita' dall'inizio alla fine e
     *  arriva davvero — ed e' quella la sensazione di una cosa che risale la
     *  gola, un movimento solo, continuo, che finisce. */
    o.frequency.setValueAtTime(da * alt, t0);
    o.frequency.linearRampToValueAtTime(a * alt, t0 + quanto);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0, t0);
    g.gain.setTargetAtTime(forza, t0, quanto * .26);
    g.gain.setTargetAtTime(0, t0 + quanto * .78, quanto * .40);
    o.connect(g).connect(morbido);
    o.start(t0); o.stop(t0 + quanto * 2.2);

    const n = _sorgenteRumore();
    const lp = ctx.createBiquadFilter();
    lp.type = 'bandpass'; lp.Q.value = 2.2;
    lp.frequency.setValueAtTime(da * alt, t0);
    lp.frequency.linearRampToValueAtTime(a * alt, t0 + quanto);
    const ng = ctx.createGain();
    ng.gain.setValueAtTime(0, t0);
    ng.gain.setTargetAtTime(forza * grana, t0, quanto * .26);
    ng.gain.setTargetAtTime(0, t0 + quanto * .6, quanto * .34);
    n.connect(lp).connect(ng).connect(morbido);
    n.start(t0); n.stop(t0 + quanto * 2);
  };

  // 1. il primo tempo: la gola si chiude e spinge giu'
  /*  E LA RISONANZA SALE. La cavita' si stringe mentre il boccone passa
   *  invece di allargarsi: e' il gesto opposto a quello di prima, e a orecchio
   *  legge come qualcosa che tira su invece che come qualcosa che cala.
   *  Tutto dura anche la meta': un boccone e' un attimo. */
  /*  Partenza in mezzo, arrivo appena SOPRA: lo scarto resta meno di una
   *  terza, cambia solo il verso. Le versioni con salti larghi — in su o in
   *  giu' — suonavano tutte come qualcosa di percosso o di risucchiato; con un
   *  movimento piccolo resta solo la cavita' che cambia forma, che e' quel che
   *  fa una gola, e il verso decide se si chiude o si apre. */
  const d1 = .042 + Math.random() * .016;
  glug(ora, .40, 300, 418, d1, .15);

  /*  2. LA DISCESA. Una nota grave che casca mentre il boccone passa: e' la
   *  colonna d'aria sopra a farsi piu' lunga, e senza di lei i due glug non
   *  sono collegati da niente e si sentono come due schiocchi separati.
   *  Sinusoide e non triangolo: il triangolo ha armoniche fino in cima e a
   *  volume basso sono proprio loro a dare il bordo duro.
   *
   *  E VA IN SU ANCHE LEI, di una quinta scarsa. Il salto resta piccolo di
   *  proposito: era la CADUTA larga — 165 hertz che diventavano 44 — a far
   *  sentire il tamburo, e una salita larga farebbe lo stesso difetto al
   *  contrario. Cosi' invece si sente il verso della gola che si stringe e
   *  non una nota intonata. */
  const o = ctx.createOscillator(); o.type = 'sine';
  o.frequency.setValueAtTime(145 * alt, ora);
  o.frequency.linearRampToValueAtTime(188 * alt, ora + .05);
  const og = ctx.createGain();
  og.gain.setValueAtTime(0, ora);
  og.gain.setTargetAtTime(.10, ora, .016);          // sale in curva, non a rampa
  og.gain.setTargetAtTime(0, ora + .04, .03);
  o.connect(og).connect(morbido);
  o.start(ora); o.stop(ora + .15);

  // 3. il secondo tempo, piu' tardi e piu' in basso: la gola si riapre
  const t2 = ora + d1 * .8 + .012 + Math.random() * .012;
  glug(t2, .20, 235, 325, .034 + Math.random() * .014, .12);

  /*  4. e il residuo bagnato, che e' quel che distingue una gola da un tubo. */
  const nr = _sorgenteRumore();
  const lr = ctx.createBiquadFilter();
  lr.type = 'lowpass'; lr.Q.value = 1.6; lr.frequency.value = 420 * alt;
  const gr = ctx.createGain();
  gr.gain.setValueAtTime(0, t2);
  gr.gain.setTargetAtTime(.035, t2, .012);
  gr.gain.setTargetAtTime(0, t2 + .035, .026);
  nr.connect(lr).connect(gr).connect(morbido);
  nr.start(t2); nr.stop(t2 + .13);

  b.pulisci(.35);
}

/* --- pannello dei volumi -------------------------------------------------
 *  Tre cursori e nient'altro: le manopole del timbro non stanno qui perche'
 *  non sono dell'utente, sono del genoma. Qui si decide solo quanto forte.
 * ---------------------------------------------------------------------- */
function costruisciPannelloAudio() {
  const host = document.getElementById('audioBody');
  if (!host) return;
  host.innerHTML = '';
  const righe = [
    { k: 'master', n: 'Master', d: 'quanto forte in tutto' },
    { k: 'voci',   n: 'Voices', d: 'i versi degli esserini' },
    { k: 'colpi',  n: 'Attacks & pain', d: 'i colpi e i lamenti' },
  ];
  for (const r of righe) {
    const riga = document.createElement('div');
    riga.className = 'gene';
    riga.title = r.d;
    riga.innerHTML = `<div class="lab">${r.n}<b>${audio.vol[r.k].toFixed(2)}</b></div>`;
    const inp = document.createElement('input');
    inp.type = 'range'; inp.min = 0; inp.max = 1; inp.step = .01;
    inp.value = audio.vol[r.k];
    inp.oninput = () => {
      const v = parseFloat(inp.value);
      audio.vol[r.k] = v;
      if (r.k === 'master' && audio.master)
        audio.master.gain.setTargetAtTime(volPerc(v), audio.ctx.currentTime, .05);
      riga.querySelector('b').textContent = v.toFixed(2);
    };
    inp.onchange = salvaAudio;
    riga.appendChild(inp);
    host.appendChild(riga);
  }
  const ora = document.createElement('div');
  ora.id = 'audioNow';
  host.appendChild(ora);
  const cv = document.createElement('canvas');
  cv.id = 'audioFrase';
  cv.title = 'The phrase this creature is singing: bars are notes, dashes are rests, '
           + 'the lit column is where it is now.';
  host.appendChild(cv);
  _fraseUltimo = '';
  _oraAudioTesto = '';                       // il riquadro e' nuovo, va riscritto
  aggiornaOraAudio(audio.acceso ? _ascoltatoDaSolo() : null);
  aggiornaFraseAudio(audio.acceso ? _ascoltatoDaSolo() : null);

  const nota = document.createElement('div');
  nota.className = 'q';
  nota.innerHTML = 'Every creature\u2019s voice is <b>synthesised from its genome</b>: three '
                 + 'drifting frequencies, ring modulation, two formants and a gurgle, through '
                 + 'a shared reverb and echo. Size sets the pitch, symmetry sets whether the '
                 + 'three tones agree or beat, aggression sets how dirty it is. '
                 + 'Attacks and cries of pain are synthesised too \u2014 the cry is that same '
                 + 'voice, wrung out.<br><br>'
                 + '<b>Hover a creature to hear it alone.</b> Everything else goes silent '
                 + 'while the pointer is on it \u2014 the only practical way to make out one '
                 + 'voice when seven are singing at once. Looking into a single vessel also '
                 + 'mutes the other vessels.';
  host.appendChild(nota);
}

/*  Ultima riga scritta, per non toccare il DOM sessanta volte al secondo
 *  scrivendoci sempre la stessa cosa. */
let _oraAudioTesto = '';
let _fraseUltimo = '';      // esserino + passo gia' disegnati

/**
 *  IL GRAFICO DELLA FRASE, mentre si isola un esserino.
 *
 *  Sedici colonne, una per passo della battuta, e ognuna dice cosa succede li':
 *  barra piena = nota, e l'altezza e' il grado con l'ottava; trattino in basso
 *  = pausa. La colonna accesa e' quella che sta suonando adesso.
 *
 *  Il colore e' il PIGMENTO dell'esserino, la stessa tinta che ha addosso in
 *  vasca: cosi' il disegnino non e' un grafico generico, e' il suo — se ne
 *  isoli due di fila si vede subito che sono due bestie diverse anche senza
 *  leggere il nome.
 *
 *  Costa un `clearRect` e sedici rettangoli, e solo quando cambia il passo:
 *  una volta ogni trecento millesimi scarsi, non a ogni fotogramma.
 */
function disegnaFrase(cv, cr) {
  const t = timbroDi(cr), g = cv.getContext('2d');
  if (!g) return;
  const rap = Math.min(2, window.devicePixelRatio || 1);
  const L = Math.round(cv.clientWidth * rap), A = Math.round(cv.clientHeight * rap);
  if (!L || !A) return;
  if (cv.width !== L || cv.height !== A) { cv.width = L; cv.height = A; }

  const passo = Math.floor(audio.ctx.currentTime / (PASSO_DUR * t.divisione));
  const qui = ((passo % PASSI_FRASE) + PASSI_FRASE) % PASSI_FRASE;

  const p = clamp((cr.dna && cr.dna.hue) || 0, 0, 1);
  const tinta = p > 0 ? `hsl(${Math.round(p * 360)} 72% 62%)` : '#8fd8cf';
  const spenta = p > 0 ? `hsl(${Math.round(p * 360)} 40% 34%)` : '#3d5c58';

  g.clearRect(0, 0, L, A);
  g.fillStyle = 'rgba(255,255,255,.035)';
  g.fillRect(0, 0, L, A);

  const w = L / PASSI_FRASE, base = A - 3 * rap;
  /*  Le colonne interne a una nota lunga non hanno un evento proprio: si
   *  trascina l'ultimo visto, o una nota da quattro passi si vedrebbe come
   *  una barra sola seguita da tre buchi. */
  let ev = null;
  for (let i = 0; i < PASSI_FRASE; i++) {
    const inizio = t.griglia[i];
    if (inizio) ev = inizio;
    const x = i * w, acceso = i === qui;
    if (!ev || ev.pausa) {
      g.fillStyle = acceso ? tinta : 'rgba(255,255,255,.13)';
      g.fillRect(x + w * .3, base - 1 * rap, w * .4, 1.5 * rap);
    } else {
      // grado 0..2 e ottava: dove sta la nota nella gola dell'esserino
      const q = (ev.grado + 1) / 3 * (ev.ott === 2 ? 1 : ev.ott === .5 ? .45 : .72);
      const h = Math.max(3 * rap, (base - 3 * rap) * clamp(q, .12, 1));
      g.fillStyle = acceso ? tinta : (inizio ? spenta : 'rgba(255,255,255,.10)');
      g.fillRect(x + w * .16, base - h, w * .68, h);
    }
  }
  // il segnaposto: dove siamo dentro la battuta
  g.fillStyle = 'rgba(255,255,255,.10)';
  g.fillRect(qui * w, 0, w, A);
}

/**
 *  CHI STIAMO SENTENDO, scritto nel pannello.
 *
 *  Le regole su chi suona sono tre sovrapposte — il puntatore, il recipiente
 *  a fuoco, i piu' vicini alla camera — e messe insieme diventano difficili da
 *  indovinare a orecchio: uno sente due voci e non sa se le altre tacciono
 *  perche' sono lontane, perche' sono in un'altra vasca o perche' ha il mouse
 *  fermo su qualcosa. Scritto, non c'e' niente da indovinare.
 *
 *  I nomi finiscono in `textContent` e non in `innerHTML`: un esserino si puo'
 *  rinominare, e un nome e' testo di chi lo usa, non marcatura.
 */
function aggiornaOraAudio(solo) {
  const el = document.getElementById('audioNow');
  if (!el) return;
  const voci = [...audio.voci.keys()];
  let pezzi, solistico = false;
  if (!audio.acceso || !audio.pronto || audio.ctx.state !== 'running') {
    pezzi = ['Sound is off.'];
  } else if (solo) {
    pezzi = ['Hearing ', { b: solo.name }, ' alone \u2014 the pointer is on it.'];
    solistico = true;
  } else if (!voci.length) {
    pezzi = ['Nothing in earshot.'];
  } else {
    const mostra = Math.min(voci.length, 4), resto = voci.length - mostra;
    pezzi = ['Hearing '];
    for (let i = 0; i < mostra; i++) {
      if (i) pezzi.push(i === mostra - 1 && !resto ? ' and ' : ', ');
      pezzi.push({ b: voci[i].name });
    }
    if (resto) pezzi.push(' and ' + resto + ' more');
    pezzi.push(' \u2014 the nearest');
    if (world.focus) { pezzi.push(' in '); pezzi.push({ b: world.focus.name }); pezzi.push('.'); }
    else pezzi.push(' to the camera.');
  }
  const firma = pezzi.map(p => (typeof p === 'string' ? p : '\u0001' + p.b)).join('');
  if (firma === _oraAudioTesto) return;
  _oraAudioTesto = firma;
  el.textContent = '';
  for (const p of pezzi) {
    if (typeof p === 'string') { el.appendChild(document.createTextNode(p)); continue; }
    const b = document.createElement('b'); b.textContent = p.b; el.appendChild(b);
  }
  el.classList.toggle('solo', solistico);
}

/*  Il grafico segue la riga, ma con una sua ragione per ridisegnarsi: cambia
 *  solo quando cambia il passo o l'esserino isolato. */
function aggiornaFraseAudio(solo) {
  const cv = document.getElementById('audioFrase');
  if (!cv) return;
  cv.classList.toggle('on', !!solo);
  if (!solo) { _fraseUltimo = ''; return; }
  const t = timbroDi(solo);
  const passo = Math.floor(audio.ctx.currentTime / (PASSO_DUR * t.divisione)) % PASSI_FRASE;
  const chiave = solo.id + ':' + passo;
  if (chiave === _fraseUltimo) return;
  _fraseUltimo = chiave;
  disegnaFrase(cv, solo);
}

/*  Lo stato dell'interruttore, letto dalla realta' e non dal bottone:
 *  l'etichetta dice com'e' il suono adesso, e la tinta accesa la mostra. */
function aggiornaInterruttoreAudio() {
  const b = document.getElementById('audioOnOff');
  if (!b) return;
  b.textContent = audio.acceso ? 'On' : 'Off';
  b.classList.toggle('on', audio.acceso);
}

function apriPannelloAudio(on) {
  const p = document.getElementById('audiopanel');
  if (!p) return;
  p.classList.toggle('on', on);
  if (on) pannelloInCima(p);
  const b = document.getElementById('btnAudio');
  if (b) b.classList.toggle('on', on);
  if (on) { costruisciPannelloAudio(); aggiornaInterruttoreAudio(); }
}

function salvaAudio() {
  try {
    localStorage.setItem(AUDIO_CHIAVE, JSON.stringify({ ...audio.vol, acceso: audio.acceso }));
  } catch (e) { /* spazio finito o modalita' privata */ }
}

/*  I volumi si riprendono, l'ACCENSIONE no: il contesto audio vuole un gesto
 *  dell'utente, e riaccenderlo da solo al caricamento produrrebbe soltanto un
 *  contesto sospeso che non si sente. L'interruttore riparte spento: il
 *  contesto sarebbe ripreso, ma muto. */
function riprendiAudio() {
  let d = null;
  try { d = JSON.parse(localStorage.getItem(AUDIO_CHIAVE)); } catch (e) { return; }
  if (!d) return;
  for (const k of ['master', 'voci', 'colpi'])
    if (typeof d[k] === 'number' && isFinite(d[k])) audio.vol[k] = clamp(d[k], 0, 1);
}

function frame(dt) {
  lastFrameT = performance.now();

  /*  In EDIT, trascinando, non si fa NESSUN passo: la cellula in mano la
   *  sposta il puntatore, tutto il resto resta dov'è. L'accumulatore si azzera,
   *  o al rilascio il tempo arretrato verrebbe recuperato in un colpo solo e
   *  l'esserino schizzerebbe. */
  tempoFermo = editMode && drag.active;
  if (tempoFermo) {
    acc = 0;
  } else if (!world.paused) {
    acc += dt * world.speed;
    let steps = 0;
    while (acc >= FIXED && steps < 6) { world.step(FIXED); acc -= FIXED; steps++; }
    if (acc > FIXED * 6) acc = 0;
  } else {
    /*  Il passo singolo del debugger: esattamente un passo di simulazione,
     *  poi si torna fermi. Va prima del trascinamento perche' e' un comando
     *  esplicito, e va qui e non altrove perche' `world.step` deve girare una
     *  volta sola per fotogramma disegnato — chiamandolo dal bottone il passo
     *  sarebbe avvenuto senza che nessuno lo disegnasse. */
    if (bpPassiSingoli > 0) { bpPassiSingoli--; world.step(FIXED); }
    // in pausa la fisica gira comunque piano, così il drag con IK resta reattivo
    else if (drag.active) world.step(FIXED * .5);
  }

  avanzaBattito();
  // La barra in basso conta esserini, cellule e cibo: numeri che cambiano da
  // soli mentre il mondo gira, mentre finora si aggiornava solo a comando.
  // Due secondi bastano a tenerla onesta senza ricostruire il DOM di continuo.
  if (performance.now() - _ultimoRinfrescoVasche > 2000) {
    _ultimoRinfrescoVasche = performance.now();
    ui.refreshVesselsLight();
    torneoEtichetta();               // pausa e avanzamento si vedono da fuori
  }
  syncViewport();
  updateCamera(dt);
  audioAggiorna(dt);                     // dopo la telecamera: l'ascoltatore e' lei
  if (viewOk) {                          // vista degenere: non si disegna nulla
    syncBlobs(world);
    resetCoperture(world);
    syncMesh(world);
    syncSpline(world);
    syncInstances(world);
    syncStruts(world);
    syncEffects(world);
    syncSenseLines(world);
    syncAuras(world);
    syncLabels(world);
    syncAnelloSel();
    aggiornaTilt();
    composer.render();
    fantasmiSopraTutto();
  }

  frames++; fpsT += dt;
  if (fpsT > .5) { fps = frames / fpsT; frames = 0; fpsT = 0; updateStats(); }
  uiT += dt;
  if (uiT > .6) { uiT = 0; if (world.selected) ui.refreshInspectorLight(); }
}

function animate() {
  requestAnimationFrame(animate);
  frame(Math.min(clock.getDelta(), .1));
}

// se il frame non arriva entro 250 ms ma la pagina è visibile, disegniamo noi
setInterval(() => {
  if (document.hidden) return;
  const idle = performance.now() - lastFrameT;
  if (idle < 250) return;
  clock.getDelta();                     // azzera il clock: il rAF non conteggi due volte
  frame(Math.min(idle / 1000, .2));
}, 120);

/**
 *  AGGIORNAMENTO PERIODICO DEL PANNELLO DI DESTRA.
 *
 *  Prima ricostruiva tutto: `innerHTML = ''` e poi da capo cursori del genoma,
 *  pulsanti, pastiglie e righe vitali, sessanta volte al minuto. Di quella roba
 *  cambia da sola solo una parte — i numeri vitali e i conteggi della
 *  composizione — mentre cursori e pulsanti cambiano solo quando è l'utente a
 *  toccarli, e allora il pannello si rifà per conto suo.
 *
 *  Ora si riscrivono i soli testi che sono cambiati. Quando compare o sparisce
 *  un tipo di cellula si rifanno le sole pastiglie della composizione. La
 *  ricostruzione completa resta per i due casi in cui il pannello parla
 *  davvero di un altro: cambia l'esserino selezionato, oppure quello che c'era
 *  muore.
 */
ui.refreshInspectorLight = function () {
  const cr = world.selected;
  if (!cr) return;
  const host = document.getElementById('inspBody');
  if (!host.querySelector('.sec')) return;

  // un altro esserino, o lo stesso che nel frattempo è morto: struttura diversa
  if (this._pannelloDi !== cr || this._pannelloVivo !== cr.alive) {
    this.refreshInspector();
    return;
  }
  if (this._aggiornaVitali) this._aggiornaVitali();
  if (this._aggiornaComposizione) this._aggiornaComposizione();
};

function updateStats() {
  let cells = 0, alive = 0, corpses = 0, food = 0;
  for (const v of world.vessels) {
    for (const c of v.creatures) { cells += c.cells.length; if (c.alive) alive++; else corpses++; }
    food += v.food.length;
  }
  const blob = world._blobRes ? `   tessuto ${world._blobRes}³` : '';
  document.getElementById('stats').textContent =
    `${fps.toFixed(0)} fps   cells ${cells}   creatures ${alive}   remains ${corpses}   food ${food}${blob}   t ${world.time.toFixed(0)}s`;
}

animate();
setTimeout(() => {
  const l = document.getElementById('loading');
  l.style.opacity = 0;
  setTimeout(() => l.remove(), 600);
}, 350);

world.log('Culture ready. <b>Double-click</b> a vessel to step inside.');

// handle di debug dalla console del browser: CELLS.world, CELLS.ui, …
window.CELLS = {
  world, ui, THREE, CELL_TYPES, GENES, PRESETS, focusVessel, buildFromRecipe, ricettaScalata, scene, camera, renderer, controls, cam,
  audio, timbroDi, audioAttacco, audioDolore, audioStrappo, audioPasto,
  // il cervello scritto a mano: caricarlo e fermarlo anche da console
  avviaBrainProgram, fermaBrainProgram, BrainProgram, Vec,
  bilanciaScudo, SCUDO_R_MIN, SCUDO_K,
  alberoDi, alberoPiatto, NodoCorpo,
  // e il suo debugger: strumentazione, editor, punti d'arresto
  apriPannelloDebug, chiudiPannelloDebug, bpStrumenta, bpScansiona, bpEvidenzia, bpNomiLocali,
  apriPannelloDoc, chiudiPannelloDoc,
  accendiPOV, spegniPOV, get povOn() { return povOn; }, get povCreature() { return povCreature; },
  pannelliDebug, PannelloDebug, bpConsole,
  // i due suoni scritti campione per campione, esposti per poterli ispezionare
  _bufferStrappo, _bufferScarica, _bufferFrittura, audioMorte,
  get consumo() { return CONSUMO; }, set consumo(v) { CONSUMO = v; },
  // esegue un frame completo a mano (utile per il debug a passo singolo)
  tick(dt = 1 / 60) {
    avanzaBattito();
    syncViewport(); updateCamera(dt);
    if (!viewOk) return;
    syncBlobs(world, true); resetCoperture(world); syncMesh(world); syncSpline(world);
    syncInstances(world); syncStruts(world);
    syncEffects(world); syncSenseLines(world); syncAuras(world);
    syncLabels(world); syncAnelloSel(); aggiornaTilt(); composer.render(); fantasmiSopraTutto();
  },
};
